insert into public.mushroom_lookalikes_i18n (edible_slug,lookalike_slug,lang,visual_differences,smell_differences,habitat_differences,spore_print_differences,pro_tip,key_differences,verified) values 
('agaricus_augustus','agaricus_moelleri','en','The prince (Agaricus augustus) with a brownish-scaly cap that yellows under pressure, large; inky mushroom grey-brown spotted, guineafowl-like, smaller.','The prince: anise/bitter almond. Inky mushroom: carbolic/ink, unpleasant when cooked. The smell is the central distinguishing feature.','The prince at path edges, in coniferous forest, on compost; inky mushroom parks/gardens/forest edge. Overlap possible near settlements.','Both chocolate-brown — NOT a distinguishing feature.','The carbolic smell and chrome-yellow stem base are the unmistakable sign of the toxic mushroom — when in doubt, discard the entire find, do not rely on size.','{"The prince (Agaricus augustus) smells pleasantly of anise/bitter almond; the inky mushroom of carbolic/ink","The stem base of the inky mushroom turns immediately and strongly chrome-yellow; the prince yellows only faintly/on the outside","The prince with a brownish-scaly (not grey-spotted) cap that yellows pleasantly under pressure; the inky mushroom grey-brown guineafowl-mottled","When heated anise aroma (edible) vs ink/carbolic smell (toxic)","The prince grows very large (cap often 10-25 cm); but striking size alone is NOT proof of safety — smell + stem base remain mandatory"}',false),
('agaricus_augustus','agaricus_moelleri','es','Champiñón gigante (Agaricus augustus) con sombrero parduzco-escamoso que amarillea a la presión, grande; champiñón perlado gris-pardo moteado, como una pintada, más pequeño.','Champiñón gigante: anís/almendra amarga. Champiñón perlado: fenol/tinta, desagradable al cocinar. El olor es el criterio de distinción central.','Champiñón gigante en los bordes de los caminos, en bosque de coníferas, sobre compost; champiñón perlado parques/jardines/borde del bosque. Solapamiento posible cerca de los asentamientos.','Ambos marrón chocolate — NO es un criterio de distinción.','El olor a fenol y la base del pie amarillo cromo son la señal inequívoca del hongo tóxico — en caso de duda, desechar toda la recolección, no fiarse del tamaño.','{"El champiñón gigante (Agaricus augustus) huele agradablemente a anís/almendra amarga; el champiñón perlado a fenol/tinta","La base del pie del champiñón perlado vira de inmediato y con fuerza a amarillo cromo; el champiñón gigante amarillea solo débilmente/por fuera","Champiñón gigante con sombrero parduzco-escamoso (no manchado de gris) que amarillea agradablemente a la presión; champiñón perlado gris-pardo moteado como una pintada","Al calentar, aroma de anís (comestible) vs olor a tinta/fenol (tóxico)","El champiñón gigante se vuelve muy grande (sombrero a menudo 10-25 cm); pero un tamaño llamativo por sí solo NO es prueba de seguridad — olor + base del pie siguen siendo obligatorios"}',false),
('agaricus_augustus','agaricus_moelleri','fr','Agaric géant (agaric impérial) à chapeau brunâtre-squameux jaunissant à la pression, grand ; agaric perlé gris-brun moucheté, comme une pintade, plus petit.','Agaric géant : anis/amande amère. Agaric perlé : phénol/encre, désagréable à la cuisson. L''odeur est le critère de distinction central.','Agaric géant au bord des chemins, en forêt de conifères, sur le compost ; agaric perlé parcs/jardins/lisière. Chevauchement possible près des habitations.','Les deux brun chocolat — PAS un critère de distinction.','L''odeur de phénol et la base du pied jaune chrome sont le signe infaillible du champignon toxique — en cas de doute, jeter toute la récolte, ne pas se fier à la taille.','{"L''agaric géant (agaric impérial) sent agréablement l''anis/l''amande amère ; l''agaric perlé le phénol/l''encre","La base du pied de l''agaric perlé vire immédiatement et fortement au jaune chrome ; l''agaric géant ne jaunit que faiblement/en surface","Agaric géant à chapeau brunâtre-squameux (non taché de gris) qui jaunit agréablement à la pression ; agaric perlé gris-brun moucheté comme une pintade","Au chauffage, arôme d''anis (comestible) vs odeur d''encre/de phénol (toxique)","L''agaric géant devient très grand (chapeau souvent 10-25 cm) ; mais une taille frappante seule n''est PAS une preuve de sûreté — odeur + base du pied restent obligatoires"}',false),
('agaricus_augustus','agaricus_moelleri','it','Prataiolo gigante (prataiolo imperiale) con cappello brunastro-squamoso che ingiallisce alla pressione, grande; prataiolo perlato grigio-bruno maculato, come una faraona, più piccolo.','Prataiolo gigante: anice/mandorla amara. Prataiolo perlato: fenolo/inchiostro, sgradevole in cottura. L''odore è il criterio distintivo centrale.','Prataiolo gigante ai margini dei sentieri, in bosco di conifere, sul compost; prataiolo perlato parchi/giardini/margini. Sovrapposizione possibile vicino agli insediamenti.','Entrambi bruno cioccolato — NON un criterio distintivo.','L''odore di fenolo e la base del gambo giallo cromo sono il segno inequivocabile del fungo velenoso — nel dubbio gettare l''intero raccolto, non affidarsi alle dimensioni.','{"Il prataiolo gigante (prataiolo imperiale) odora gradevolmente di anice/mandorla amara; il prataiolo perlato di fenolo/inchiostro","La base del gambo del prataiolo perlato vira subito e intensamente al giallo cromo; il prataiolo gigante ingiallisce solo debolmente/in superficie","Prataiolo gigante con cappello brunastro-squamoso (non macchiato di grigio) che ingiallisce gradevolmente alla pressione; prataiolo perlato grigio-bruno maculato come una faraona","Al riscaldamento profumo di anice (commestibile) vs odore di inchiostro/fenolo (velenoso)","Il prataiolo gigante diventa molto grande (cappello spesso 10-25 cm); ma una taglia vistosa da sola NON è prova di sicurezza — odore + base del gambo restano obbligatori"}',false),
('agaricus_campestris','agaricus_moelleri','en','Inky/karbolic mushroom (Agaricus moelleri) with a grey-brown spotted, guineafowl-mottled cap; field mushroom pure white to cream, smooth. Caution: both small to medium-sized, easily confused in the field.','Toxic mushroom: smell of carbolic/ink/iodine, disgustingly intensified when cooked. Field mushroom: pleasantly mushroomy and mild. Here the smell is a reliable distinguishing feature.','Inky mushroom rather in parks, gardens, at forest edges and near settlements; field mushroom on mown meadows and pastures. Habitat overlap possible, so do not rely on it alone.','Both have a chocolate-brown spore print — NOT a distinguishing feature.','On EVERY agaric, cut the stem base AND smell it: chrome-yellow staining plus a carbolic/ink smell (also test during a brief sauté) = toxic agaric, discard the entire basket contents, not just the single specimen.','{"The inky/carbolic mushroom smells unpleasantly of carbolic/ink/iodine (pharmacy, hospital), the smell intensifying and becoming sickening when heated; the field mushroom smells pleasantly mushroomy and mild","The stem base of the inky mushroom turns immediately and strongly chrome-yellow when scratched/cut (especially in the bulb area); the field mushroom at most faintly reddish/brownish","The field mushroom has pink gills from the start, later chocolate-brown (never pure white); pure white gills in a young agaric = warning sign towards the toxic agaric","Cap surface of the inky mushroom grey-brown spotted/scaly (guineafowl-mottled); field mushroom pure white to cream, smooth to scaly","The carbolic smell AND chrome-yellow stem base occur together and reliably rule out any edible agaric"}',false),
('agaricus_campestris','agaricus_moelleri','es','Champiñón perlado (Agaricus moelleri) con sombrero gris-pardo moteado, jaspeado como el plumaje de una pintada; champiñón silvestre blanco puro a crema, liso. Atención: ambos de tamaño pequeño-mediano, fácilmente confundibles en el campo.','Hongo tóxico: olor a fenol/tinta/yodo, desagradablemente intensificado al cocinar. Champiñón silvestre: agradablemente fúngico y suave. Aquí el olor es un criterio de distinción fiable.','Champiñón perlado más bien en parques, jardines, en los bordes del bosque y cerca de los asentamientos; champiñón silvestre en prados segados y pastos. Solapamiento de hábitat posible, no fiarse solo de esto.','Ambos esporada marrón chocolate — NO es un criterio de distinción.','En CADA champiñón cortar la base del pie Y olerla: viraje amarillo cromo más olor a fenol/tinta (probar también durante un breve salteado) = champiñón tóxico, desechar todo el contenido del cesto, no solo el ejemplar aislado.','{"El champiñón perlado/fenólico huele desagradablemente a fenol/tinta/yodo (farmacia, hospital), olor intensificado y nauseabundo al calentar; el champiñón silvestre huele agradablemente a hongo, suave","La base del pie del champiñón perlado vira de inmediato y con fuerza a amarillo cromo al rascarla/cortarla (sobre todo en la zona del bulbo); el champiñón silvestre como mucho débilmente rojizo/parduzco","El champiñón silvestre tiene láminas rosas desde el principio, luego marrón chocolate (nunca blanco puro); láminas blanco puro en un champiñón joven = señal de alarma hacia el champiñón tóxico","Superficie del sombrero del champiñón perlado gris-pardo moteada/escamosa (jaspeada como una pintada); champiñón silvestre blanco puro a crema, de liso a escamoso","El olor a fenol Y la base del pie amarillo cromo aparecen juntos y excluyen con certeza cualquier champiñón comestible"}',false),
('agaricus_campestris','agaricus_moelleri','fr','Agaric perlé (psalliote pintade) à chapeau gris-brun moucheté, tacheté comme un plumage de pintade ; agaric champêtre blanc pur à crème, lisse. Attention : les deux sont petits à moyens et facilement confondables sur le terrain.','Champignon toxique : odeur de phénol/encre/iode, désagréablement renforcée à la cuisson. Agaric champêtre : agréablement fongique et douce. Ici l''odeur est un critère de distinction fiable.','Agaric perlé plutôt dans les parcs, jardins, en lisière de forêt et près des habitations ; agaric champêtre dans les prairies fauchées et les pâturages. Un chevauchement d''habitat est possible, ne pas s''y fier seul.','Les deux ont une sporée brun chocolat — PAS un critère de distinction.','Sur CHAQUE agaric, couper la base du pied ET sentir : virage jaune chrome plus odeur de phénol/encre (à tester aussi lors d''une brève cuisson) = agaric toxique, jeter tout le contenu du panier, pas seulement le spécimen isolé.','{"L''agaric perlé/phénolé sent désagréablement le phénol/l''encre/l''iode (pharmacie, hôpital), odeur renforcée et écœurante au chauffage ; l''agaric champêtre sent agréablement le champignon, doux","La base du pied de l''agaric perlé vire immédiatement et fortement au jaune chrome quand on la gratte/coupe (surtout dans la zone du bulbe) ; l''agaric champêtre tout au plus faiblement rougeâtre/brunâtre","L''agaric champêtre a des lames roses dès le début, puis brun chocolat (jamais blanc pur) ; des lames blanc pur chez un jeune agaric = signal d''alerte vers l''agaric toxique","Surface du chapeau de l''agaric perlé gris-brun mouchetée/squameuse (tachetée comme une pintade) ; agaric champêtre blanc pur à crème, lisse à squameux","L''odeur de phénol ET la base du pied jaune chrome apparaissent ensemble et excluent avec certitude tout agaric comestible"}',false),
('agaricus_campestris','agaricus_moelleri','it','Prataiolo perlato (psalliota della faraona) con cappello grigio-bruno maculato, screziato come il piumaggio di una faraona; prataiolo dei prati bianco puro-crema, liscio. Attenzione: entrambi piccolo-medi, facilmente confondibili sul campo.','Fungo velenoso: odore di fenolo/inchiostro/iodio, sgradevolmente accentuato in cottura. Prataiolo dei prati: gradevolmente fungino e delicato. Qui l''odore è un criterio distintivo affidabile.','Prataiolo perlato piuttosto in parchi, giardini, ai margini dei boschi e vicino agli insediamenti; prataiolo dei prati su prati falciati e pascoli. Sovrapposizione di habitat possibile, non affidarsi solo a questo.','Entrambi sporata bruno cioccolato — NON un criterio distintivo.','Su OGNI prataiolo tagliare la base del gambo E annusare: viraggio giallo cromo più odore di fenolo/inchiostro (testare anche con una breve rosolatura) = prataiolo velenoso, gettare l''intero contenuto del cesto, non solo il singolo esemplare.','{"Il prataiolo perlato/fenolico odora sgradevolmente di fenolo/inchiostro/iodio (farmacia, ospedale), odore accentuato e nauseante al riscaldamento; il prataiolo dei prati odora gradevolmente di fungo, delicato","La base del gambo del prataiolo perlato vira subito e intensamente al giallo cromo quando viene grattata/tagliata (soprattutto nella zona del bulbo); il prataiolo dei prati al massimo debolmente rossastro/brunastro","Il prataiolo dei prati ha lamelle rosa fin dall''inizio, poi bruno cioccolato (mai bianco puro); lamelle bianco puro in un prataiolo giovane = segnale d''allarme verso il prataiolo velenoso","Superficie del cappello del prataiolo perlato grigio-bruno maculata/squamosa (screziata come una faraona); prataiolo dei prati bianco puro-crema, da liscio a squamoso","L''odore di fenolo E la base del gambo giallo cromo compaiono insieme ed escludono con certezza ogni prataiolo commestibile"}',false),
('agaricus_campestris','fliegenpilz_var_alba','en','Field mushroom: pink-brown gills, ringed stem without bulbous volva; white fly agaric: white gills, warted belted bulb.','Field mushroom pleasantly mushroomy; white fly agaric inconspicuous.','Field mushroom on open grassland; fly agaric var. alba in/at the forest, mycorrhizal.','Field mushroom with brown spore print vs. white spore print in the fly agaric.','Golden Agaricus rule: never eat a "mushroom" with gills that stay white — the spore print (brown vs. white) makes the difference.','{"The field mushroom has free gills that are pink when young, later blackish-brown, and a brown spore print; the white fly agaric keeps white gills and has a white spore print","Agaricus mushrooms have no volva and no warted-belted bulb — the white fly agaric shows veil warts and a rimmed, striated bulb base","Habitat: field mushroom on open, fertilised meadows/pastures; white fly agaric in the forest under birch/conifer","Reject any supposed Agaricus with white gills immediately — white gills point to Amanita"}',false),
('agaricus_campestris','fliegenpilz_var_alba','es','Champiñón silvestre: láminas rosa-marrón, pie anillado sin volva bulbosa; amanita matamoscas blanca: láminas blancas, bulbo verrugoso con cinturones.','Champiñón silvestre agradablemente fúngico; amanita matamoscas blanca discreta.','Champiñón silvestre en praderas abiertas; matamoscas var. alba en/al borde del bosque, micorrízica.','Champiñón silvestre con esporada marrón frente a esporada blanca de la amanita matamoscas.','Regla de oro del champiñón: nunca comer un «champiñón» cuyas láminas permanezcan blancas — la impronta de esporada (marrón frente a blanca) marca la diferencia.','{"El champiñón silvestre tiene láminas libres rosas de joven, luego negro-marrones, y esporada marrón; la amanita matamoscas blanca conserva láminas blancas y tiene esporada blanca","Los champiñones no tienen volva ni bulbo verrugoso-cinturado — la amanita matamoscas blanca muestra verrugas de velo y una base de bulbo marginada-estriada","Hábitat: champiñón silvestre en praderas/pastos abiertos y abonados; amanita matamoscas blanca en el bosque bajo abedul/conífera","Rechazar de inmediato todo supuesto champiñón con láminas blancas — las láminas blancas apuntan a Amanita"}',false),
('agaricus_campestris','fliegenpilz_var_alba','fr','Agaric champêtre : lamelles rose-brun, pied annelé sans volve bulbeuse ; amanite tue-mouches blanche : lamelles blanches, bulbe verruqueux ceinturé.','Agaric champêtre agréablement fongique ; amanite tue-mouches blanche discrète.','Agaric champêtre en prairies ouvertes ; amanite tue-mouches var. alba en/au bord de forêt, mycorhizienne.','Agaric champêtre à sporée brune contre sporée blanche chez l''amanite tue-mouches.','Règle d''or de l''agaric : ne jamais manger un « champignon » dont les lamelles restent blanches — l''empreinte de sporée (brune contre blanche) fait la différence.','{"L''agaric champêtre a des lamelles libres roses jeunes puis brun-noir et une sporée brune ; l''amanite tue-mouches blanche garde des lamelles blanches et a une sporée blanche","Les agarics n''ont pas de volve ni de bulbe verruqueux-ceinturé — l''amanite tue-mouches blanche montre des verrues de voile et une base de bulbe marginée-striée","Habitat : agaric champêtre sur prairies/pâtures ouvertes et fertilisées ; amanite tue-mouches blanche en forêt sous bouleau/conifère","Rejeter immédiatement tout prétendu agaric à lamelles blanches — des lamelles blanches indiquent une Amanita"}',false),
('agaricus_campestris','fliegenpilz_var_alba','it','Prataiolo (campestre): lamelle rosa-brune, gambo anellato senza volva bulbosa; ovolaccio bianco: lamelle bianche, bulbo verrucoso a cinture.','Prataiolo campestre gradevolmente fungino; ovolaccio bianco discreto.','Prataiolo campestre in prati aperti; ovolaccio var. alba nel/ai margini del bosco, micorrizico.','Prataiolo campestre con sporata bruna contro sporata bianca dell''ovolaccio.','Regola d''oro del prataiolo: non mangiare mai un «prataiolo» con lamelle che restano bianche — l''impronta sporale (bruna contro bianca) fa la differenza.','{"Il prataiolo campestre ha lamelle libere rosa da giovani poi bruno-nere e una sporata bruna; l''ovolaccio bianco mantiene lamelle bianche e ha una sporata bianca","I prataioli non hanno volva né bulbo verrucoso-cinturato — l''ovolaccio bianco mostra verruche di velo e una base del bulbo marginato-striata","Habitat: prataiolo campestre su prati/pascoli aperti e concimati; ovolaccio bianco nel bosco sotto betulla/conifera","Scartare subito ogni presunto prataiolo con lamelle bianche — lamelle bianche indicano un''Amanita"}',false),
('agaricus_silvicola','agaricus_moelleri','en','Wood mushroom pure white silky (yellows faintly); inky mushroom grey-brown spotted with guineafowl-mottled cap. Caution: similar whitish appearance.','Wood mushroom: pleasant smell of anise/bitter almond. Toxic mushroom: carbolic/ink/iodine, unpleasant when cooked. The smell is the most important distinguishing feature.','Wood mushroom in coniferous/mixed forest; inky mushroom in parks, gardens, at forest edges. Habitat helps but is not absolutely discriminating.','Both chocolate-brown — NOT a distinguishing feature.','The smell test and scratch test at the stem base are mandatory: carbolic smell plus chrome-yellow base = toxic, never eat. An anise smell without a chrome-yellow base argues for the wood mushroom — when in doubt, make a spore print and consult an expert.','{"The thin-fleshed wood mushroom smells distinctly of anise/bitter almond (pleasant); the inky mushroom of carbolic/ink/iodine (unpleasant)","The stem base of the wood mushroom turns at most faintly yellowish when cut; that of the inky mushroom immediately and strongly chrome-yellow","When heated the anise aroma becomes pleasantly sweet, the inky mushroom stinks more strongly of ink/carbolic","The wood mushroom has a pure white, silky cap (yellows slightly under pressure); the inky mushroom grey-brown spotted/scaly","Both have pale gills when young — therefore NEVER decide on gill colour alone, but combine smell + stem-base reaction"}',false),
('agaricus_silvicola','agaricus_moelleri','es','Champiñón anisado blanco puro sedoso (amarillea ligeramente); champiñón perlado gris-pardo moteado con sombrero jaspeado como una pintada. Atención: aspecto blanquecino similar.','Champiñón anisado: agradable olor a anís/almendra amarga. Hongo tóxico: fenol/tinta/yodo, desagradable al cocinar. El olor es el criterio de distinción más importante.','Champiñón anisado en bosque de coníferas/mixto; champiñón perlado en parques, jardines, bordes del bosque. El hábitat ayuda pero no es absolutamente discriminante.','Ambos marrón chocolate — NO es un criterio de distinción.','La prueba olfativa y de rascado en la base del pie es obligatoria: olor a fenol más base amarillo cromo = tóxico, nunca comer. Olor a anís sin base amarillo cromo aboga por el champiñón anisado — en caso de duda, hacer la esporada y consultar a un experto.','{"El champiñón anisado de carne delgada huele claramente a anís/almendra amarga (agradable); el champiñón perlado a fenol/tinta/yodo (desagradable)","La base del pie del champiñón anisado vira como mucho débilmente a amarillento al cortarla; la del champiñón perlado de inmediato y con fuerza a amarillo cromo","Al calentar, el aroma de anís se vuelve agradablemente dulce, el champiñón perlado apesta más a tinta/fenol","El champiñón anisado tiene sombrero blanco puro, sedoso (amarillea ligeramente a la presión); el champiñón perlado gris-pardo moteado/escamoso","Ambos tienen láminas claras de jóvenes — por eso NUNCA decidir solo por el color de las láminas, sino combinar olor + reacción de la base del pie"}',false),
('agaricus_silvicola','agaricus_moelleri','fr','Agaric anisé blanc pur soyeux (jaunit légèrement) ; agaric perlé gris-brun moucheté avec chapeau tacheté comme une pintade. Attention : aspect blanchâtre similaire.','Agaric anisé : odeur agréable d''anis/amande amère. Champignon toxique : phénol/encre/iode, désagréable à la cuisson. L''odeur est le critère de distinction le plus important.','Agaric anisé en forêt de conifères/mixte ; agaric perlé dans les parcs, jardins, en lisière de forêt. L''habitat aide mais n''est pas absolument discriminant.','Les deux brun chocolat — PAS un critère de distinction.','Le test olfactif et le grattage de la base du pied sont obligatoires : odeur de phénol plus base jaune chrome = toxique, ne jamais manger. Une odeur d''anis sans base jaune chrome plaide pour l''agaric anisé — en cas de doute, faire la sporée et consulter un spécialiste.','{"L''agaric anisé à chair mince sent nettement l''anis/l''amande amère (agréable) ; l''agaric perlé le phénol/l''encre/l''iode (désagréable)","La base du pied de l''agaric anisé vire tout au plus faiblement au jaunâtre à la coupe ; celle de l''agaric perlé immédiatement et fortement au jaune chrome","Au chauffage, l''arôme d''anis devient agréablement sucré, l''agaric perlé pue davantage l''encre/le phénol","L''agaric anisé a un chapeau blanc pur, soyeux (jaunit légèrement à la pression) ; l''agaric perlé gris-brun moucheté/squameux","Les deux ont des lames claires lorsqu''ils sont jeunes — ne JAMAIS décider sur la seule couleur des lames, mais combiner odeur + réaction de la base du pied"}',false),
('agaricus_silvicola','agaricus_moelleri','it','Prataiolo anisato bianco puro setoso (ingiallisce leggermente); prataiolo perlato grigio-bruno maculato con cappello screziato come una faraona. Attenzione: aspetto biancastro simile.','Prataiolo anisato: gradevole odore di anice/mandorla amara. Fungo velenoso: fenolo/inchiostro/iodio, sgradevole in cottura. L''odore è il criterio distintivo più importante.','Prataiolo anisato in bosco di conifere/misto; prataiolo perlato in parchi, giardini, ai margini dei boschi. L''habitat aiuta ma non è assolutamente discriminante.','Entrambi bruno cioccolato — NON un criterio distintivo.','La prova olfattiva e di grattatura alla base del gambo è obbligatoria: odore di fenolo più base giallo cromo = velenoso, mai mangiare. Odore di anice senza base giallo cromo depone per il prataiolo anisato — nel dubbio fare la sporata e consultare un esperto.','{"Il prataiolo anisato a carne sottile odora nettamente di anice/mandorla amara (gradevole); il prataiolo perlato di fenolo/inchiostro/iodio (sgradevole)","La base del gambo del prataiolo anisato vira al massimo debolmente al giallastro al taglio; quella del prataiolo perlato subito e intensamente al giallo cromo","Al riscaldamento il profumo di anice diventa gradevolmente dolce, il prataiolo perlato puzza maggiormente di inchiostro/fenolo","Il prataiolo anisato ha cappello bianco puro, setoso (ingiallisce leggermente alla pressione); il prataiolo perlato grigio-bruno maculato/squamoso","Entrambi hanno lamelle chiare da giovani — quindi MAI decidere solo dal colore delle lamelle, ma combinare odore + reazione della base del gambo"}',false),
('agaricus_silvicola','fliegenpilz_var_alba','en','Agaricus (wood mushroom): pink to brown gills, smooth stem with ring, no bulbous volva; white fly agaric: white gills, warted belted bulb.','Wood mushroom smelling of anise/marzipan; white fly agaric inconspicuous.','Wood mushroom in forests; white fly agaric mycorrhizal under birch/conifer.','Wood mushroom with brown spore print vs. white spore print in the fly agaric — decisive distinguishing feature.','The spore-print test and gill colour are lifesavers: white gills + white spore print + bulbous volva = never eat as an Agaricus.','{"The wood mushroom has free gills that are pink when young and later chocolate brown, and a brown spore print; the white fly agaric has permanently WHITE gills and a white spore print","Agaricus mushrooms have NO volva and no warted, belted bulbous base — the white fly agaric has warted veil remnants and a striated-rimmed bulb","The wood mushroom smells distinctly of anise/marzipan; the white fly agaric is odourless","Young white fly agaric bulbs look agaric-like — therefore always dig out the stem base and check gill colour + spore print"}',false),
('agaricus_silvicola','fliegenpilz_var_alba','es','Champiñón (de bosque): láminas rosas a marrones, pie liso con anillo, sin volva bulbosa; amanita matamoscas blanca: láminas blancas, bulbo verrugoso con cinturones.','Champiñón anisado huele a anís/mazapán; amanita matamoscas blanca discreta.','Champiñón anisado en bosques; amanita matamoscas blanca micorrízica bajo abedul/conífera.','Champiñón anisado con esporada marrón frente a esporada blanca de la amanita matamoscas — carácter distintivo decisivo.','La prueba de esporada y el color de las láminas salvan la vida: láminas blancas + esporada blanca + volva bulbosa = nunca comer como champiñón.','{"El champiñón anisado tiene láminas libres que de jóvenes son rosas y luego marrón chocolate, y esporada marrón; la amanita matamoscas blanca tiene láminas permanentemente BLANCAS y esporada blanca","Los champiñones NO poseen volva ni base bulbosa verrugoso-cinturada — la amanita matamoscas blanca tiene restos de velo verrugosos y un bulbo estriado-marginado","El champiñón anisado huele claramente a anís/mazapán; la amanita matamoscas blanca es inodora","Los bulbos jóvenes de amanita matamoscas blanca parecen champiñones — por eso desenterrar siempre la base del pie y comprobar color de láminas + esporada"}',false),
('agaricus_silvicola','fliegenpilz_var_alba','fr','Agaric : lamelles roses à brunes, pied lisse avec anneau, sans volve bulbeuse ; amanite tue-mouches blanche : lamelles blanches, bulbe verruqueux ceinturé.','Agaric anisé sentant l''anis/le massepain ; amanite tue-mouches blanche discrète.','Agaric anisé en forêts ; amanite tue-mouches blanche mycorhizienne sous bouleau/conifère.','Agaric anisé à sporée brune contre sporée blanche chez l''amanite tue-mouches — caractère de séparation décisif.','L''épreuve de la sporée et la couleur des lamelles sauvent la vie : lamelles blanches + sporée blanche + volve bulbeuse = ne jamais manger comme agaric.','{"L''agaric anisé a des lamelles libres qui sont roses jeunes puis brun chocolat, et une sporée brune ; l''amanite tue-mouches blanche a des lamelles durablement BLANCHES et une sporée blanche","Les agarics ne possèdent AUCUNE volve et aucune base bulbeuse verruqueuse-ceinturée — l''amanite tue-mouches blanche a des restes de voile verruqueux et un bulbe strié-marginé","L''agaric anisé sent nettement l''anis/le massepain ; l''amanite tue-mouches blanche est inodore","Les jeunes bulbes d''amanite tue-mouches blanche ressemblent à des agarics — toujours déterrer la base du pied et vérifier la couleur des lamelles + la sporée"}',false),
('agaricus_silvicola','fliegenpilz_var_alba','it','Prataiolo: lamelle rosa fino a brune, gambo liscio con anello, senza volva bulbosa; ovolaccio bianco: lamelle bianche, bulbo verrucoso a cinture.','Prataiolo all''anice odora di anice/marzapane; ovolaccio bianco discreto.','Prataiolo all''anice nei boschi; ovolaccio bianco micorrizico sotto betulla/conifera.','Prataiolo all''anice con sporata bruna contro sporata bianca dell''ovolaccio — carattere distintivo decisivo.','La prova della sporata e il colore delle lamelle salvano la vita: lamelle bianche + sporata bianca + volva bulbosa = mai mangiare come prataiolo.','{"Il prataiolo all''anice ha lamelle libere che da giovani sono rosa e poi bruno cioccolato, e una sporata bruna; l''ovolaccio bianco ha lamelle stabilmente BIANCHE e sporata bianca","I prataioli NON possiedono volva né base bulbosa verrucoso-cinturata — l''ovolaccio bianco ha resti di velo verrucosi e un bulbo striato-marginato","Il prataiolo all''anice odora nettamente di anice/marzapane; l''ovolaccio bianco è inodore","I giovani bulbi di ovolaccio bianco sembrano prataioli — perciò dissotterrare sempre la base del gambo e controllare colore delle lamelle + sporata"}',false),
('amanita_caesarea','amanita_muscaria','en','Caesar''s mushroom uniformly yellow (gills/stem/ring) with a sac-like white volva and a smooth orange-red cap; fly agaric white (gills/stem/ring) with a warty bulb and cap-skin flecks (possibly washed off).','Both inconspicuous and mild — smell is NOT a distinguishing feature.','Caesar''s mushroom thermophilic, in Switzerland extremely rare only in southern locations (Ticino); fly agaric common with birch/spruce throughout the country.','Both white spore print — NOT a distinguishing feature.','Never eat an orange-red mushroom without checking gills, stem AND ring: all white = fly agaric (toxic). Only uniformly YELLOW gills/stem/ring plus a sac-like white volva argue for Caesar''s mushroom — when in doubt, expert/mushroom inspection (VAPKO).','{"The fly agaric has PURE WHITE gills, a white stem and a white ring — Caesar''s mushroom has YELLOW gills, a yellow stem and a yellow ring","The fly agaric has a warty bulb with rings of warts; Caesar''s mushroom a thick-skinned, sac-like, lobed white volva (eggshell-like sheath)","The fly agaric cap bears white, washable flecks (veil remnants); Caesar''s mushroom cap is smooth orange-red without a fleck pattern","DANGER: a fly agaric washed clean by rain or faded loses its white flecks and can look orange — then only the gill/stem/ring colour (white!) and the warty bulb decide","Caesar''s mushroom is a pronounced rarity in Switzerland (only warm southern locations, especially Ticino) — an orange-red Amanita outside such locations is most probably a fly agaric"}',false),
('amanita_caesarea','amanita_muscaria','es','Oronja completamente amarilla (láminas/pie/anillo) con volva blanca en forma de saco y sombrero liso rojo-anaranjado; matamoscas (Amanita muscaria) blanco (láminas/pie/anillo) con bulbo verrugoso y copos cuticulares (posiblemente lavados).','Ambos discretos y suaves — el olor NO es un criterio de distinción.','Oronja termófila, en Suiza extremadamente rara solo en zonas meridionales (Tesino); matamoscas frecuente bajo abedul/abeto rojo en todo el país.','Ambos esporada blanca — NO es un criterio de distinción.','Nunca comer un hongo rojo-anaranjado sin comprobar láminas, pie Y anillo: todo blanco = matamoscas (tóxico). Solo láminas/pie/anillo completamente AMARILLOS más una volva blanca en forma de saco abogan por la oronja — en caso de duda, experto/control de setas (VAPKO).','{"El matamoscas tiene láminas BLANCO PURO, pie blanco y anillo blanco — la oronja tiene láminas AMARILLAS, pie amarillo y anillo amarillo","El matamoscas tiene un bulbo verrugoso con cinturones de verrugas; la oronja una volva blanca gruesa, en forma de saco, lobulada (vaina como cáscara de huevo)","El sombrero del matamoscas lleva copos blancos lavables (restos de velo); el sombrero de la oronja es liso rojo-anaranjado sin patrón de copos","PELIGRO: un matamoscas lavado por la lluvia o desteñido pierde los copos blancos y puede parecer naranja — entonces solo deciden el color de láminas/pie/anillo (¡blanco!) y el bulbo verrugoso","La oronja es una rareza marcada en Suiza (solo zonas meridionales cálidas, sobre todo Tesino) — una Amanita rojo-anaranjada fuera de tales zonas es con alta probabilidad un matamoscas"}',false),
('amanita_caesarea','amanita_muscaria','fr','Oronge entièrement jaune (lames/pied/anneau) avec une volve blanche en sac et un chapeau lisse rouge-orangé ; amanite tue-mouches blanche (lames/pied/anneau) avec un bulbe verruqueux et des flocons cuticulaires (éventuellement délavés).','Les deux discrètes et douces — l''odeur n''est PAS un critère de distinction.','Oronge thermophile, en Suisse extrêmement rare uniquement dans les régions méridionales (Tessin) ; amanite tue-mouches fréquente sous bouleau/épicéa dans tout le pays.','Les deux ont une sporée blanche — PAS un critère de distinction.','Ne jamais manger un champignon rouge-orangé sans vérifier les lames, le pied ET l''anneau : tout blanc = amanite tue-mouches (toxique). Seuls des lames/pied/anneau entièrement JAUNES plus une volve blanche en sac plaident pour l''oronge — en cas de doute, spécialiste/contrôle des champignons (VAPKO).','{"L''amanite tue-mouches a des lames BLANC PUR, un pied blanc et un anneau blanc — l''oronge a des lames JAUNES, un pied jaune et un anneau jaune","L''amanite tue-mouches a un bulbe verruqueux à bourrelets ; l''oronge une volve blanche épaisse, en sac, lobée (gaine en coquille d''œuf)","Le chapeau de l''amanite tue-mouches porte des flocons blancs lavables (restes de voile) ; le chapeau de l''oronge est lisse rouge-orangé sans motif de flocons","DANGER : une amanite tue-mouches délavée par la pluie ou décolorée perd ses flocons blancs et peut paraître orange — seules la couleur des lames/du pied/de l''anneau (blanc !) et le bulbe verruqueux décident alors","L''oronge est une rareté prononcée en Suisse (uniquement régions méridionales chaudes, surtout Tessin) — une amanite rouge-orangée hors de telles régions est très probablement une amanite tue-mouches"}',false),
('amanita_caesarea','amanita_muscaria','it','Ovolo buono interamente giallo (lamelle/gambo/anello) con volva bianca a sacco e cappello liscio rosso-arancio; ovolo malefico (amanita muscaria) bianco (lamelle/gambo/anello) con bulbo verrucoso e fioccosità cuticolari (eventualmente dilavate).','Entrambi discreti e delicati — l''odore NON è un criterio distintivo.','Ovolo buono termofilo, in Svizzera estremamente raro solo nelle regioni meridionali (Ticino); amanita muscaria frequente sotto betulla/abete rosso in tutto il Paese.','Entrambi sporata bianca — NON un criterio distintivo.','Non mangiare mai un fungo rosso-arancio senza controllare lamelle, gambo E anello: tutto bianco = amanita muscaria (velenosa). Solo lamelle/gambo/anello interamente GIALLI più una volva bianca a sacco depongono per l''ovolo buono — nel dubbio esperto/controllo dei funghi (VAPKO).','{"L''amanita muscaria ha lamelle BIANCO PURO, gambo bianco e anello bianco — l''ovolo buono ha lamelle GIALLE, gambo giallo e anello giallo","L''amanita muscaria ha un bulbo verrucoso con cinture di verruche; l''ovolo buono una volva bianca spessa, a sacco, lobata (guaina a guscio d''uovo)","Il cappello dell''amanita muscaria porta fiocchi bianchi lavabili (resti di velo); il cappello dell''ovolo buono è liscio rosso-arancio senza disegno di fiocchi","PERICOLO: un''amanita muscaria dilavata dalla pioggia o scolorita perde i fiocchi bianchi e può apparire arancione — allora decidono solo il colore di lamelle/gambo/anello (bianco!) e il bulbo verrucoso","L''ovolo buono in Svizzera è una spiccata rarità (solo regioni meridionali calde, soprattutto Ticino) — un''Amanita rosso-arancio fuori da tali zone è con alta probabilità amanita muscaria"}',false),
('amanita_crocea','amanita_gemmata','en','Toxic mushroom: yellowish cap with white flake remnants, (fleeting) ring on the stem, onion-like bulb with a rimmed sheath. Orange grisette (Amanita crocea): orange-yellow, grooved-rimmed, flake-free cap, NO ring, high free sheath.','Both inconspicuous — smell is NOT a distinguishing feature.','Both near broadleaf/conifer trees on rather acidic soil; habitat does not separate reliably.','Both white spore print — NOT a distinguishing feature.','Grisettes NEVER have a ring nor a rimmed bulb — any yellow Amanita WITH a ring collar and/or a bulb is suspicious (the gemmed Amanita / jonquil Amanita contains ibotenic acid/muscimol and muscarine) and does not belong in the basket.','{"The jonquil Amanita (Amanita gemmata) has an onion-like bulb with a rimmed, transient sheath AND a (often fleeting) ring — grisettes (including the orange grisette) NEVER have a ring","The grisette has a high, membranous, free sheath (volva) at the stem base, no bulb; cap margin distinctly grooved/furrowed","The cap of the toxic mushroom bears white, angular veil remnants (cap-skin flakes) and is deep to pale yellow (can fade in dry weather); the grisette cap is orange-yellow, flake-free, with a grooved margin","Stem of the grisette without a hanging ring collar; any ringed yellow Amanita is suspicious","Important: faded gemmata caps can appear paler/more similar — therefore ALWAYS check the ring + bulb shape, not just the cap colour"}',false),
('amanita_crocea','amanita_gemmata','es','Hongo tóxico: sombrero amarillento con restos de copos blancos, anillo (fugaz) en el pie, bulbo en forma de cebolla con vaina marginada. Amanita azafranada (Amanita crocea): sombrero amarillo-anaranjado, de margen estriado-surcado, sin copos, SIN anillo, vaina libre alta.','Ambos discretos — el olor NO es un criterio de distinción.','Ambos junto a frondosas/coníferas en suelo más bien ácido; el hábitat no separa de forma fiable.','Ambos esporada blanca — NO es un criterio de distinción.','Las amanitas envainadas (Vaginatae) NUNCA tienen anillo ni bulbo marginado — toda amanita amarilla CON collar de anillo y/o bulbo es sospechosa (la amanita gemada / amanita amarilla contiene ácido iboténico/muscimol y muscarina) y no va al cesto.','{"La amanita gemada (Amanita gemmata) tiene un bulbo en forma de cebolla con vaina marginada y fugaz Y un anillo (a menudo fugaz) — las amanitas envainadas (incluida la amanita azafranada) NUNCA tienen anillo","La amanita envainada posee una vaina (volva) alta, membranosa y libre en la base del pie, ningún bulbo; margen del sombrero claramente estriado/surcado","El sombrero del hongo tóxico lleva restos de velo blancos y angulosos (copos cuticulares) y es de amarillo intenso a pálido (puede desteñirse con tiempo seco); el sombrero de la amanita azafranada es amarillo-anaranjado, sin copos, con margen estriado","Pie de la amanita envainada sin collar de anillo colgante; toda amanita amarilla con anillo es sospechosa","Importante: los sombreros de gemmata desteñidos pueden parecer más pálidos/más similares — por eso comprobar SIEMPRE el anillo + la forma del bulbo, no solo el color del sombrero"}',false),
('amanita_crocea','amanita_gemmata','fr','Champignon toxique : chapeau jaunâtre avec restes de flocons blancs, anneau (fugace) sur le pied, bulbe en oignon à gaine marginée. Amanite safran : chapeau jaune-orangé, à marge striée-sillonnée, sans flocons, SANS anneau, haute gaine libre.','Les deux discrètes — l''odeur n''est PAS un critère de distinction.','Les deux près de feuillus/conifères sur sol plutôt acide ; l''habitat ne sépare pas de manière fiable.','Les deux ont une sporée blanche — PAS un critère de distinction.','Les amanites engainées n''ont JAMAIS d''anneau ni de bulbe marginé — toute amanite jaune AVEC manchette d''anneau et/ou bulbe est suspecte (l''amanite jonquille contient de l''acide iboténique/muscimol et de la muscarine) et ne va pas dans le panier.','{"L''amanite jonquille a un bulbe en oignon à gaine marginée et fugace ET un anneau (souvent fugace) — les amanites engainées (y compris l''amanite safran orangée) n''ont JAMAIS d''anneau","L''amanite engainée possède une gaine (volve) haute, membraneuse et libre à la base du pied, pas de bulbe ; marge du chapeau nettement striée/sillonnée","Le chapeau du champignon toxique porte des restes de voile blancs et anguleux (flocons cuticulaires) et est jaune vif à pâle (peut se décolorer par temps sec) ; le chapeau de l''amanite safran est jaune-orangé, sans flocons, à marge striée","Le pied de l''amanite engainée sans manchette d''anneau pendante ; toute amanite jaune annelée est suspecte","Important : les chapeaux de gemmata décolorés peuvent paraître plus pâles/plus semblables — donc TOUJOURS regarder l''anneau + la forme du bulbe, pas seulement la couleur du chapeau"}',false),
('amanita_crocea','amanita_gemmata','it','Fungo velenoso: cappello giallastro con resti di fiocchi bianchi, anello (fugace) sul gambo, bulbo a cipolla con guaina marginata. Amanita fulva crocea (bubbola): cappello giallo-arancio, con margine striato-solcato, senza fiocchi, SENZA anello, alta guaina libera.','Entrambi discreti — l''odore NON è un criterio distintivo.','Entrambi presso latifoglie/conifere su suolo piuttosto acido; l''habitat non separa in modo affidabile.','Entrambi sporata bianca — NON un criterio distintivo.','Le amanite a guaina (Vaginatae) non hanno MAI anello né bulbo marginato — ogni amanita gialla CON collare ad anello e/o bulbo è sospetta (l''amanita gemmata contiene acido ibotenico/muscimolo e muscarina) e non va nel cesto.','{"L''amanita gemmata ha un bulbo a cipolla con guaina marginata e fugace E un anello (spesso fugace) — le amanite a guaina (compresa la bubbola giallo-arancio) non hanno MAI anello","L''amanita a guaina possiede una guaina (volva) alta, membranosa e libera alla base del gambo, nessun bulbo; margine del cappello nettamente striato/solcato","Il cappello del fungo velenoso porta resti di velo bianchi e angolosi (fiocchi cuticolari) ed è giallo intenso o pallido (può scolorire con tempo secco); il cappello della bubbola è giallo-arancio, senza fiocchi, con margine striato","Il gambo dell''amanita a guaina senza collare ad anello pendente; ogni amanita gialla con anello è sospetta","Importante: i cappelli di gemmata scoloriti possono apparire più pallidi/più simili — quindi guardare SEMPRE anello + forma del bulbo, non solo il colore del cappello"}',false),
('amanita_fulva','amanita_gemmata','en','Tawny grisette red-brown, grooved, flake-free, ringless, with a high sheath; toxic mushroom yellowish, flaky, with a (fleeting) ring and a rimmed bulb.','Both inconspicuous — NOT a distinguishing feature.','Both near broadleaf/conifer trees on rather acidic soil; habitat does not separate.','Both white spore print — NOT a distinguishing feature.','Pay attention to ring and bulb: grisettes are always ringless with a high free sheath; a yellow Amanita with a ring or rimmed bulb is the toxic jonquil Amanita — when in doubt, leave it standing.','{"The tawny grisette is RINGLESS — the jonquil Amanita has a (often fleeting) hanging ring","Grisette with a high, free, red-brown-spotted sheath (volva) at the stem base instead of an onion-like bulb with a rimmed sheath","Cap of the grisette red-brown to foxy, smooth, strongly grooved at the margin, without veil flakes; toxic mushroom yellow (faded in dry weather) with white cap-skin flakes","Stem of the grisette without a mottled ring zone and without a collar","The tawny grisette should in any case only be eaten well cooked — raw, grisettes are indigestible"}',false),
('amanita_fulva','amanita_gemmata','es','Amanita envainada leonada pardo-rojiza, estriada, sin copos, sin anillo, con vaina alta; hongo tóxico amarillento, escamoso, con anillo (fugaz) y bulbo marginado.','Ambos discretos — NO es un criterio de distinción.','Ambos junto a frondosas/coníferas en suelo más bien ácido; el hábitat no separa.','Ambos esporada blanca — NO es un criterio de distinción.','Prestar atención al anillo y al bulbo: las amanitas envainadas son siempre sin anillo con vaina libre alta; una amanita amarilla con anillo o bulbo marginado es la amanita gemada tóxica — en caso de duda, dejarla en el lugar.','{"La amanita leonada envainada es SIN ANILLO — la amanita gemada tiene un anillo colgante (a menudo fugaz)","Amanita envainada con vaina (volva) alta, libre, manchada de pardo-rojizo en la base del pie en lugar de un bulbo en forma de cebolla con vaina marginada","Sombrero de la amanita envainada pardo-rojizo a leonado, liso, fuertemente estriado en el margen, sin copos de velo; hongo tóxico amarillo (desteñido con tiempo seco) con copos cuticulares blancos","Pie de la amanita envainada sin zona de anillo jaspeada y sin collar","La amanita leonada envainada debe en cualquier caso comerse solo bien cocida — crudas, las amanitas envainadas son indigestas"}',false),
('amanita_fulva','amanita_gemmata','fr','Amanite engainée brun-roux, striée, sans flocons, sans anneau, à haute gaine ; champignon toxique jaunâtre, floconneux, avec anneau (fugace) et bulbe marginé.','Les deux discrètes — PAS un critère de distinction.','Les deux près de feuillus/conifères sur sol plutôt acide ; l''habitat ne sépare pas.','Les deux ont une sporée blanche — PAS un critère de distinction.','Faire attention à l''anneau et au bulbe : les amanites engainées sont toujours sans anneau avec une haute gaine libre ; une amanite jaune avec anneau ou bulbe marginé est l''amanite jonquille toxique — en cas de doute, la laisser sur place.','{"L''amanite fauve engainée est SANS ANNEAU — l''amanite jonquille a un anneau pendant (souvent fugace)","Amanite engainée à gaine (volve) haute, libre, tachée de brun-roux à la base du pied au lieu d''un bulbe en oignon à gaine marginée","Chapeau de l''amanite engainée brun-roux à fauve, lisse, fortement strié au bord, sans flocons de voile ; champignon toxique jaune (décoloré par temps sec) avec flocons cuticulaires blancs","Pied de l''amanite engainée sans zone d''anneau tachetée et sans manchette","L''amanite fauve engainée ne doit de toute façon être mangée que bien cuite — crues, les amanites engainées sont indigestes"}',false),
('amanita_fulva','amanita_gemmata','it','Amanita a guaina (bubbola fulva) bruno-rossiccia, striata, senza fiocchi, senza anello, con alta guaina; fungo velenoso giallastro, fioccoso, con anello (fugace) e bulbo marginato.','Entrambi discreti — NON un criterio distintivo.','Entrambi presso latifoglie/conifere su suolo piuttosto acido; l''habitat non separa.','Entrambi sporata bianca — NON un criterio distintivo.','Fare attenzione ad anello e bulbo: le amanite a guaina sono sempre senza anello con alta guaina libera; un''amanita gialla con anello o bulbo marginato è l''amanita gemmata velenosa — nel dubbio lasciarla sul posto.','{"La bubbola bruno-rossiccia è SENZA ANELLO — l''amanita gemmata ha un anello pendente (spesso fugace)","Amanita a guaina con guaina (volva) alta, libera, macchiata di bruno-rossiccio alla base del gambo invece di un bulbo a cipolla con guaina marginata","Cappello della bubbola bruno-rossiccio fino a fulvo, liscio, fortemente striato al margine, senza fiocchi di velo; fungo velenoso giallo (scolorito con tempo secco) con fiocchi cuticolari bianchi","Gambo della bubbola senza zona ad anello screziata e senza collare","La bubbola bruno-rossiccia va comunque mangiata solo ben cotta — crude le bubbole sono indigeste"}',false),
('amanita_rubescens','amanita_gemmata','en','Blusher with pinkish reddening at pressure/bite marks and a strongly grooved ring (cap colour variable); toxic mushroom usually bright yellow, not reddening, with a fleeting ring.','Both inconspicuous and mild — NOT a reliable distinguishing feature.','Both in broadleaf/conifer forest; habitat does not separate.','Both white spore print — NOT a distinguishing feature.','The blusher MUST redden and is only edible well cooked — a yellow Amanita that does NOT redden never belongs in the basket (jonquil Amanita: ibotenic acid/muscimol and muscarine). Raw, the blusher is also toxic.','{"The blusher reddens distinctly to wine-red/flesh-pink when injured/grub-eaten — the jonquil Amanita NEVER reddens, its flesh stays white-yellowish (most reliable distinguishing feature)","The blusher has a robust ring, grooved (ridged) on the upper side; the ring of the toxic mushroom is thin and transient (often absent)","Cap colour of the blusher very variable (whitish, brown-yellowish, flesh-pink to red-brown) — therefore do NOT rely on colour alone; toxic mushroom usually deep lemon/ochre-yellow, fading in dry weather","Bulb of the blusher rounded with veil rings (without a rimmed sheath); toxic mushroom with an onion-like bulb and a rimmed remnant sheath","Stem base/bite marks of the blusher often tinged pink/wine-red, not in the toxic mushroom"}',false),
('amanita_rubescens','amanita_gemmata','es','Amanita rojiza (Amanita rubescens) con enrojecimiento rosado en los puntos de presión/mordedura y anillo fuertemente estriado (color del sombrero variable); hongo tóxico por lo general amarillo vivo, que no enrojece, con anillo fugaz.','Ambos discretos y suaves — NO es un criterio de distinción fiable.','Ambos en bosque de frondosas/coníferas; el hábitat no separa.','Ambos esporada blanca — NO es un criterio de distinción.','La amanita rojiza DEBE enrojecer y solo es comestible bien cocida — una amanita amarilla que NO enrojece nunca va al cesto (amanita gemada: ácido iboténico/muscimol y muscarina). Cruda, la amanita rojiza también es tóxica.','{"La amanita rojiza enrojece claramente a rojo vinoso/rosa carne al ser herida/comida por larvas — la amanita gemada NUNCA enrojece, su carne permanece blanco-amarillenta (criterio de distinción más fiable)","La amanita rojiza tiene un anillo robusto, estriado (acanalado) por la parte superior; el anillo del hongo tóxico es fino y fugaz (a menudo ausente)","Color del sombrero de la amanita rojiza muy variable (blanquecino, pardo-amarillento, rosa carne a pardo-rojizo) — por eso NO fiarse solo del color; hongo tóxico por lo general amarillo limón/ocre intenso, que se destiñe con tiempo seco","Bulbo de la amanita rojiza redondeado con cinturones de velo (sin vaina marginada); hongo tóxico con bulbo en forma de cebolla y resto de vaina marginada","Base del pie/marcas de mordedura de la amanita rojiza a menudo teñidas de rosa/rojo vinoso, no en el hongo tóxico"}',false),
('amanita_rubescens','amanita_gemmata','fr','Amanite rougissante avec rougissement rosé aux points de pression/morsure et anneau fortement strié (couleur du chapeau variable) ; champignon toxique généralement jaune vif, ne rougissant pas, à anneau fugace.','Les deux discrètes et douces — PAS un critère de distinction fiable.','Les deux en forêt de feuillus/conifères ; l''habitat ne sépare pas.','Les deux ont une sporée blanche — PAS un critère de distinction.','L''amanite rougissante DOIT rougir et n''est comestible que bien cuite — une amanite jaune qui NE rougit PAS ne va jamais dans le panier (amanite jonquille : acide iboténique/muscimol et muscarine). Crue, l''amanite rougissante est aussi toxique.','{"L''amanite rougissante rougit nettement en rouge vineux/rose chair en cas de blessure/morsure de larve — l''amanite jonquille ne rougit JAMAIS, sa chair reste blanc-jaunâtre (critère de distinction le plus fiable)","L''amanite rougissante a un anneau robuste, strié (cannelé) sur le dessus ; l''anneau du champignon toxique est mince et fugace (souvent absent)","Couleur du chapeau de l''amanite rougissante très variable (blanchâtre, brun-jaunâtre, rose chair à brun-roux) — ne donc PAS se fier à la seule couleur ; champignon toxique généralement jaune citron/ocre soutenu, se décolorant par temps sec","Bulbe de l''amanite rougissante arrondi avec bourrelets de voile (sans gaine marginée) ; champignon toxique à bulbe en oignon et reste de gaine marginée","Base du pied/points de morsure de l''amanite rougissante souvent teintés de rose/rouge vineux, pas chez le champignon toxique"}',false),
('amanita_rubescens','amanita_gemmata','it','Tignosa vinata con arrossamento rosato nei punti di pressione/morso e anello fortemente striato (colore del cappello variabile); fungo velenoso di solito giallo vivo, non arrossante, con anello fugace.','Entrambi discreti e delicati — NON un criterio distintivo affidabile.','Entrambi in bosco di latifoglie/conifere; l''habitat non separa.','Entrambi sporata bianca — NON un criterio distintivo.','La tignosa vinata DEVE arrossare ed è commestibile solo ben cotta — un''amanita gialla che NON arrossa non va mai nel cesto (amanita gemmata: acido ibotenico/muscimolo e muscarina). Cruda anche la tignosa vinata è velenosa.','{"La tignosa vinata arrossa nettamente in rosso vinoso/rosa carne in caso di ferita/morso di larva — l''amanita gemmata non arrossa MAI, la sua carne resta bianco-giallastra (criterio distintivo più affidabile)","La tignosa vinata ha un anello robusto, striato (scanalato) superiormente; l''anello del fungo velenoso è sottile e fugace (spesso assente)","Colore del cappello della tignosa vinata molto variabile (biancastro, bruno-giallastro, rosa carne fino a bruno-rossiccio) — quindi NON affidarsi solo al colore; fungo velenoso di solito giallo limone/ocra intenso, che scolorisce con tempo secco","Bulbo della tignosa vinata arrotondato con cinture di velo (senza guaina marginata); fungo velenoso con bulbo a cipolla e resto di guaina marginata","Base del gambo/punti di morso della tignosa vinata spesso tinti di rosa/rosso vinoso, non nel fungo velenoso"}',false),
('amanita_rubescens','fliegenpilz-roetlich','en','The royal fly agaric has a leather-brown to dark grey-brown cap with yellowish-grey veil flecks and a yellow to yellow-brown zone beneath the cap skin; the blusher reddens pink to wine-red at feeding and pressure spots and does not show this yellow subcuticular zone.','Both smell inconspicuously mushroomy — smell does NOT help to tell them apart here, so the reddening and the yellow layer beneath the cap skin are the decisive features.','The royal fly agaric only in acidic coniferous forest as a spruce symbiont (more in upland areas); the blusher widely distributed in deciduous, coniferous and mixed forest, also at lower elevations.','Both are white-spored — the spore print does not separate the two; decisive are the reddening and the yellow subcuticular zone beneath the cap skin.','With brown-capped amanitas ALWAYS cut the flesh and observe for 10-15 min: if it reddens pink/wine-red = blusher; if it stays white with a yellow layer directly beneath the cap skin = poisonous royal fly agaric, leave it standing. When in doubt with gilled amanitas, generally refrain.','{"The blusher (edible) reddens markedly on injury, pressure and maggot feeding to flesh- to wine-red/pink — the brown royal fly agaric (Amanita regalis) NEVER does this.","Royal fly agaric: white flesh, but directly beneath the cap skin a characteristic yellow to yellow-brown zone (visible in longitudinal/cross section) — in the blusher this yellow layer is absent.","Cap colour of the royal fly agaric: leather-brown to dark grey-brown with yellowish to grey-white, wipeable veil flecks; blusher: reddish-brown to flesh-brownish with grey to reddish-tinged skin remnants.","The royal fly agaric grows as a spruce symbiont almost only in acidic coniferous forest (more upland/higher elevations) — the blusher prefers deciduous and mixed forest, also at lower altitudes and widely distributed.","The royal fly agaric contains ibotenic acid/muscimol like the red fly agaric (pantherina syndrome: confusion, hallucinations, convulsions, in larger amounts circulatory collapse/respiratory paralysis) — not an edible mushroom, not even cooked."}',false),
('amanita_rubescens','fliegenpilz-roetlich','es','La amanita real tiene un sombrero pardo cuero a pardo-gris oscuro con copos del velo gris-amarillentos y una zona amarilla a pardo-amarilla bajo la cutícula; la amanita rojiza enrojece de rosa a rojo vinoso en las zonas roídas y de presión y no muestra esta zona subcuticular amarilla.','Ambas huelen a hongo de forma poco llamativa — el olor NO ayuda aquí a distinguirlas, por lo que el enrojecimiento y la capa amarilla bajo la cutícula son los caracteres decisivos.','La amanita real solo en bosque ácido de coníferas como simbionte del abeto rojo (más bien en montaña); la amanita rojiza ampliamente distribuida en bosque de frondosas, coníferas y mixto, también a menor altitud.','Ambas de esporas blancas — la esporada no separa a las dos; decisivos son el enrojecimiento y la zona subcuticular amarilla bajo la cutícula.','Con las amanitas de sombrero pardo SIEMPRE cortar la carne y observar 10-15 min: si enrojece rosa/rojo vinoso = amanita rojiza; si permanece blanca con una capa amarilla justo bajo la cutícula = amanita real tóxica, dejarla. En caso de duda con las amanitas laminadas, renunciar por regla general.','{"La amanita rojiza (comestible) enrojece netamente, por herida, presión y ataque de gusanos, de rojo carne a rojo vinoso/rosa — la amanita real parda (Amanita regalis) NUNCA lo hace.","Amanita real: carne blanca, pero justo bajo la cutícula una característica zona amarilla a pardo-amarilla (visible en sección longitudinal/transversal) — en la amanita rojiza falta esta capa amarilla.","Color del sombrero de la amanita real: pardo cuero a pardo-gris oscuro con copos del velo amarillentos a gris-blancos, que se pueden limpiar; amanita rojiza: pardo-rojizo a pardo carne con restos de piel grises a teñidos de rojizo.","La amanita real crece como simbionte del abeto rojo casi solo en bosque ácido de coníferas (más bien montaña/altitudes elevadas) — la amanita rojiza prefiere bosques de frondosas y mixtos, también a baja altitud y ampliamente distribuida.","La amanita real contiene ácido iboténico/muscimol como la amanita matamoscas roja (síndrome panterínico: confusión, alucinaciones, convulsiones, en mayores cantidades colapso circulatorio/parálisis respiratoria) — no es un hongo comestible, ni siquiera cocinado."}',false),
('amanita_rubescens','fliegenpilz-roetlich','fr','L''amanite royale a un chapeau brun cuir à brun-gris foncé avec des flocons de voile gris-jaunâtre et une zone jaune à brun-jaune sous la cuticule; l''amanite rougissante rougit en rose à rouge vineux aux endroits rongés ou pressés et ne présente pas cette zone sous-cuticulaire jaune.','Toutes deux ont une odeur fongique discrète — l''odeur n''aide PAS ici à les distinguer, ce sont donc le rougissement et la couche jaune sous la cuticule qui sont les caractères décisifs.','L''amanite royale uniquement en forêt de conifères acide comme symbiote de l''épicéa (plutôt en montagne); l''amanite rougissante largement répandue en forêt de feuillus, de conifères et mixte, aussi à basse altitude.','Les deux ont une sporée blanche — la couleur de la sporée ne les sépare pas; déterminants sont le rougissement et la zone sous-cuticulaire jaune sous la cuticule.','Chez les amanites à chapeau brun, TOUJOURS couper la chair et observer 10-15 min: si elle rougit rose/rouge vineux = amanite rougissante; si elle reste blanche avec une couche jaune juste sous la cuticule = amanite royale toxique, à laisser. En cas de doute sur les amanites à lames, renoncer en règle générale.','{"L''amanite rougissante (comestible) rougit nettement, lors de blessure, pression et attaque de vers, en rouge chair à rouge vineux/rose — l''amanite royale brune (Amanita regalis) ne le fait JAMAIS.","Amanite royale: chair blanche, mais juste sous la cuticule une zone jaune à brun-jaune caractéristique (visible en coupe longitudinale/transversale) — chez l''amanite rougissante cette couche jaune est absente.","Couleur du chapeau de l''amanite royale: brun cuir à brun-gris foncé avec des flocons de voile jaunâtres à gris-blanc, essuyables; amanite rougissante: brun-rougeâtre à brun chair avec des restes de voile gris à teintés de rougeâtre.","L''amanite royale pousse comme symbiote de l''épicéa presque uniquement en forêt de conifères acide (plutôt montagne/altitudes élevées) — l''amanite rougissante préfère les forêts de feuillus et mixtes, aussi à basse altitude et largement répandue.","L''amanite royale contient de l''acide iboténique/muscimol comme l''amanite tue-mouches rouge (syndrome panthérinien: confusion, hallucinations, convulsions, à fortes doses collapsus circulatoire/paralysie respiratoire) — pas un champignon comestible, même cuit."}',false),
('amanita_rubescens','fliegenpilz-roetlich','it','L''ovolo reale ha un cappello da bruno cuoio a bruno-grigio scuro con fiocchi del velo grigio-giallastri e una zona gialla o bruno-gialla sotto la cuticola; l''amanita rosata arrossa in rosa fino a rosso vinoso nei punti rosicchiati e di pressione e non mostra questa zona sottocuticolare gialla.','Entrambe hanno un odore fungino poco appariscente — l''odore qui NON aiuta a distinguerle, perciò l''arrossamento e lo strato giallo sotto la cuticola sono i caratteri decisivi.','L''ovolo reale solo nel bosco acido di conifere come simbionte dell''abete rosso (piuttosto in montagna); l''amanita rosata ampiamente diffusa in boschi di latifoglie, conifere e misti, anche a quote più basse.','Entrambe a spore bianche — il colore della sporata non le separa; decisivi sono l''arrossamento e la zona sottocuticolare gialla sotto la cuticola.','Nelle amanite dal cappello bruno SEMPRE tagliare la carne e osservare 10-15 min: se arrossa rosa/rosso vinoso = amanita rosata; se resta bianca con uno strato giallo subito sotto la cuticola = ovolo reale tossico, da lasciare. Nel dubbio, con le amanite lamellate in generale rinunciare.','{"L''amanita rosata (commestibile) arrossa nettamente, per ferita, pressione e attacco di larve, in rosso carne fino a rosso vinoso/rosa — l''ovolo reale bruno (Amanita regalis) non lo fa MAI.","Ovolo reale: carne bianca, ma subito sotto la cuticola una caratteristica zona gialla fino a bruno-gialla (visibile in sezione longitudinale/trasversale) — nell''amanita rosata questo strato giallo manca.","Colore del cappello dell''ovolo reale: da bruno cuoio a bruno-grigio scuro con fiocchi del velo giallastri fino a grigio-bianchi, asportabili; amanita rosata: da bruno-rossastro a bruno carnicino con residui di velo grigi fino a sfumati di rossastro.","L''ovolo reale cresce come simbionte dell''abete rosso quasi solo nel bosco acido di conifere (piuttosto montagna/quote elevate) — l''amanita rosata preferisce boschi di latifoglie e misti, anche a quote basse e ampiamente diffusa.","L''ovolo reale contiene acido ibotenico/muscimolo come l''ovolo malefico rosso (sindrome panterinica: confusione, allucinazioni, convulsioni, in dosi maggiori collasso circolatorio/paralisi respiratoria) — non è un fungo commestibile, nemmeno cotto."}',false),
('amanita_strobiliformis','fliegenpilz_var_alba','en','Warted amanita (A. strobiliformis): large, soft, wipeable mealy veil patches on the cap, unstriated bulb margin; white fly agaric: warted belted veil patches on the cap and a striated-rimmed bulb.','Warted amanita pleasant when young, unpleasant when old; white fly agaric inconspicuous — smell does not separate reliably.','Fly agaric var. alba under birch/conifer on acidic soil; Amanita strobiliformis on calcareous broadleaf-forest soil.','Both with white spore print — not a distinguishing feature.','For EVERY white Amanita, fully dig out the stem base and check the bulb, veil belt and striation — eat white amanitas only with absolute certainty of identification.','{"The warted amanita bears soft, mealy-cottony, easily wipeable veil patches and NO striated bulb margin; the white fly agaric has warted belted veil remnants and a distinctly striated-rimmed bulb base","In the white fly agaric the ring is membranous-hanging with a toothed margin and the stem base shows concentric veil belt rings; in the warted amanita these belt zones are absent","Habitat check: white fly agaric under birch/pine/spruce (mycorrhiza, acidic soils); warted amanita on warm calcareous broadleaf-forest soils","When in doubt, leave both standing — NEVER eat an all-white Amanita without sure identification (the phalloides/virosa group is deadly)"}',false),
('amanita_strobiliformis','fliegenpilz_var_alba','es','Amanita de velo (A. strobiliformis): grandes copos harinosos blandos y limpiables en el sombrero, margen del bulbo no estriado; amanita matamoscas blanca: copos verrugosos en cinturones sobre el sombrero y bulbo estriado-marginado.','Amanita de velo joven agradable, vieja desagradable; amanita matamoscas blanca discreta — el olor no separa con seguridad.','Matamoscas var. alba bajo abedul/conífera en suelo ácido; Amanita strobiliformis en suelo calcáreo de bosque de frondosas.','Ambas con esporada blanca — sin carácter distintivo.','Para CUALQUIER amanita blanca, desenterrar completamente la base del pie y comprobar bulbo, cinturón de velo y estriación — consumir las amanitas blancas solo con certeza de determinación absoluta.','{"La amanita de velo lleva copos de velo blandos, harinoso-algodonosos, fácilmente limpiables y NINGÚN margen de bulbo estriado; la amanita matamoscas blanca tiene restos de velo verrugosos en cinturón y una base de bulbo claramente estriado-marginada","En la amanita matamoscas blanca el anillo es membranoso-colgante con margen dentado y la base del pie muestra anillos concéntricos de velo; en la amanita de velo faltan estas zonas en cinturón","Comprobación del hábitat: amanita matamoscas blanca bajo abedul/pino/abeto rojo (micorriza, suelos ácidos); amanita de velo en suelos calcáreos cálidos de bosque de frondosas","En caso de duda, dejar ambas en su sitio — NUNCA consumir una amanita totalmente blanca sin determinación segura (el grupo phalloides/virosa es mortal)"}',false),
('amanita_strobiliformis','fliegenpilz_var_alba','fr','Amanite à voile (A. strobiliformis) : grands flocons farineux mous et essuyables sur le chapeau, marge du bulbe non striée ; amanite tue-mouches blanche : flocons verruqueux en bandes sur le chapeau et bulbe strié-marginé.','Amanite à voile jeune agréable, vieille désagréable ; amanite tue-mouches blanche discrète — l''odeur ne sépare pas de façon sûre.','Amanite tue-mouches var. alba sous bouleau/conifère sur sol acide ; Amanita strobiliformis sur sol calcaire de forêt feuillue.','Toutes deux à sporée blanche — pas de caractère distinctif.','Pour TOUTE amanite blanche, déterrer entièrement la base du pied et vérifier bulbe, ceinture de voile et striation — ne consommer les amanites blanches qu''avec une certitude de détermination absolue.','{"L''amanite à voile porte des flocons de voile mous, farineux-ouatés, facilement essuyables et AUCUNE marge de bulbe striée ; l''amanite tue-mouches blanche a des restes de voile verruqueux en ceinture et une base de bulbe nettement striée-marginée","Chez l''amanite tue-mouches blanche l''anneau est membraneux-pendant à marge dentelée et la base du pied montre des anneaux concentriques de voile ; chez l''amanite à voile ces zones en ceinture font défaut","Vérification de l''habitat : amanite tue-mouches blanche sous bouleau/pin/épicéa (mycorhize, sols acides) ; amanite à voile sur sols calcaires chauds de forêt feuillue","Dans le doute, laisser les deux sur place — ne JAMAIS consommer une amanite entièrement blanche sans détermination sûre (le groupe phalloides/virosa est mortel)"}',false),
('amanita_strobiliformis','fliegenpilz_var_alba','it','Amanita a velo (A. strobiliformis): grandi fiocchi farinosi molli e asportabili sul cappello, margine del bulbo non striato; ovolaccio bianco (amanita muscaria var. alba): fiocchi verrucosi a cinture sul cappello e bulbo striato-marginato.','Amanita a velo da giovane gradevole, da vecchia sgradevole; ovolaccio bianco discreto — l''odore non separa con sicurezza.','Ovolaccio var. alba sotto betulla/conifera su suolo acido; Amanita strobiliformis su suolo calcareo di bosco di latifoglie.','Entrambe con sporata bianca — nessun carattere distintivo.','Per OGNI amanita bianca dissotterrare completamente la base del gambo e controllare bulbo, cintura di velo e striatura — consumare le amanite bianche solo con assoluta certezza di determinazione.','{"L''amanita a velo porta fiocchi di velo molli, farinoso-cotonosi, facilmente asportabili e NESSUN margine del bulbo striato; l''ovolaccio bianco ha resti di velo verrucosi a cintura e una base del bulbo nettamente striato-marginata","Nell''ovolaccio bianco l''anello è membranoso-pendente con margine dentellato e la base del gambo mostra anelli concentrici di velo; nell''amanita a velo queste zone a cintura mancano","Verifica dell''habitat: ovolaccio bianco sotto betulla/pino/abete rosso (micorriza, suoli acidi); amanita a velo su suoli calcarei caldi di bosco di latifoglie","Nel dubbio lasciare entrambe sul posto — non consumare MAI un''amanita interamente bianca senza determinazione sicura (il gruppo phalloides/virosa è mortale)"}',false),
('butyriboletus_appendiculatus','caloboletus_calopus','en','Butter bolete: brown cap, yellow stipe with yellow net, weak blueing. Scarlet-stemmed bolete (bitter beech bolete): grey cap, red-yellow netted stipe, strong blueing.','Both inconspicuous — the bitter taste is the decisive distinguishing feature.','Both thermophilous in deciduous/mixed forest (oak/beech); habitat does not separate them.','Both olive-brown spore print — NOT a distinguishing feature.','Taste test (tiny piece, spit out): every bitter bolete leaves the basket — the mild butter bolete is never bitter. With a red stipe net plus strong blueing, check especially carefully.','{"The scarlet-stemmed bolete tastes strongly BITTER (stays bitter even cooked) — the butter bolete tastes mild and pleasant","Cap of the butter bolete warm brown to leather-yellow; scarlet-stemmed bolete clay-grey/grey-brown","The butter bolete blues only weakly/slowly; the scarlet-stemmed bolete blues rapidly and strongly blue-green","Butter bolete stipe yellow with a fine yellow net and a rooting extension; scarlet-stemmed bolete stipe strongly red-netted below","Flesh of the butter bolete golden-yellow and mild; bitter in the scarlet-stemmed bolete"}',false),
('butyriboletus_appendiculatus','caloboletus_calopus','es','Boleto apendiculado: sombrero pardo, pie amarillo con retículo amarillo, azuleamiento débil. Boleto de pie hermoso: sombrero gris, pie con retículo rojo-amarillo, azuleamiento marcado.','Ambos poco llamativos — el sabor amargo es el carácter de separación decisivo.','Ambos termófilos en bosque de frondosas/mixto (roble/haya); el hábitat no los separa.','Ambos con esporada pardo-oliva — NO es un carácter distintivo.','Prueba de sabor (trocito mínimo, escupir): todo boleto amargo sale de la cesta — el dulce boleto apendiculado nunca es amargo. Con retículo del pie rojo más azuleamiento marcado, comprobar con especial cuidado.','{"El boleto de pie hermoso sabe fuertemente AMARGO (sigue amargo incluso cocinado) — el boleto apendiculado sabe suave y agradable","Sombrero del boleto apendiculado pardo cálido a amarillo cuero; boleto de pie hermoso gris arcilloso/gris-pardo","El boleto apendiculado azulea solo débil/lentamente; el boleto de pie hermoso azulea rápida e intensamente azul-verde","Pie del boleto apendiculado amarillo con fino retículo amarillo y prolongación radicante; pie del boleto de pie hermoso fuertemente reticulado de rojo en la parte inferior","Carne del boleto apendiculado amarillo oro y suave; amarga en el boleto de pie hermoso"}',false),
('butyriboletus_appendiculatus','caloboletus_calopus','fr','Bolet appendiculé: chapeau brun, pied jaune à réseau jaune, bleuissement faible. Bolet à beau pied: chapeau gris, pied à réseau rouge-jaune, bleuissement marqué.','Tous deux discrets — le goût amer est le caractère de séparation décisif.','Tous deux thermophiles en forêt de feuillus/mixte (chêne/hêtre); l''habitat ne sépare pas.','Tous deux à sporée brun-olive — PAS un caractère distinctif.','Test gustatif (minuscule morceau, recracher): tout bolet amer sort du panier — le bolet appendiculé doux n''est jamais amer. En cas de réseau du pied rouge plus bleuissement marqué, vérifier particulièrement.','{"Le bolet à beau pied a un goût fortement AMER (reste amer même cuit) — le bolet appendiculé a un goût doux et agréable","Chapeau du bolet appendiculé brun chaud à jaune cuir; bolet à beau pied gris argileux/gris-brun","Le bolet appendiculé ne bleuit que faiblement/lentement; le bolet à beau pied bleuit rapidement et fortement en bleu-vert","Pied du bolet appendiculé jaune à fin réseau jaune et prolongement radicant; pied du bolet à beau pied fortement réticulé de rouge en bas","Chair du bolet appendiculé jaune d''or et douce; amère chez le bolet à beau pied"}',false),
('butyriboletus_appendiculatus','caloboletus_calopus','it','Boleto appendicolato: cappello bruno, gambo giallo con reticolo giallo, viraggio al blu debole. Boleto dal bel piede: cappello grigio, gambo a reticolo rosso-giallo, viraggio al blu marcato.','Entrambi poco appariscenti — il sapore amaro è il carattere distintivo decisivo.','Entrambi termofili nel bosco di latifoglie/misto (quercia/faggio); l''habitat non separa.','Entrambi a sporata bruno-olivastra — NON è un carattere distintivo.','Prova di assaggio (pezzettino minuscolo, sputare): ogni boleto amaro esce dal cesto — il dolce boleto appendicolato non è mai amaro. Con reticolo del gambo rosso più viraggio al blu marcato, controllare con particolare attenzione.','{"Il boleto dal bel piede ha un sapore fortemente AMARO (resta amaro anche cotto) — il boleto appendicolato ha un sapore dolce e gradevole","Cappello del boleto appendicolato bruno caldo fino a giallo cuoio; boleto dal bel piede grigio argilla/grigio-bruno","Il boleto appendicolato vira al blu solo debolmente/lentamente; il boleto dal bel piede vira rapidamente e intensamente in blu-verde","Gambo del boleto appendicolato giallo con fine reticolo giallo e prolungamento radicante; gambo del boleto dal bel piede in basso fortemente reticolato di rosso","Carne del boleto appendicolato giallo oro e dolce; amara nel boleto dal bel piede"}',false),
('butyriboletus_appendiculatus','roehrling_flockenstielig','en','Clay-grey to grey-brown cap + red lower stipe part in the scarlet-stemmed bolete vs. ochre/chestnut-brown cap + mostly yellow stipe in the butter bolete.','Both inconspicuously mushroomy — smell does not separate them; the taste test (bitter vs. mild) is decisive.','Scarlet-stemmed bolete on acidic, poor soil/coniferous/montane forest; butter bolete thermophilous in deciduous forest on limestone.','Both olive-brown spore print — not a distinguishing feature.','For every bolete with a stipe net, do the bitter taste test: bitter = throw away. Net on the stipe + bitter taste = scarlet-stemmed bolete, inedible. The butter bolete is moreover protected/rare — when in doubt, leave it standing.','{"The scarlet-stemmed bolete (Caloboletus calopus) tastes distinctly BITTER — the taste test (tip of the tongue, spit out) is the safe distinguishing criterion; the butter bolete tastes mild-nutty","The scarlet-stemmed bolete has a pale clay-grey/grey-brown cap; the butter bolete has a warm ochre to chestnut-brown cap","Scarlet-stemmed bolete stipe with a strongly red area and net in the lower part; butter bolete stipe mostly yellow with a fine yellowish net and only a reddish base","Both blue under pressure/when cut (pores/flesh) — blueing alone does NOT separate them; decisive are the bitter taste and the stipe colour","The scarlet-stemmed bolete prefers acidic, poor soil (readily coniferous/montane forest); the butter bolete is thermophilous in deciduous forest on calcareous soil"}',false),
('butyriboletus_appendiculatus','roehrling_flockenstielig','es','Sombrero gris-arcilloso a gris-pardo + parte inferior del pie roja en el boleto de pie hermoso vs. sombrero ocre/pardo-castaño + pie mayoritariamente amarillo en el boleto apendiculado.','Ambos con olor fongico poco llamativo — el olor no los separa; la prueba de sabor (amargo vs. suave) es decisiva.','Boleto de pie hermoso en suelo ácido y pobre/bosque de coníferas/de montaña; boleto apendiculado termófilo en bosque de frondosas sobre caliza.','Ambos con esporada pardo-oliva — no es un carácter distintivo.','Para todo boleto con retículo en el pie, hacer la prueba del amargor: amargo = desechar. Retículo en el pie + sabor amargo = boleto de pie hermoso, incomible. El boleto apendiculado está además protegido/es raro — en caso de duda, dejarlo.','{"El boleto de pie hermoso (Caloboletus calopus) sabe claramente AMARGO — la prueba de sabor (punta de la lengua, escupir) es el criterio de separación seguro; el boleto apendiculado sabe suave-avellanado","El boleto de pie hermoso tiene un sombrero gris-arcilloso pálido/gris-pardo; el boleto apendiculado tiene un sombrero ocre cálido a pardo-castaño","Pie del boleto de pie hermoso con una zona fuertemente roja y retículo en la parte inferior; pie del boleto apendiculado mayoritariamente amarillo con fino retículo amarillento y solo la base rojiza","Ambos azulean a la presión/al corte (poros/carne) — el azuleamiento por sí solo NO los separa; decisivos son el sabor amargo y el color del pie","El boleto de pie hermoso prefiere suelo ácido y pobre (gustosamente bosque de coníferas/de montaña); el boleto apendiculado termófilo en bosque de frondosas sobre suelo calcáreo"}',false),
('butyriboletus_appendiculatus','roehrling_flockenstielig','fr','Chapeau gris-argileux à gris-brun + partie inférieure du pied rouge chez le bolet à beau pied vs. chapeau ocre/brun-marron + pied majoritairement jaune chez le bolet appendiculé.','Tous deux à odeur fongique discrète — l''odeur ne sépare pas; le test gustatif (amer vs. doux) est décisif.','Bolet à beau pied sur sol acide et pauvre/forêt de conifères/de montagne; bolet appendiculé thermophile en forêt de feuillus sur calcaire.','Tous deux à sporée brun-olive — pas un caractère distinctif.','Pour tout bolet à réseau du pied, faire le test de l''amertume: amer = jeter. Réseau au pied + goût amer = bolet à beau pied, immangeable. Le bolet appendiculé est en outre protégé/rare — en cas de doute, le laisser.','{"Le bolet à beau pied (Caloboletus calopus) a un goût nettement AMER — le test gustatif (pointe de la langue, recracher) est le critère de séparation sûr; le bolet appendiculé a un goût doux-noisette","Le bolet à beau pied a un chapeau gris-argileux pâle/gris-brun; le bolet appendiculé a un chapeau ocre chaud à brun-marron","Pied du bolet à beau pied avec une zone fortement rouge et un réseau dans la partie inférieure; pied du bolet appendiculé majoritairement jaune avec un fin réseau jaunâtre et seulement la base rougeâtre","Tous deux bleuissent à la pression/coupe (pores/chair) — le bleuissement seul ne sépare PAS; décisifs sont le goût amer et la couleur du pied","Le bolet à beau pied préfère un sol acide et pauvre (volontiers forêt de conifères/de montagne); le bolet appendiculé thermophile en forêt de feuillus sur sol calcaire"}',false),
('butyriboletus_appendiculatus','roehrling_flockenstielig','it','Cappello grigio-argilla a grigio-bruno + parte inferiore del gambo rossa nel boleto dal bel piede vs. cappello ocra/bruno-castano + gambo prevalentemente giallo nel boleto appendicolato.','Entrambi con odore fungino poco appariscente — l''odore non separa; il test di assaggio (amaro vs. dolce) è decisivo.','Boleto dal bel piede su suolo acido e povero/bosco di conifere/di montagna; boleto appendicolato termofilo nel bosco di latifoglie su calcare.','Entrambi a sporata bruno-olivastra — non è un carattere distintivo.','Per ogni boleto con reticolo sul gambo fare la prova dell''amaro: amaro = buttare. Reticolo sul gambo + sapore amaro = boleto dal bel piede, immangiabile. Il boleto appendicolato è inoltre protetto/raro — nel dubbio lasciarlo.','{"Il boleto dal bel piede (Caloboletus calopus) ha un sapore nettamente AMARO — la prova di assaggio (punta della lingua, sputare) è il criterio distintivo sicuro; il boleto appendicolato ha un sapore dolce-nocciola","Il boleto dal bel piede ha un cappello grigio-argilla pallido/grigio-bruno; il boleto appendicolato ha un cappello ocra caldo fino a bruno-castano","Gambo del boleto dal bel piede con una zona fortemente rossa e reticolo nella parte inferiore; gambo del boleto appendicolato prevalentemente giallo con fine reticolo giallastro e solo la base rossastra","Entrambi virano al blu alla pressione/al taglio (pori/carne) — il viraggio da solo NON separa; decisivi sono il sapore amaro e il colore del gambo","Il boleto dal bel piede preferisce suolo acido e povero (volentieri bosco di conifere/di montagna); il boleto appendicolato termofilo nel bosco di latifoglie su suolo calcareo"}',false),
('butyriboletus_appendiculatus','rubroboletus_legaliae','en','Red pores + pale pink/grey-pink cap in Le Gal''''s bolete vs. yellow pores + ochre/chestnut-brown cap in the butter bolete.','Le Gal''''s bolete smells of celery/lovage; butter bolete mild and mushroomy.','Both thermophilous in deciduous forest (oak/beech) on limestone — habitat overlaps, does not separate.','Both olive-brown — not a distinguishing feature.','Golden bolete rule: red pores = not in the basket without certain identification. Only yellow pores + mild flesh + absence of celery smell in the butter bolete are harmless (it is also protected/rare).','{"Le Gal''''s bolete has RED to orange-red/blood-red pores; the butter bolete has YELLOW pores — red pores in boletes are a general warning sign","Le Gal''''s bolete has a pale white-/grey-pink to old-rose cap; the butter bolete a warm ochre to chestnut-brown cap","Le Gal''''s bolete smells of celery/lovage and is toxic/intolerable even cooked; the butter bolete smells mildly mushroomy and is mild-edible","Le Gal''''s bolete stipe with a red net on a reddish-orange ground; butter bolete stipe mostly yellow with a fine yellowish net","Both can blue — blueing alone is NOT enough; decisive is the pore colour (red vs. yellow) plus celery smell"}',false),
('butyriboletus_appendiculatus','rubroboletus_legaliae','es','Poros rojos + sombrero rosa pálido/gris-rosado en el boleto de Le Gal vs. poros amarillos + sombrero ocre/pardo-castaño en el boleto apendiculado.','Boleto de Le Gal con olor a apio/levístico; boleto apendiculado suave y fongico.','Ambos termófilos en bosque de frondosas (roble/haya) sobre caliza — el hábitat se solapa, no los separa.','Ambos pardo-oliva — no es un carácter distintivo.','Regla de oro de los boletos: poros rojos = no a la cesta sin determinación segura. Solo poros amarillos + carne suave + ausencia de olor a apio en el boleto apendiculado son inofensivos (él mismo protegido/raro).','{"El boleto de Le Gal tiene poros ROJOS a rojo-anaranjado/rojo sangre; el boleto apendiculado tiene poros AMARILLOS — los poros rojos en los boletos son una señal de alarma general","El boleto de Le Gal tiene un sombrero pálido blanco-/gris-rosado a rosa viejo; el boleto apendiculado un sombrero ocre cálido a pardo-castaño","El boleto de Le Gal huele a apio/levístico y es tóxico/mal tolerado incluso cocinado; el boleto apendiculado huele suavemente a hongo y es suave-comestible","Pie del boleto de Le Gal con retículo rojo sobre fondo rojizo-anaranjado; pie del boleto apendiculado mayoritariamente amarillo con fino retículo amarillento","Ambos pueden azulear — el azuleamiento por sí solo NO basta; decisivo es el color de los poros (rojo vs. amarillo) más el olor a apio"}',false),
('butyriboletus_appendiculatus','rubroboletus_legaliae','fr','Pores rouges + chapeau rose pâle/gris-rosé chez le bolet de Le Gal vs. pores jaunes + chapeau ocre/brun-marron chez le bolet appendiculé.','Bolet de Le Gal sentant le céleri/la livèche; bolet appendiculé doux et fongique.','Tous deux thermophiles en forêt de feuillus (chêne/hêtre) sur calcaire — l''habitat se chevauche, ne sépare pas.','Tous deux brun-olive — pas un caractère distinctif.','Règle d''or des bolets: pores rouges = pas dans le panier sans détermination sûre. Seuls des pores jaunes + chair douce + absence d''odeur de céleri chez le bolet appendiculé sont sans danger (lui-même protégé/rare).','{"Le bolet de Le Gal a des pores ROUGES à rouge-orangé/rouge sang; le bolet appendiculé a des pores JAUNES — des pores rouges chez les bolets sont un signal d''alarme général","Le bolet de Le Gal a un chapeau pâle blanc-/gris-rosé à vieux rose; le bolet appendiculé un chapeau ocre chaud à brun-marron","Le bolet de Le Gal sent le céleri/la livèche et est toxique/mal toléré même cuit; le bolet appendiculé sent doucement le champignon et est doux-comestible","Pied du bolet de Le Gal à réseau rouge sur fond rougeâtre-orangé; pied du bolet appendiculé majoritairement jaune à fin réseau jaunâtre","Tous deux peuvent bleuir — le bleuissement seul ne suffit PAS; décisives sont la couleur des pores (rouge vs. jaune) plus l''odeur de céleri"}',false),
('butyriboletus_appendiculatus','rubroboletus_legaliae','it','Pori rossi + cappello rosa pallido/grigio-rosato nel boleto di Le Gal vs. pori gialli + cappello ocra/bruno-castano nel boleto appendicolato.','Boleto di Le Gal odore di sedano/levistico; boleto appendicolato dolce e fungino.','Entrambi termofili nel bosco di latifoglie (quercia/faggio) su calcare — l''habitat si sovrappone, non separa.','Entrambi bruno-olivastri — non è un carattere distintivo.','Regola d''oro dei boleti: pori rossi = non nel cesto senza determinazione sicura. Solo pori gialli + carne dolce + assenza di odore di sedano nel boleto appendicolato sono innocui (esso stesso protetto/raro).','{"Il boleto di Le Gal ha pori ROSSI fino a rosso-arancio/rosso sangue; il boleto appendicolato ha pori GIALLI — pori rossi nei boleti sono un segnale d''allarme generale","Il boleto di Le Gal ha un cappello pallido bianco-/grigio-rosato fino a rosa antico; il boleto appendicolato un cappello ocra caldo fino a bruno-castano","Il boleto di Le Gal odora di sedano/levistico ed è tossico/mal tollerato anche cotto; il boleto appendicolato odora delicatamente di fungo ed è dolce-commestibile","Gambo del boleto di Le Gal con reticolo rosso su fondo rossastro-arancio; gambo del boleto appendicolato prevalentemente giallo con fine reticolo giallastro","Entrambi possono virare al blu — il viraggio da solo NON basta; decisivi sono il colore dei pori (rosso vs. giallo) più l''odore di sedano"}',false),
('butyriboletus_appendiculatus','rubroboletus_satanas','en','The butter bolete has yellow pores and a yellow stipe, the Satan''''s bolete red pores and a red-netted stipe.','The Satan''''s bolete smells of carrion when old; the butter bolete pleasantly mushroomy.','Both calcicolous in warm oak/beech forests — not a distinguishing feature.','Both olive-brown spore print — not separating.','With red or orange pores always leave it standing — yellow-pored thick-footed boletes are edible, red-pored ones are taboo.','{"The butter bolete (thick-footed bolete) has YELLOW pores, the Satan''''s bolete red to orange pores.","The butter bolete blues only weakly in the yellow flesh and has no carrion smell; the Satan''''s bolete smells repulsively of carrion when old.","The butter bolete has a brown, velvety cap; the Satan''''s bolete when young a pale, chalk-white to whitish-grey-green cap.","Butter bolete stipe yellow with a fine yellow net, often with a rooting appendage; Satan''''s bolete stipe red-netted and bulbous.","Both grow on limestone in warm deciduous forest — the red pore colour is the safety criterion."}',false),
('butyriboletus_appendiculatus','rubroboletus_satanas','es','El boleto apendiculado tiene poros amarillos y pie amarillo, el boleto de Satanás poros rojos y pie reticulado de rojo.','El boleto de Satanás huele, de viejo, a carroña; el boleto apendiculado agradablemente a hongo.','Ambos calcícolas en cálidos robledales/hayedos — no es un carácter distintivo.','Ambos con esporada pardo-oliva — no los separa.','Con poros rojos o anaranjados dejar siempre en el sitio — los boletos de pie grueso con poros amarillos son comestibles, los de poros rojos están prohibidos.','{"El boleto apendiculado (boleto de pie grueso) tiene poros AMARILLOS, el boleto de Satanás poros de rojos a anaranjados.","El boleto apendiculado azulea solo débilmente en la carne amarilla y no tiene olor a carroña; el boleto de Satanás huele, de viejo, repugnantemente a carroña.","El boleto apendiculado tiene un sombrero pardo, aterciopelado; el boleto de Satanás, de joven, un sombrero claro, blanco calcáreo a blanco-grisáceo-verdoso.","Pie del boleto apendiculado amarillo con fino retículo amarillo, a menudo con apéndice radicante; pie del boleto de Satanás reticulado de rojo y bulboso.","Ambos crecen sobre caliza en bosque cálido de frondosas — el color rojo de los poros es el criterio de seguridad."}',false),
('butyriboletus_appendiculatus','rubroboletus_satanas','fr','Le bolet appendiculé a des pores jaunes et un pied jaune, le bolet Satan des pores rouges et un pied réticulé de rouge.','Le bolet Satan sent, en vieillissant, la charogne; le bolet appendiculé est agréablement fongique.','Tous deux calcicoles dans des chênaies/hêtraies chaudes — pas un caractère distinctif.','Tous deux à sporée brun-olive — non séparateur.','Avec des pores rouges ou orange, toujours laisser sur place — les bolets à pied épais à pores jaunes sont comestibles, ceux à pores rouges sont à proscrire.','{"Le bolet appendiculé (bolet à pied épais) a des pores JAUNES, le bolet Satan des pores rouges à orange.","Le bolet appendiculé ne bleuit que faiblement dans sa chair jaune et n''a pas d''odeur de charogne; le bolet Satan sent, en vieillissant, de façon répugnante la charogne.","Le bolet appendiculé a un chapeau brun, velouté; le bolet Satan, jeune, un chapeau clair, blanc calcaire à blanc-grisâtre-verdâtre.","Pied du bolet appendiculé jaune à fin réseau jaune, souvent avec un appendice radicant; pied du bolet Satan réticulé de rouge et bulbeux.","Tous deux poussent sur calcaire en forêt de feuillus chaude — la couleur rouge des pores est le critère de sécurité."}',false),
('butyriboletus_appendiculatus','rubroboletus_satanas','it','Il boleto appendicolato ha pori gialli e gambo giallo, il boleto di Satana pori rossi e gambo reticolato di rosso.','Il boleto di Satana odora, da vecchio, di carogna; il boleto appendicolato gradevolmente fungino.','Entrambi calcicoli in caldi querceti/faggeti — non è un carattere distintivo.','Entrambi a sporata bruno-olivastra — non separa.','Con pori rossi o arancioni lasciare sempre sul posto — i boleti dal piede grosso a pori gialli sono commestibili, quelli a pori rossi sono vietati.','{"Il boleto appendicolato (boleto dal piede grosso) ha pori GIALLI, il boleto di Satana pori da rossi ad arancioni.","Il boleto appendicolato vira al blu solo debolmente nella carne gialla e non ha odore di carogna; il boleto di Satana odora, da vecchio, in modo ripugnante di carogna.","Il boleto appendicolato ha un cappello bruno, vellutato; il boleto di Satana, da giovane, un cappello chiaro, bianco calcareo fino a bianco-grigio-verdastro.","Gambo del boleto appendicolato giallo con fine reticolo giallo, spesso con appendice radicante; gambo del boleto di Satana reticolato di rosso e bulboso.","Entrambi crescono su calcare nel caldo bosco di latifoglie — il colore rosso dei pori è il criterio di sicurezza."}',false),
('calocybe_gambosa','hebeloma_crustuliniforme','en','St George''s mushroom cream-white with densely crowded white gills; Hebeloma (poison pie) clay-grey pale with weeping, later rust-brown gills.','St George''s mushroom mealy-cucumbery (edible marker); Hebeloma radish-like (toxicity hint).','Both can appear in spring — St George''s mushroom classically around St George''s Day (late April/May) in fairy rings on meadows/forest edges.','St George''s mushroom with white spore print vs. rust-olive in the weeping Hebeloma — the most reliable distinguishing feature.','Always take a spore print: white = possible St George''s mushroom, rust/brown = Hebeloma and discard; additionally check mealy smell (good) vs. radish smell (warning).','{"St George''s mushroom smells strongly mealy-cucumbery; the weeping Hebeloma smells radish-like — the radish smell is a warning sign","St George''s mushroom has a WHITE spore print; Hebeloma crustuliniforme has a rust to brown-olive spore print","In the weeping Hebeloma, watery droplets hang on the gill edges when young and leave brown spore spots — in St George''s mushroom these weeping gills are absent","St George''s mushroom has densely crowded, white, straight-attached gills when young; Hebeloma gills are pale grey-brown and turn rust-brown"}',false),
('calocybe_gambosa','hebeloma_crustuliniforme','es','Seta de San Jorge crema-blanca con láminas blancas apretadas; hebeloma («lacrimoso») gris-arcilla pálido con láminas lacrimosas y luego pardo-herrumbre.','Seta de San Jorge con olor harinoso-a pepino (marcador de comestible); hebeloma con olor a rábano (indicio de toxicidad).','Ambos pueden aparecer en primavera — la seta de San Jorge clásicamente hacia San Jorge (finales de abril/mayo) en corros de brujas en praderas/bordes de bosque.','Seta de San Jorge con esporada blanca frente a herrumbre-oliva en el hebeloma lacrimoso — carácter distintivo más seguro.','Hacer siempre una impronta de esporada: blanco = posible seta de San Jorge, herrumbre/pardo = hebeloma a descartar; comprobar además el olor harinoso (bueno) frente al olor a rábano (advertencia).','{"La seta de San Jorge huele fuertemente a harina/pepino; el hebeloma lacrimoso huele a rábano — el olor a rábano es una señal de alarma","La seta de San Jorge tiene esporada BLANCA; Hebeloma crustuliniforme tiene esporada herrumbre a pardo-oliva","En el hebeloma lacrimoso, de joven cuelgan gotitas acuosas del filo de las láminas que dejan manchas de esporas pardas — en la seta de San Jorge faltan estas láminas lacrimosas","La seta de San Jorge tiene de joven láminas apretadas, blancas, de inserción recta; las láminas del hebeloma son gris-pardas claras y viran a pardo-herrumbre"}',false),
('calocybe_gambosa','hebeloma_crustuliniforme','fr','Mousseron de la Saint-Georges crème-blanc à lamelles blanches serrées ; hébélome (« faux clitocybe larmoyant ») gris-argile pâle à lamelles larmoyantes puis brun-rouille.','Mousseron de la Saint-Georges à odeur farineuse-de concombre (marqueur de comestible) ; hébélome à odeur de raifort (indice de toxicité).','Tous deux peuvent apparaître au printemps — le mousseron classiquement vers la Saint-Georges (fin avril/mai) en ronds de sorcière sur prairies/lisières.','Mousseron à sporée blanche contre rouille-olive chez l''hébélome larmoyant — caractère de séparation le plus sûr.','Toujours faire une empreinte de sporée : blanc = mousseron possible, rouille/brun = hébélome et à rejeter ; vérifier en plus l''odeur de farine (bon) contre l''odeur de raifort (avertissement).','{"Le mousseron de la Saint-Georges sent fortement la farine/le concombre ; l''hébélome larmoyant sent le raifort — l''odeur de raifort est un signal d''alarme","Le mousseron a une sporée BLANCHE ; Hebeloma crustuliniforme a une sporée rouille à brun-olive","Chez l''hébélome larmoyant, des gouttelettes aqueuses pendent jeunes au tranchant des lamelles et laissent des taches de spores brunes — chez le mousseron ces lamelles larmoyantes font défaut","Le mousseron a jeune des lamelles serrées, blanches, droitement attachées ; les lamelles de l''hébélome sont gris-brun clair et virent au brun-rouille"}',false),
('calocybe_gambosa','hebeloma_crustuliniforme','it','Prugnolo (fungo di San Giorgio) crema-bianco con lamelle bianche fitte; hebeloma («lacrimoso») grigio-argilla pallido con lamelle lacrimanti poi bruno-ruggine.','Prugnolo dall''odore farinoso-di cetriolo (marcatore di commestibile); hebeloma dall''odore di rafano (indizio di tossicità).','Entrambi possono comparire in primavera — il prugnolo classicamente attorno a San Giorgio (fine aprile/maggio) in cerchi delle streghe su prati/margini boschivi.','Prugnolo con sporata bianca contro ruggine-oliva nell''hebeloma lacrimoso — carattere distintivo più sicuro.','Fare sempre un''impronta sporale: bianco = possibile prugnolo, ruggine/bruno = hebeloma da scartare; controllare inoltre l''odore farinoso (buono) contro l''odore di rafano (avvertimento).','{"Il prugnolo odora fortemente di farina/cetriolo; l''hebeloma lacrimoso odora di rafano — l''odore di rafano è un segnale di allarme","Il prugnolo ha sporata BIANCA; Hebeloma crustuliniforme ha sporata ruggine fino a bruno-oliva","Nell''hebeloma lacrimoso da giovane pendono goccioline acquose dal filo delle lamelle che lasciano macchie sporali brune — nel prugnolo queste lamelle lacrimanti mancano","Il prugnolo ha da giovane lamelle fitte, bianche, attaccate dritte; le lamelle dell''hebeloma sono grigio-brune chiare e virano al bruno-ruggine"}',false),
('calocybe_gambosa','hebeloma_sinapizans','en','St George''s mushroom cream-white, compact, white gills; Hebeloma (bitter poison pie) clay-brown with grey-brown gills and a bulbous base.','St George''s mushroom mealy-cucumbery; bitter poison pie with an intense radish smell.','St George''s mushroom appears in spring (May) in fairy rings; Hebeloma sinapizans mainly August–October in broadleaf forest (beech, limestone).','St George''s mushroom with white spore print vs. rust-brown in the bitter poison pie — the most reliable distinguishing feature.','Spore print + smell decide: white powder and mealy smell = possible St George''s mushroom; rust-brown powder and radish smell = Hebeloma and absolutely discard.','{"St George''s mushroom smells of meal/cucumber; the bitter poison pie smells strongly of radish and tastes bitter — the radish smell is a warning sign","St George''s mushroom has a WHITE spore print; Hebeloma sinapizans has a rust-brown spore print","St George''s mushroom gills white and crowded when young; Hebeloma gills grey-brown, emarginate-attached, NOT weeping, often with a cone-like projection into the stem (lengthwise cut)","The bitter poison pie is squat-fleshy on calcareous soils under beech, main growth late in the year"}',false),
('calocybe_gambosa','hebeloma_sinapizans','es','Seta de San Jorge crema-blanca, compacta, láminas blancas; hebeloma (de rábano) pardo-arcilla con láminas gris-pardas y base bulbosa.','Seta de San Jorge harinosa-a pepino; hebeloma de rábano con olor a rábano intenso.','La seta de San Jorge aparece en primavera (mayo) en corros de brujas; Hebeloma sinapizans sobre todo de agosto a octubre en bosque de frondosas (haya, caliza).','Seta de San Jorge con esporada blanca frente a herrumbre-pardo en el hebeloma de rábano — carácter distintivo más seguro.','La impronta de esporada + el olor deciden: polvo blanco y olor harinoso = posible seta de San Jorge; polvo herrumbre-pardo y olor a rábano = hebeloma y descartar imperativamente.','{"La seta de San Jorge huele a harina/pepino; el hebeloma de rábano huele fuertemente a rábano y sabe amargo — el olor a rábano es una señal de alarma","La seta de San Jorge tiene esporada BLANCA; Hebeloma sinapizans tiene esporada herrumbre-parda","Láminas de la seta de San Jorge de joven blancas y apretadas; láminas del hebeloma gris-pardas, escotado-adheridas, NO lacrimosas, a menudo con una prolongación cónica en el pie (corte longitudinal)","El hebeloma de rábano es rechoncho-carnoso en suelos calcáreos bajo haya, crecimiento principal tarde en el año"}',false),
('calocybe_gambosa','hebeloma_sinapizans','fr','Mousseron de la Saint-Georges crème-blanc, compact, lamelles blanches ; hébélome à odeur de raifort (« faux clitocybe ») brun-argile à lamelles gris-brun et base bulbeuse.','Mousseron de la Saint-Georges farineux-de concombre ; hébélome à odeur de raifort intense.','Mousseron apparaît au printemps (mai) en ronds de sorcière ; Hebeloma sinapizans surtout d''août à octobre en forêt feuillue (hêtre, calcaire).','Mousseron à sporée blanche contre rouille-brun chez l''hébélome à odeur de raifort — caractère de séparation le plus sûr.','L''empreinte de sporée + l''odeur décident : poudre blanche et odeur de farine = mousseron possible ; poudre rouille-brun et odeur de raifort = hébélome et à rejeter impérativement.','{"Le mousseron sent la farine/le concombre ; l''hébélome à odeur de raifort sent fortement le raifort et a un goût amer — l''odeur de raifort est un signal d''alarme","Le mousseron a une sporée BLANCHE ; Hebeloma sinapizans a une sporée rouille-brun","Lamelles du mousseron jeunes blanches et serrées ; lamelles de l''hébélome gris-brun, échancrées-attachées, NON larmoyantes, souvent avec un prolongement en forme de cône dans le pied (coupe longitudinale)","L''hébélome à odeur de raifort est trapu-charnu sur sols calcaires sous hêtre, croissance principale tard dans l''année"}',false),
('calocybe_gambosa','hebeloma_sinapizans','it','Prugnolo (fungo di San Giorgio) crema-bianco, compatto, lamelle bianche; hebeloma (di rafano) bruno-argilla con lamelle grigio-brune e base bulbosa.','Prugnolo farinoso-di cetriolo; hebeloma di rafano dall''odore di rafano intenso.','Il prugnolo compare in primavera (maggio) in cerchi delle streghe; Hebeloma sinapizans soprattutto da agosto a ottobre nel bosco di latifoglie (faggio, calcare).','Prugnolo con sporata bianca contro ruggine-bruno nell''hebeloma di rafano — carattere distintivo più sicuro.','L''impronta sporale + l''odore decidono: polvere bianca e odore di farina = possibile prugnolo; polvere ruggine-bruna e odore di rafano = hebeloma da scartare assolutamente.','{"Il prugnolo odora di farina/cetriolo; l''hebeloma di rafano odora fortemente di rafano e ha sapore amaro — l''odore di rafano è un segnale di allarme","Il prugnolo ha sporata BIANCA; Hebeloma sinapizans ha sporata ruggine-bruna","Lamelle del prugnolo da giovani bianche e fitte; lamelle dell''hebeloma grigio-brune, smarginato-attaccate, NON lacrimanti, spesso con un prolungamento conico nel gambo (taglio longitudinale)","L''hebeloma di rafano è tozzo-carnoso su suoli calcarei sotto faggio, crescita principale tardi nell''anno"}',false),
('calocybe_gambosa','inocybe_rimosa','en','The ochre-brown, conical-umbonate and radially split cap of the fibrecap stands in clear contrast to the smooth, whitish, convex cap of St. George''''s mushroom.','St. George''''s mushroom: distinctly mealy-cucumber (fresh flour); fibrecap: spermatic/sour-earthy — the mealy smell is the most important confirmatory feature for St. George''''s mushroom.','Both in meadows, hedges, path and forest edges in spring; habitat and season overlap, therefore separable only by smell and spore colour.','St. George''''s mushroom: WHITE spore print; conical fibrecap: tobacco-/grey-brown spore print — an unambiguous distinguishing feature.','Harvest St. George''''s mushrooms only if they clearly smell mealy-cucumber AND give a white spore print; every conical, radially split cap with brown spore dust and an unpleasant smell is a fibrecap — discard at once.','{"St. George''''s mushroom smells strongly mealy-cucumber; the conical fibrecap smells spermatic/earthy-unpleasant","St. George''''s mushroom cap whitish to cream, smooth, with an inrolled margin; fibrecap cap ochre/straw-brown, conical-umbonate and radially SPLIT (cracked cap surface)","St. George''''s mushroom gills white to cream, crowded; fibrecap gills pale when young, soon clay-grey-brown","Fibrecaps contain muscarine (sweating, salivation, visual disturbance 15-120 min) — the closely related deadly fibrecap (Inocybe erubescens) at the same site has even caused fatalities; St. George''''s mushroom is non-toxic","Both appear in spring (April/May) at the same site — confusion is dangerous precisely for this reason"}',false),
('calocybe_gambosa','inocybe_rimosa','es','El sombrero ocre-pardo, cónico-mamelonado y rasgado radialmente del inocibe contrasta claramente con el sombrero liso, blanquecino y convexo de la seta de San Jorge.','Seta de San Jorge: marcadamente harinoso-a pepino (harina fresca); inocibe: espermático/ácido-terroso — el olor a harina es el carácter de confirmación más importante para la seta de San Jorge.','Ambos en prados, setos, bordes de caminos y linderos de bosque en primavera; el hábitat y la estación se solapan, por lo que solo separables por olor y color de la esporada.','Seta de San Jorge: esporada BLANCA; inocibe cónico: esporada pardo-tabaco/pardo-gris — carácter distintivo inequívoco.','Recolectar las setas de San Jorge solo si huelen claramente a harina-pepino Y dan esporada blanca; todo sombrero cónico, rasgado radialmente, con polvo de esporas pardo y olor desagradable es un inocibe — desechar de inmediato.','{"La seta de San Jorge huele fuertemente a harina-pepino; el inocibe cónico huele a espermático/terroso-desagradable","Sombrero de la seta de San Jorge blanquecino a crema, liso, con margen enrollado; sombrero del inocibe ocre/pardo paja, cónico-mamelonado y RASGADO radialmente (superficie del sombrero agrietada)","Láminas de la seta de San Jorge blancas a crema, apretadas; láminas del inocibe pálidas de jóvenes, pronto pardo-gris arcilloso","Los inocibes contienen muscarina (sudoración, salivación, trastornos de la visión 15-120 min) — el inocibe de Patouillard muy afín (Inocybe erubescens), en el mismo lugar, ha causado incluso muertes; la seta de San Jorge es inocua","Ambos aparecen en primavera (abril/mayo) en el mismo lugar — la confusión es peligrosa precisamente por ello"}',false),
('calocybe_gambosa','inocybe_rimosa','fr','Le chapeau ocre-brun, conique-mamelonné et déchiré radialement de l''inocybe contraste nettement avec le chapeau lisse, blanchâtre et convexe du mousseron de la Saint-Georges.','Mousseron de la Saint-Georges: nettement farineux-concombre (farine fraîche); inocybe: spermatique/aigre-terreux — l''odeur de farine est le caractère de confirmation le plus important pour le mousseron.','Tous deux dans les prés, haies, bords de chemins et lisières au printemps; l''habitat et la saison se chevauchent, d''où une séparation uniquement par l''odeur et la couleur de la sporée.','Mousseron de la Saint-Georges: sporée BLANCHE; inocybe à chapeau conique: sporée brun-tabac/brun-gris — caractère distinctif sans équivoque.','Ne récolter les mousserons que s''ils sentent clairement la farine-concombre ET donnent une sporée blanche; tout chapeau conique, déchiré radialement, à poussière sporale brune et à odeur désagréable est un inocybe — à éliminer aussitôt.','{"Le mousseron de la Saint-Georges sent fortement la farine-concombre; l''inocybe à chapeau conique sent le spermatique/terreux-désagréable","Chapeau du mousseron blanchâtre à crème, lisse, à marge enroulée; chapeau de l''inocybe ocre/brun paille, conique-mamelonné et DÉCHIRÉ radialement (surface du chapeau fissurée)","Lames du mousseron blanches à crème, serrées; lames de l''inocybe jeunes pâles, bientôt brun-gris argileux","Les inocybes contiennent de la muscarine (sueurs, salivation, troubles de la vue 15-120 min) — l''inocybe de Patouillard très proche (Inocybe erubescens), au même endroit, a même provoqué des décès; le mousseron est inoffensif","Tous deux apparaissent au printemps (avril/mai) au même endroit — la confusion est dangereuse précisément pour cette raison"}',false),
('calocybe_gambosa','inocybe_rimosa','it','Il cappello ocra-bruno, conico-umbonato e fessurato radialmente dell''inocibe contrasta nettamente con il cappello liscio, biancastro e convesso del prugnolo.','Prugnolo: marcatamente farinoso-cetriolo (farina fresca); inocibe: spermatico/acidulo-terroso — l''odore di farina è il carattere di conferma più importante per il prugnolo.','Entrambi in prati, siepi, bordi di sentieri e margini boschivi in primavera; l''habitat e la stagione si sovrappongono, perciò separabili solo tramite odore e colore della sporata.','Prugnolo: sporata BIANCA; inocibe conico: sporata bruno-tabacco/bruno-grigia — carattere distintivo inequivocabile.','Raccogliere i prugnoli solo se odorano chiaramente di farina-cetriolo E danno sporata bianca; ogni cappello conico, fessurato radialmente, con polvere sporale bruna e odore sgradevole è un inocibe — eliminare subito.','{"Il prugnolo odora fortemente di farina-cetriolo; l''inocibe conico odora di spermatico/terroso-sgradevole","Cappello del prugnolo biancastro fino a color crema, liscio, con margine arrotolato; cappello dell''inocibe ocra/bruno paglia, conico-umbonato e FESSURATO radialmente (superficie del cappello screpolata)","Lamelle del prugnolo bianche fino a crema, fitte; lamelle dell''inocibe da giovani pallide, presto bruno-grigio argilla","Gli inocibi contengono muscarina (sudorazione, salivazione, disturbi della vista 15-120 min) — l''inocibe di Patouillard molto affine (Inocybe erubescens), nello stesso luogo, ha causato perfino decessi; il prugnolo è innocuo","Entrambi compaiono in primavera (aprile/maggio) nello stesso luogo — la confusione è pericolosa proprio per questo"}',false),
('calvatia_gigantea','scleroderma_citrinum','en','Giant puffball large, white, smooth and soft-shelled; common earthball small (3-10 cm), yellow-brown, hard and coarsely areolate-scurfy.','Earthball unpleasantly metallic; young giant puffball mild and pleasant.','Giant puffball on nutrient-rich, fertilised meadows, pastures, gardens and nettle margins; earthball on acidic forest soil, mycorrhizal near trees.','Earthball, when cut, early brown-black-spored; young giant puffball pure white inside without dark spore mass — edible only in this state.','Eat only large white puffballs that are COMPLETELY snow-white and homogeneous in longitudinal section. Any dark marbling, yellowish discolouration or hard shell means either overripe (inedible) or earthball (toxic).','{"Confusion in practice only with YOUNG/small specimens: mature giant puffballs (15-50 cm) are unmistakable, but young small ones are spherical and whitish like a puffball.","Giant puffball, when cut and young, uniformly snow-white and soft like cotton wool; earthball, when cut already young, dark/greyish marbled.","The earthball has a hard, thick, tough shell; the giant puffball a thin, soft, leathery casing.","The earthball smells metallic-unpleasant; the young giant puffball mildly mushroomy."}',false),
('calvatia_gigantea','scleroderma_citrinum','es','Bejín gigante grande, blanco, liso y de cáscara blanda; escleroderma pequeño (3-10 cm), pardo-amarillo, duro y de superficie groseramente areolada-costrosa.','Escleroderma de olor metálico desagradable; bejín gigante joven suave y agradable.','Bejín gigante en prados ricos en nutrientes y abonados, pastos, jardines y orlas de ortigas; escleroderma sobre suelo forestal ácido, micorrízico junto a los árboles.','Escleroderma, al corte, con esporas pardo-negras tempranamente; bejín gigante joven interior blanco puro sin masa esporal oscura — comestible solo en este estado.','Comer solo los bejines grandes y blancos que, en sección longitudinal, sean COMPLETAMENTE blanco nieve y homogéneos. Todo veteado oscuro, coloración amarillenta o cáscara dura significa o sobremadurez (incomible) o escleroderma (tóxico).','{"Confusión en la práctica solo en los ejemplares JÓVENES/pequeños: los bejines gigantes adultos (15-50 cm) son inconfundibles, pero los jóvenes pequeños son esféricos y blanquecinos como un bejín.","Bejín gigante, al corte y de joven, uniformemente blanco nieve y blando como algodón; escleroderma, al corte ya de joven, veteado oscuro/grisáceo.","El escleroderma tiene una cáscara dura, gruesa y tenaz; el bejín gigante una envoltura fina, blanda y coriácea.","El escleroderma huele a metálico-desagradable; el bejín gigante joven huele suavemente a hongo."}',false),
('calvatia_gigantea','scleroderma_citrinum','fr','Vesse-de-loup géante grande, blanche, lisse et à enveloppe molle; scléroderme petit (3-10 cm), brun-jaune, dur et à surface grossièrement aréolée-croûteuse.','Scléroderme à odeur métallique désagréable; jeune vesse-de-loup géante douce et agréable.','Vesse-de-loup géante sur prairies riches et fertilisées, pâturages, jardins et ourlets d''orties; scléroderme sur sol forestier acide, mycorhizien près des arbres.','Scléroderme, à la coupe, à spores brun-noir précocement; jeune vesse-de-loup géante intérieur d''un blanc pur sans masse sporale sombre — comestible uniquement dans cet état.','Ne manger que les vesses grandes et blanches qui, en coupe longitudinale, sont COMPLÈTEMENT blanc neige et homogènes. Toute marbrure sombre, coloration jaunâtre ou enveloppe dure signifie soit surmaturité (immangeable) soit scléroderme (toxique).','{"Confusion en pratique seulement chez les JEUNES/petits exemplaires: les vesses-de-loup géantes adultes (15-50 cm) sont impossibles à confondre, mais les jeunes petites sont sphériques et blanchâtres comme une vesse.","Vesse-de-loup géante, à la coupe et jeune, uniformément blanc neige et molle comme de l''ouate; scléroderme, à la coupe déjà jeune, marbré sombre/grisâtre.","Le scléroderme a une enveloppe dure, épaisse et coriace; la vesse-de-loup géante une enveloppe fine, molle et cuir.","Le scléroderme sent le métallique-désagréable; la jeune vesse-de-loup géante sent doucement le champignon."}',false),
('calvatia_gigantea','scleroderma_citrinum','it','Vescia gigante grande, bianca, liscia e a guscio molle; scleroderma piccolo (3-10 cm), bruno-giallo, duro e a superficie grossolanamente areolata-crostosa.','Scleroderma odore metallico sgradevole; giovane vescia gigante dolce e gradevole.','Vescia gigante su prati ricchi e concimati, pascoli, giardini e bordure di ortiche; scleroderma su suolo forestale acido, micorrizico presso gli alberi.','Scleroderma, al taglio, con spore bruno-nere precocemente; giovane vescia gigante interno bianco puro senza massa sporale scura — commestibile solo in questo stato.','Mangiare solo le vesce grandi e bianche che, in sezione longitudinale, sono COMPLETAMENTE bianco neve e omogenee. Ogni marezzatura scura, colorazione giallastra o guscio duro significa o sovramaturazione (immangiabile) o scleroderma (tossico).','{"Confusione in pratica solo negli esemplari GIOVANI/piccoli: le vesce giganti adulte (15-50 cm) sono inconfondibili, ma quelle giovani piccole sono sferiche e biancastre come una vescia.","Vescia gigante, al taglio e da giovane, uniformemente bianco neve e molle come ovatta; scleroderma, al taglio già da giovane, marezzato scuro/grigiastro.","Lo scleroderma ha un guscio duro, spesso e tenace; la vescia gigante un involucro sottile, molle e simile a cuoio.","Lo scleroderma odora di metallico-sgradevole; la giovane vescia gigante odora delicatamente di fungo."}',false),
('chlorophyllum_rhacodes','lepiota_brunneoincarnata','en','The flesh that reddens saffron/orange when cut is typical of the edible shaggy parasol and is absent in the small toxic dapperling, which is flesh-pink-brown.','Shaggy parasol with a mild mushroomy smell; toxic dapperling with a sweetish-fruity smell — smell is not a reliable criterion.','Shaggy parasol in nutrient-rich spots, compost, conifer forest, gardens; toxic dapperling in sandy-grassy, park-like places — overlap possible.','Both with whitish spore print — not a distinguishing feature, therefore check the size, the saffron reaction of the flesh and the ring.','Only harvest the (shaggy) parasol if the cap is large (over 8 cm) AND the flesh reddens saffron-orange on rubbing/cutting — always leave small parasols under 8 cm standing.','{"The shaggy parasol is large: cap 8-20 cm; the flesh-pink dapperling is small: only 2-5 cm.","Shaggy parasol: the flesh turns saffron/orange-red when cut/rubbed; the toxic dapperling does not turn saffron-red.","Shaggy parasol: thick movable ring, smooth stem (NOT snake-patterned); toxic dapperling: only a fleeting fibrous ring zone, flesh-brown scaly stem.","The flesh-pink dapperling contains deadly amatoxins; the shaggy parasol is edible (can, raw/insufficiently cooked, cause gastrointestinal upset)."}',false),
('chlorophyllum_rhacodes','lepiota_brunneoincarnata','es','La carne que enrojece azafrán/naranja al corte es típica de la apagador rojizo/galamperna rojiza comestible y falta en la pequeña lepiota tóxica, de color pardo-rosa carne.','Galamperna rojiza con olor suave a champiñón; lepiota tóxica con olor dulzón-afrutado — el olor no es un criterio seguro.','Galamperna rojiza en lugares ricos en nutrientes, compost, bosque de coníferas, jardines; lepiota tóxica en lugares arenoso-herbosos, tipo parque — solapamiento posible.','Ambas con esporada blanquecina — no es un criterio distintivo, por ello verificar el tamaño, la reacción azafrán de la carne y el anillo.','Recolectar la galamperna (rojiza) solo si el sombrero es grande (más de 8 cm) Y si la carne enrojece azafrán-naranja al frotar/cortar — dejar siempre en el sitio las pequeñas lepiotas de menos de 8 cm.','{"La galamperna rojiza es grande: sombrero 8-20 cm; la lepiota pardo-rosada es pequeña: solo 2-5 cm.","Galamperna rojiza: la carne vira a azafrán/naranja-rojo al cortar/frotar; la lepiota tóxica no vira a azafrán-rojo.","Galamperna rojiza: anillo grueso desplazable, pie liso (NO jaspeado); lepiota tóxica: solo una fugaz zona anular fibrosa, pie con escamas pardo carne.","La lepiota pardo-rosada contiene amatoxinas mortales; la galamperna rojiza es comestible (puede, cruda/insuficientemente cocida, causar molestias gastrointestinales)."}',false),
('chlorophyllum_rhacodes','lepiota_brunneoincarnata','fr','La chair qui rougit safran/orange à la coupe est typique de la lépiote déguenillée comestible et fait défaut à la petite lépiote toxique, brun-rose chair.','Lépiote déguenillée à odeur douce de champignon ; lépiote toxique à odeur douceâtre-fruitée — l''odeur n''est pas un critère sûr.','Lépiote déguenillée dans les endroits riches en nutriments, composts, forêt de conifères, jardins ; lépiote toxique dans les endroits sablonneux-herbeux, de type parc — chevauchement possible.','Les deux à sporée blanchâtre — pas un critère de distinction, c''est pourquoi il faut vérifier la taille, la réaction safran de la chair et l''anneau.','Ne récolter la lépiote (déguenillée) que si le chapeau est grand (plus de 8 cm) ET si la chair rougit safran-orange au frottement/à la coupe — laisser systématiquement sur place les petites lépiotes de moins de 8 cm.','{"La lépiote déguenillée est grande : chapeau 8-20 cm ; la lépiote brun-incarnat est petite : seulement 2-5 cm.","Lépiote déguenillée : la chair vire au safran/orange à la coupe/au frottement ; la lépiote toxique ne vire pas au safran.","Lépiote déguenillée : anneau épais coulissant, pied lisse (NON chiné) ; lépiote toxique : seulement une zone annulaire fibreuse fugace, pied à squames brun chair.","La lépiote brun-incarnat contient des amatoxines mortelles ; la lépiote déguenillée est comestible (peut, crue/insuffisamment cuite, provoquer des troubles gastro-intestinaux)."}',false),
('chlorophyllum_rhacodes','lepiota_brunneoincarnata','it','La carne che arrossa zafferano/arancio al taglio è tipica della mazza di tamburo rossastra commestibile e manca alla piccola lepiota tossica, bruno-rosa carne.','Mazza di tamburo rossastra dall''odore mite di fungo; lepiota tossica dall''odore dolciastro-fruttato — l''odore non è un criterio sicuro.','Mazza di tamburo rossastra in luoghi ricchi di nutrienti, compost, bosco di conifere, giardini; lepiota tossica in luoghi sabbioso-erbosi, tipo parco — sovrapposizione possibile.','Entrambe con sporata biancastra — non è un criterio distintivo, perciò verificare la dimensione, la reazione zafferano della carne e l''anello.','Raccogliere la mazza di tamburo (rossastra) solo se il cappello è grande (oltre 8 cm) E se la carne arrossa zafferano-arancio allo sfregamento/al taglio — lasciare sempre sul posto le piccole lepiote sotto gli 8 cm.','{"La mazza di tamburo rossastra è grande: cappello 8-20 cm; la lepiota bruno-incarnata è piccola: solo 2-5 cm.","Mazza di tamburo rossastra: la carne vira allo zafferano/arancio al taglio/sfregamento; la lepiota tossica non vira allo zafferano.","Mazza di tamburo rossastra: anello spesso scorrevole, gambo liscio (NON zigrinato); lepiota tossica: solo una fugace zona anulare fibrosa, gambo con squame bruno carne.","La lepiota bruno-incarnata contiene amatossine mortali; la mazza di tamburo rossastra è commestibile (può, cruda/cotta insufficientemente, causare disturbi gastrointestinali)."}',false),
('clitopilus_prunulus','clitocybe_phyllophila','en','Both small and white; the funnel cap (clitocybe) looks glassy/varnished and frosted, the miller dull and chamois-like — but only the spore print distinguishes them reliably (pink vs white).','Miller = clear flour/cucumber smell; lead-white funnel cap = musty-sweetish/perfumed smell. The flour smell is the main confirmatory feature — but on its own not conclusive.','Both in hardwood/conifer forest; the lead-white funnel cap often in troops in leaf/needle litter, at path edges and in gardens.','Miller pink, lead-white funnel cap white/cream — the spore print is the most reliable distinguishing feature. When uncertain, ALWAYS make a spore print.','Only eat the miller if the flour smell is clear AND the spore print is pink — any white funnel cap with white spores, a perfumed/musty smell is muscarine-suspect and stays put.','{"The miller smells strongly and clearly of fresh flour/cucumber; the lead-white funnel cap smells musty-sweetish to perfumed — the smell is an important confirmatory feature.","The miller''s spore print is pink (gills flushing pinkish-red with age); in the lead-white funnel cap it is white to cream — the spore print is the MOST RELIABLE distinguishing feature.","The miller''s gills are distinctly decurrent and easily detachable; in the lead-white funnel cap they are only weakly/faintly decurrent.","The lead-white funnel cap is listed as muscarine-suspect/toxic (sweating/salivation/lacrimation syndrome; toxin content disputed in the literature, therefore conservatively treated as toxic) — the miller is safely edible.","The cap of the lead-white funnel cap is glassy-varnished white and frosted; the miller is dull grey-white, often somewhat distorted."}',false),
('clitopilus_prunulus','clitocybe_phyllophila','es','Ambos pequeños y blancos; el clitocibe parece vidrioso/como barnizado y pruinoso, el harinero mate y agamuzado — pero solo la esporada los distingue con seguridad (rosa vs blanca).','Harinero = claro olor a harina/pepino; clitocibe blanco plomizo = olor a moho-dulzón/perfumado. El olor a harina es el principal criterio de confirmación — pero por sí solo no concluyente.','Ambos en bosque de frondosas/coníferas; el clitocibe blanco plomizo a menudo en grupos en la hojarasca de hojas/acículas, en los bordes de los caminos y en los jardines.','Harinero rosa, clitocibe blanco plomizo blanca/crema — la esporada es el criterio distintivo más seguro. En caso de incertidumbre, hacer SIEMPRE una esporada.','Consumir el harinero solo si el olor a harina es claro Y la esporada rosa — todo clitocibe blanco de esporas blancas, con olor perfumado/a moho es sospechoso de muscarina y se queda en el sitio.','{"El harinero huele fuerte y claramente a harina fresca/pepino; el clitocibe blanco plomizo huele a moho-dulzón hasta perfumado — el olor es un criterio de confirmación importante.","La esporada del harinero es rosa (láminas que con la edad viran a rosa-rojizo); en el clitocibe blanco plomizo es blanca o crema — la esporada es el criterio distintivo MÁS SEGURO.","Las láminas del harinero son claramente decurrentes y se desprenden con facilidad; en el clitocibe blanco plomizo solo son débil/discretamente decurrentes.","El clitocibe blanco plomizo figura como sospechoso de muscarina/tóxico (síndrome sudoriano: sudoración/salivación/lagrimeo; contenido de toxina discutido en la literatura, por ello tratado con prudencia como tóxico) — el harinero es comestible sin peligro.","El sombrero del clitocibe blanco plomizo es blanco vidrioso-barnizado y pruinoso; el harinero es gris-blanco mate, a menudo algo deformado."}',false),
('clitopilus_prunulus','clitocybe_phyllophila','fr','Les deux petits et blancs ; le clitocybe paraît vitreux/comme verni et pruineux, le meunier mat et chamoisé — mais seule la sporée distingue avec certitude (rose vs blanc).','Meunier = nette odeur de farine/concombre ; clitocybe blanc de plomb = odeur de moisi-douceâtre/parfumée. L''odeur de farine est le principal critère de confirmation — mais à elle seule non probante.','Les deux en forêt de feuillus/conifères ; le clitocybe blanc de plomb souvent en troupes dans la litière de feuilles/aiguilles, en bordure de chemins et dans les jardins.','Meunier rose, clitocybe blanc de plomb blanc/crème — la sporée est le critère de distinction le plus sûr. En cas d''incertitude, TOUJOURS faire une sporée.','Ne consommer le meunier que si l''odeur de farine est nette ET la sporée rose — tout clitocybe blanc à spores blanches, à odeur parfumée/de moisi est suspect de muscarine et reste sur place.','{"Le meunier sent fortement et nettement la farine fraîche/le concombre ; le clitocybe blanc de plomb sent le moisi-douceâtre à parfumé — l''odeur est un critère de confirmation important.","La sporée du meunier est rose (lames devenant rose-rougeâtre avec l''âge) ; chez le clitocybe blanc de plomb elle est blanche à crème — la sporée est le critère de distinction le PLUS SÛR.","Les lames du meunier sont nettement décurrentes et se détachent facilement ; chez le clitocybe blanc de plomb elles ne sont que faiblement/discrètement décurrentes.","Le clitocybe blanc de plomb est considéré comme suspect de muscarine/toxique (syndrome sudorien : sudation/salivation/larmoiement ; teneur en toxine débattue dans la littérature, donc traité par prudence comme toxique) — le meunier est comestible sans danger.","Le chapeau du clitocybe blanc de plomb est blanc vitreux et pruineux comme verni ; le meunier est gris-blanc mat, souvent un peu déformé."}',false),
('clitopilus_prunulus','clitocybe_phyllophila','it','Entrambi piccoli e bianchi; il clitocybe appare vitreo/come verniciato e pruinoso, il fungo di farina opaco e camosciato — ma solo la sporata distingue con certezza (rosa vs bianca).','Fungo di farina = netto odore di farina/cetriolo; clitocybe bianco-plumbeo = odore di muffa-dolciastro/profumato. L''odore di farina è il principale criterio di conferma — ma da solo non probante.','Entrambi in bosco di latifoglie/conifere; il clitocybe bianco-plumbeo spesso a gruppi nella lettiera di foglie/aghi, ai bordi dei sentieri e nei giardini.','Fungo di farina rosa, clitocybe bianco-plumbeo bianca/crema — la sporata è il criterio distintivo più sicuro. In caso di incertezza fare SEMPRE la sporata.','Consumare il fungo di farina solo se l''odore di farina è netto E la sporata rosa — ogni clitocybe bianco a spore bianche, dall''odore profumato/di muffa è sospetto di muscarina e va lasciato sul posto.','{"Il fungo di farina odora fortemente e nettamente di farina fresca/cetriolo; il clitocybe bianco-plumbeo odora di muffa-dolciastro fino a profumato — l''odore è un criterio di conferma importante.","La sporata del fungo di farina è rosa (lamelle che con l''età virano al rosa-rossastro); nel clitocybe bianco-plumbeo è bianca o crema — la sporata è il criterio distintivo PIÙ SICURO.","Le lamelle del fungo di farina sono nettamente decorrenti e si staccano facilmente; nel clitocybe bianco-plumbeo sono solo debolmente/discretamente decorrenti.","Il clitocybe bianco-plumbeo è classificato come sospetto di muscarina/tossico (sindrome sudorina: sudorazione/salivazione/lacrimazione; contenuto di tossina dibattuto in letteratura, perciò trattato per prudenza come tossico) — il fungo di farina è commestibile senza pericolo.","Il cappello del clitocybe bianco-plumbeo è bianco vitreo e pruinoso come verniciato; il fungo di farina è grigio-bianco opaco, spesso un po'' deformato."}',false),
('clitopilus_prunulus','hebeloma_crustuliniforme','en','The miller (sweetbread mushroom): white-grey, decurrent gills; Hebeloma: clay-grey pale, emarginate, weeping gills.','The miller strongly mealy; weeping Hebeloma radish-like.',NULL,'The miller with pink spore print vs. rust/brown-olive in the weeping Hebeloma — decisive feature.','Spore-print colour secures the identification: pink + decurrent gills + mealy smell = the miller, rust-brown + radish smell + weeping gills = toxic mushroom.','{"The miller has gills clearly decurrent down the stem and a PINK spore print; the weeping Hebeloma has emarginate-attached gills and a rust/brown-olive spore print","The miller smells intensely mealy (especially at the gills); Hebeloma crustuliniforme smells radish-like","Weeping gills with droplets and brown spotting are typical of the Hebeloma and absent in the miller","The miller''s cap is white-grey, often somewhat irregular/distorted; the Hebeloma''s cap is clay-grey pale with a darker centre"}',false),
('clitopilus_prunulus','hebeloma_crustuliniforme','es','Molinera (clitopilo): blanco-gris, láminas decurrentes; hebeloma: gris-arcilla pálido, láminas escotadas, lacrimosas.','Molinera fuertemente harinosa; hebeloma lacrimoso con olor a rábano.',NULL,'Molinera con esporada rosa frente a herrumbre/pardo-oliva en el hebeloma lacrimoso — carácter decisivo.','El color de la esporada asegura la determinación: rosa + láminas decurrentes + olor harinoso = molinera, herrumbre-pardo + olor a rábano + láminas lacrimosas = hongo tóxico.','{"La molinera tiene láminas claramente decurrentes a lo largo del pie y una esporada ROSA; el hebeloma lacrimoso tiene láminas escotado-adheridas y una esporada herrumbre/pardo-oliva","La molinera huele intensamente a harina (sobre todo en las láminas); Hebeloma crustuliniforme huele a rábano","Las láminas lacrimosas con gotitas y manchas pardas son típicas del hebeloma y faltan en la molinera","El sombrero de la molinera es blanco-gris, a menudo algo irregular/deformado; el sombrero del hebeloma es gris-arcilla pálido con centro más oscuro"}',false),
('clitopilus_prunulus','hebeloma_crustuliniforme','fr','Meunier (clitopile petite-prune) : blanc-gris, lamelles décurrentes ; hébélome : gris-argile pâle, lamelles échancrées, larmoyantes.','Meunier fortement farineux ; hébélome larmoyant à odeur de raifort.',NULL,'Meunier à sporée rose contre rouille/brun-olive chez l''hébélome larmoyant — caractère décisif.','La couleur de la sporée assure la détermination : rose + lamelles décurrentes + odeur de farine = meunier, rouille-brun + odeur de raifort + lamelles larmoyantes = champignon toxique.','{"Le meunier a des lamelles nettement décurrentes le long du pied et une sporée ROSE ; l''hébélome larmoyant a des lamelles échancrées-attachées et une sporée rouille/brun-olive","Le meunier sent intensément la farine (surtout aux lamelles) ; Hebeloma crustuliniforme sent le raifort","Des lamelles larmoyantes avec gouttelettes et taches brunes sont typiques de l''hébélome et font défaut chez le meunier","Chapeau du meunier blanc-gris, souvent un peu irrégulier/déformé ; chapeau de l''hébélome gris-argile pâle à centre plus foncé"}',false),
('clitopilus_prunulus','hebeloma_crustuliniforme','it','Fungo della farina (clitopilo): bianco-grigio, lamelle decorrenti; hebeloma: grigio-argilla pallido, lamelle smarginate, lacrimanti.','Fungo della farina fortemente farinoso; hebeloma lacrimoso dall''odore di rafano.',NULL,'Fungo della farina con sporata rosa contro ruggine/bruno-oliva nell''hebeloma lacrimoso — carattere decisivo.','Il colore della sporata garantisce la determinazione: rosa + lamelle decorrenti + odore di farina = fungo della farina, ruggine-bruno + odore di rafano + lamelle lacrimanti = fungo tossico.','{"Il fungo della farina ha lamelle nettamente decorrenti lungo il gambo e una sporata ROSA; l''hebeloma lacrimoso ha lamelle smarginato-attaccate e una sporata ruggine/bruno-oliva","Il fungo della farina odora intensamente di farina (specialmente alle lamelle); Hebeloma crustuliniforme odora di rafano","Lamelle lacrimanti con goccioline e macchie brune sono tipiche dell''hebeloma e mancano nel fungo della farina","Cappello del fungo della farina bianco-grigio, spesso un po'' irregolare/deformato; cappello dell''hebeloma grigio-argilla pallido con centro più scuro"}',false),
('eierschwamm','omphalotus_olearius','en','The jack-o''-lantern is a strong orange with true thin, crowded gills and a funnel-shaped depressed cap, in clusters on wood; the chanterelle is pale yellow with thick, forked, decurrent ridges, single on the ground.','The chanterelle smells pleasantly fruity of apricot; the jack-o''-lantern smells inconspicuous to slightly unpleasant, without an apricot note.','Jack-o''-lantern in clusters on hardwood/stumps/roots (heat-loving, rare in Switzerland and only in mild locations); chanterelle single out of the ground in conifer and hardwood forest, frequent in Switzerland.','Both whitish to pale cream — the spore print does NOT separate them. Decisive are true gills vs thick ridges and the growth form (wood vs ground).','True, sharp-edged gills + clustered growth directly on wood = NEVER a chanterelle, no matter how yellow. A chanterelle has only thick, forked, decurrent ridges and stands single out of the ground.','{"The jack-o''-lantern has true, sharp-edged, crowded gills; the chanterelle has NO true gills, but only blunt, forked, thick ridges (thickened veined folds) that run far down the stem.","The jack-o''-lantern grows in clusters directly on/against wood and roots (oak, olive, sweet chestnut, stumps); the true chanterelle grows single to scattered out of the forest floor (mycorrhiza), never in clusters on wood.","Colour of the jack-o''-lantern strong orange to orange-red/brown-orange; chanterelle pale egg-yellow to yolk-yellow, uniform.","The gills of the fresh jack-o''-lantern glow faintly green in the dark (bioluminescence) — the chanterelle never.","Chanterelle flesh is fibrous-tough, pale yellow throughout and tears in fibres; jack-o''-lantern flesh is softer, orange-brown towards the base."}',false),
('eierschwamm','omphalotus_olearius','es','El clitocibe luminiscente/seta del olivo es de un naranja intenso con verdaderas láminas finas, apretadas, y sombrero deprimido en embudo, en grupos sobre madera; el rebozuelo/cantarela es amarillo pálido con pliegues gruesos, bifurcados, decurrentes, aislado en el suelo.','El rebozuelo huele agradablemente afrutado a albaricoque; la seta del olivo huele discreta o ligeramente desagradable, sin nota de albaricoque.','Seta del olivo en grupos sobre madera de frondosas/tocones/raíces (termófila, en Suiza rara y solo en estaciones cálidas); rebozuelo aislado saliendo del suelo en bosque de coníferas y frondosas, frecuente en Suiza.','Ambos blanquecinos a crema pálido — la esporada NO los distingue. Decisivos son las verdaderas láminas vs los pliegues gruesos y la forma de crecimiento (madera vs suelo).','Verdaderas láminas de arista cortante + crecimiento en grupos directamente sobre madera = NUNCA un rebozuelo, por amarillo que sea. Un rebozuelo solo tiene pliegues gruesos, bifurcados, decurrentes y crece aislado fuera del suelo.','{"La seta del olivo tiene verdaderas láminas de arista cortante, apretadas; el rebozuelo NO tiene verdaderas láminas, sino solo pliegues romos, bifurcados, gruesos (repliegues venosos engrosados) que descienden mucho por el pie.","La seta del olivo crece en grupos directamente sobre/contra la madera y las raíces (roble, olivo, castaño, tocones); el verdadero rebozuelo crece aislado o disperso saliendo del suelo del bosque (micorriza), nunca en grupos sobre madera.","Color de la seta del olivo naranja intenso a naranja-rojo/pardo-anaranjado; rebozuelo amarillo pálido a amarillo yema, uniforme.","Las láminas de la seta del olivo fresca brillan débilmente de verde en la oscuridad (bioluminiscencia) — el rebozuelo nunca.","La carne del rebozuelo es fibrosa-tenaz, amarillo pálido en todo su espesor y se rasga en fibras; la carne de la seta del olivo es más blanda, naranja-parda hacia la base."}',false),
('eierschwamm','omphalotus_olearius','fr','Le clitocybe de l''olivier est d''un orange vif avec de vraies lames fines, serrées, et un chapeau creusé en entonnoir, en touffes sur bois ; la girolle est jaune pâle avec des plis épais, fourchus, décurrents, isolée au sol.','La girolle a une agréable odeur fruitée d''abricot ; le clitocybe de l''olivier a une odeur discrète à légèrement désagréable, sans note d''abricot.','Clitocybe de l''olivier en touffes sur bois de feuillus/souches/racines (thermophile, rare en Suisse et seulement en stations douces) ; girolle isolée sortant du sol en forêt de conifères et de feuillus, fréquente en Suisse.','Les deux blanchâtres à crème pâle — la sporée ne les distingue PAS. Décisifs sont les vraies lames vs les plis épais et le mode de croissance (bois vs sol).','De vraies lames à arête tranchante + croissance en touffes directement sur bois = JAMAIS une girolle, aussi jaune soit-elle. Une girolle n''a que des plis épais, fourchus, décurrents et pousse isolée hors du sol.','{"Le clitocybe de l''olivier a de vraies lames à arête tranchante, serrées ; la girolle n''a PAS de vraies lames, mais seulement des plis épais, fourchus, émoussés (replis veineux épaissis) qui descendent loin sur le pied.","Le clitocybe de l''olivier pousse en touffes directement sur/contre le bois et les racines (chêne, olivier, châtaignier, souches) ; la vraie girolle pousse isolée à dispersée hors du sol forestier (mycorhize), jamais en touffes sur bois.","Couleur du clitocybe de l''olivier orange vif à orange-rouge/brun-orangé ; girolle jaune pâle à jaune d''œuf, uniforme.","Les lames du clitocybe de l''olivier frais luisent faiblement vert dans l''obscurité (bioluminescence) — jamais la girolle.","La chair de la girolle est fibreuse-tenace, jaune pâle de part en part et se déchire en fibres ; la chair du clitocybe de l''olivier est plus molle, orange-brun vers la base."}',false),
('eierschwamm','omphalotus_olearius','it','L''omfaloto dell''olivo è di un arancione vivo con vere lamelle sottili, fitte, e cappello depresso a imbuto, a ciuffi su legno; il finferlo/gallinaccio è giallo pallido con pliche spesse, forcate, decorrenti, isolato al suolo.','Il finferlo ha un gradevole odore fruttato di albicocca; l''omfaloto dell''olivo ha odore poco appariscente o leggermente sgradevole, senza nota di albicocca.','Omfaloto dell''olivo a ciuffi su legno di latifoglie/ceppaie/radici (termofilo, in Svizzera raro e solo in stazioni miti); finferlo isolato dal suolo in bosco di conifere e latifoglie, frequente in Svizzera.','Entrambi biancastri a crema pallido — la sporata NON li distingue. Decisivi sono le vere lamelle vs le pliche spesse e la forma di crescita (legno vs suolo).','Vere lamelle a spigolo tagliente + crescita a ciuffi direttamente su legno = MAI un finferlo, per quanto giallo. Un finferlo ha solo pliche spesse, forcate, decorrenti e cresce isolato dal suolo.','{"L''omfaloto dell''olivo ha vere lamelle a spigolo tagliente, fitte; il finferlo NON ha vere lamelle, ma solo pliche ottuse, forcate, spesse (pieghe venose ispessite) che scendono molto sul gambo.","L''omfaloto dell''olivo cresce a ciuffi direttamente su/contro il legno e le radici (quercia, olivo, castagno, ceppaie); il vero finferlo cresce isolato o sparso dal suolo del bosco (micorriza), mai a ciuffi su legno.","Colore dell''omfaloto dell''olivo arancione vivo fino a arancio-rosso/bruno-arancio; finferlo giallo pallido a giallo tuorlo, uniforme.","Le lamelle dell''omfaloto dell''olivo fresco brillano debolmente di verde al buio (bioluminescenza) — il finferlo mai.","La carne del finferlo è fibrosa-tenace, gialla pallida in tutto lo spessore e si lacera in fibre; la carne dell''omfaloto dell''olivo è più molle, arancio-bruna verso la base."}',false),
('flockenstieliger_hexenpilz','rubroboletus_satanas','en','Stem with red flecks (NO network) and immediate intense blackish-blue bluing in the dotted-stem bolete (scarletina bolete) versus a red stem network and weak bluing in the Devil''s bolete.','The Devil''s bolete smells of carrion when old, the scarletina bolete smells pleasantly mushroomy.','The scarletina bolete also grows in acidic conifer forests; the Devil''s bolete is strictly confined to warm calcareous hardwood forest.','Both olive-brown — not distinguishing.','A flecked stem without a network argues for the edible scarletina bolete; a red network on the stem is a warning signal towards the Devil''s bolete — when in doubt, discard, and thorough cooking is mandatory.','{"The scarletina bolete has NO stem network, but red flecks/dots on a yellow stem; the Devil''s bolete has a distinct red stem network — this is the most important distinguishing feature.","The scarletina bolete blues immediately and intensely to blackish-blue; the Devil''s bolete only weakly.","The scarletina bolete has a brown to dark-brown-brick-red cap; the Devil''s bolete when young has a pale, chalk-white-grey-green cap.","The Devil''s bolete smells of carrion when old; the scarletina bolete smells pleasantly mushroomy.","Both have red pores — the scarletina bolete is edible only when thoroughly cooked (raw toxic), the Devil''s bolete stays toxic."}',false),
('flockenstieliger_hexenpilz','rubroboletus_satanas','es','Pie con flóculos rojos (SIN retículo) y azulamiento inmediato e intenso a negro-azul en el boleto de pie punteado (Neoboletus erythropus) frente a retículo rojo en el pie y azulamiento débil en el boleto de Satanás.','El boleto de Satanás huele a carroña al envejecer, el boleto de pie punteado huele agradablemente a champiñón.','El boleto de pie punteado crece también en bosques ácidos de coníferas; el boleto de Satanás está estrictamente limitado a bosques cálidos de frondosas sobre suelo calcáreo.','Ambos pardo oliva — no distintivo.','Un pie floculoso sin retículo aboga por el boleto de pie punteado comestible; un retículo rojo en el pie es una señal de alarma hacia el boleto de Satanás — en caso de duda, descartar, y la cocción completa es obligatoria.','{"El boleto de pie punteado NO tiene retículo en el pie, sino flóculos/puntos rojos sobre pie amarillo; el boleto de Satanás tiene un nítido retículo rojo en el pie — este es el criterio distintivo más importante.","El boleto de pie punteado azulea de inmediato e intensamente a negro-azul; el boleto de Satanás solo débilmente.","El boleto de pie punteado tiene sombrero pardo a pardo oscuro-rojo ladrillo; el boleto de Satanás de joven tiene sombrero claro, blanco cal-gris-verde.","El boleto de Satanás huele a carroña al envejecer; el boleto de pie punteado huele agradablemente a champiñón.","Ambos tienen poros rojos — el boleto de pie punteado solo es comestible bien cocido (crudo tóxico), el boleto de Satanás permanece tóxico."}',false),
('flockenstieliger_hexenpilz','rubroboletus_satanas','fr','Pied à flocons rouges (PAS de réseau) et bleuissement immédiat et intense en noir-bleu chez le bolet à pied rouge (bolet Satan comestible) contre réseau rouge sur le pied et bleuissement faible chez le bolet Satan.','Le bolet Satan sent la charogne en vieillissant, le bolet à pied rouge sent agréablement le champignon.','Le bolet à pied rouge pousse aussi dans les forêts de conifères acides ; le bolet Satan est strictement limité aux forêts de feuillus calcaires et chaudes.','Les deux brun olive — non distinctif.','Un pied floconneux sans réseau plaide pour le bolet à pied rouge comestible ; un réseau rouge sur le pied est un signal d''alarme vers le bolet Satan — en cas de doute, rejeter, et une cuisson complète est obligatoire.','{"Le bolet à pied rouge n''a PAS de réseau sur le pied, mais des flocons/points rouges sur un pied jaune ; le bolet Satan a un net réseau rouge sur le pied — c''est le critère de distinction le plus important.","Le bolet à pied rouge bleuit immédiatement et intensément en noir-bleu ; le bolet Satan seulement faiblement.","Le bolet à pied rouge a un chapeau brun à brun foncé-rouge brique ; le bolet Satan a jeune un chapeau clair, blanc calcaire-gris-vert.","Le bolet Satan sent la charogne en vieillissant ; le bolet à pied rouge sent agréablement le champignon.","Les deux ont des pores rouges — le bolet à pied rouge n''est comestible que bien cuit (cru toxique), le bolet Satan reste toxique."}',false),
('flockenstieliger_hexenpilz','rubroboletus_satanas','it','Gambo con fioccosità rosse (NESSUN reticolo) e immediato e intenso viraggio al nero-blu nel boleto dal piede rosso (Neoboletus erythropus) contro reticolo rosso sul gambo e viraggio debole nel boleto di Satana.','Il boleto di Satana da vecchio odora di carogna, il boleto dal piede rosso odora gradevolmente di fungo.','Il boleto dal piede rosso cresce anche nei boschi acidi di conifere; il boleto di Satana è strettamente limitato ai boschi caldi di latifoglie su suolo calcareo.','Entrambi bruno oliva — non distintivo.','Un gambo fioccoso senza reticolo depone per il boleto dal piede rosso commestibile; un reticolo rosso sul gambo è un segnale d''allarme verso il boleto di Satana — in caso di dubbio scartare, e la cottura completa è obbligatoria.','{"Il boleto dal piede rosso NON ha reticolo sul gambo, ma fiocchi/punti rossi su gambo giallo; il boleto di Satana ha un netto reticolo rosso sul gambo — questo è il criterio distintivo più importante.","Il boleto dal piede rosso vira subito e intensamente al nero-blu; il boleto di Satana solo debolmente.","Il boleto dal piede rosso ha cappello bruno fino a bruno scuro-rosso mattone; il boleto di Satana da giovane ha cappello chiaro, bianco calce-grigio-verde.","Il boleto di Satana da vecchio odora di carogna; il boleto dal piede rosso odora gradevolmente di fungo.","Entrambi hanno pori rossi — il boleto dal piede rosso è commestibile solo ben cotto (crudo tossico), il boleto di Satana resta tossico."}',false),
('hallimasch','hypholoma_fasciculare','en','The sulphur-yellow-greenish gill tone of the sulphur tuft clearly distinguishes it from the pale flesh-coloured-gilled honey fungus with its finely scaly cap and a true whitish ring.','Only the taste test separates the sulphur tuft: honey fungus mild, sulphur tuft intensely bitter (only chew a sample, never swallow).','Both in clusters on wood/stumps; habitat does not separate them, so gill colour, ring and spore print colour must be checked.','Honey fungus: WHITE spore print; sulphur tuft (green-gilled): dark violet-/purple-brown spore print — a clear, reliable distinguishing feature.','The honey fungus has a true whitish ring and a WHITE spore print — if the true ring is missing or the spore print is dark violet-brown and the taste bitter, it is the sulphur tuft. Always cook honey fungus thoroughly, discard the cooking water.','{"Honey fungus: gills whitish to pale flesh-brown, pale rust-brown with age; sulphur tuft: gills sulphur-yellow-greenish to greenish-black.","Honey fungus: distinct whitish, flocculose-cottony ring on the stem; sulphur tuft: only a fleeting ring zone, no true ring.","Honey fungus: cap with fine dark, mostly wipe-off scales; sulphur tuft: cap smooth, sulphur- to ochre-yellow.","Honey fungus: toxic raw, but edible well-cooked and mild (discard the cooking water); sulphur tuft: bitter and toxic both raw and cooked."}',false),
('hallimasch','hypholoma_fasciculare','es','El tono de las láminas amarillo azufre-verdoso del hifoloma lo distingue claramente de la armilaria de láminas color carne claro, de sombrero finamente escamoso y con verdadero anillo blanquecino.','Solo la prueba de sabor separa al hifoloma: armilaria suave, hifoloma intensamente amargo (masticar solo una muestra, nunca tragar).','Ambos en grupos sobre madera/tocones; el hábitat no los separa, por ello hay que verificar obligatoriamente el color de las láminas, el anillo y el color de la esporada.','Armilaria: esporada BLANCA; hifoloma en grupos de láminas verdes: esporada pardo-violácea/púrpura oscura — criterio distintivo nítido y seguro.','La armilaria tiene un verdadero anillo blanquecino y esporada BLANCA — si falta el verdadero anillo o la esporada es pardo-violácea oscura y el sabor amargo, es el hifoloma. Cocer siempre bien la armilaria, desechar el agua de cocción.','{"Armilaria: láminas blanquecinas a pardo carne claro, pardo herrumbre claro con la edad; hifoloma: láminas amarillo azufre-verdoso a verde-negruzco.","Armilaria: anillo nítido, blanquecino, flocoso-algodonoso en el pie; hifoloma: solo una fugaz zona anular, ningún verdadero anillo.","Armilaria: sombrero con finas escamitas oscuras, en general eliminables al frotar; hifoloma: sombrero liso, amarillo azufre a amarillo ocre.","Armilaria: tóxica cruda, pero comestible bien cocida y suave (desechar el agua de cocción); hifoloma: amargo y tóxico tanto crudo como cocido."}',false),
('hallimasch','hypholoma_fasciculare','fr','La teinte des lames jaune soufre-verdâtre de l''hypholome le distingue clairement de l''armillaire couleur chair claire, à chapeau finement squameux et à véritable anneau blanchâtre.','Seul le test gustatif sépare l''hypholome : armillaire doux, hypholome intensément amer (n''en mâcher qu''un échantillon, ne jamais l''avaler).','Les deux en touffes sur bois/souches ; l''habitat ne les sépare pas, il faut donc impérativement vérifier la couleur des lames, l''anneau et la couleur de la sporée.','Armillaire : sporée BLANCHE ; hypholome en touffes à lames vertes : sporée brun violacé/pourpre foncé — critère de distinction net et sûr.','L''armillaire a un véritable anneau blanchâtre et une sporée BLANCHE — si le véritable anneau manque ou si la sporée est brun violacé foncé et le goût amer, c''est l''hypholome. Toujours bien cuire l''armillaire, jeter l''eau de cuisson.','{"Armillaire : lames blanchâtres à brun chair clair, brun rouille clair avec l''âge ; hypholome : lames jaune soufre-verdâtre à vert-noirâtre.","Armillaire : anneau net, blanchâtre, floconneux-cotonneux sur le pied ; hypholome : seulement une zone annulaire fugace, pas de véritable anneau.","Armillaire : chapeau à fines squamules sombres, généralement effaçables ; hypholome : chapeau lisse, jaune soufre à jaune ocre.","Armillaire : toxique cru, mais comestible bien cuit et doux (jeter l''eau de cuisson) ; hypholome : amer et toxique aussi bien cru que cuit."}',false),
('hallimasch','hypholoma_fasciculare','it','La tonalità delle lamelle giallo zolfo-verdastra del falso chiodino/ipoloma lo distingue chiaramente dal chiodino (armillaria) color carne chiaro, a cappello finemente squamoso e con vero anello biancastro.','Solo la prova del gusto separa l''ipoloma: armillaria mite, ipoloma intensamente amaro (masticare solo un assaggio, non inghiottire mai).','Entrambi a ciuffi su legno/ceppaie; l''habitat non li separa, perciò bisogna verificare obbligatoriamente il colore delle lamelle, l''anello e il colore della sporata.','Armillaria: sporata BIANCA; ipoloma a ciuffi con lamelle verdi: sporata bruno-violacea/porpora scura — criterio distintivo netto e sicuro.','L''armillaria ha un vero anello biancastro e sporata BIANCA — se manca il vero anello o se la sporata è bruno-violacea scura e il sapore amaro, è l''ipoloma. Cuocere sempre bene l''armillaria, gettare l''acqua di cottura.','{"Armillaria: lamelle biancastre a bruno carnicino chiaro, bruno ruggine chiaro con l''età; ipoloma: lamelle giallo zolfo-verdastre a verde-nerastro.","Armillaria: anello netto, biancastro, fioccoso-cotonoso sul gambo; ipoloma: solo una fugace zona anulare, nessun vero anello.","Armillaria: cappello con fini squamette scure, per lo più asportabili; ipoloma: cappello liscio, giallo zolfo a giallo ocra.","Armillaria: tossica cruda, ma commestibile ben cotta e mite (gettare l''acqua di cottura); ipoloma: amaro e tossico sia crudo sia cotto."}',false),
('hallimasch','pholiota_squarrosa','en','Coarse, spreading, shaggy scales on cap and stem in the shaggy scalycap (shaggy pholiota) instead of the fine, wipe-off, fleeting flecks of the honey fungus.','The shaggy scalycap smells obtrusively of radish/leek, the honey fungus mildly mushroomy.','Both in clusters on hardwood/conifer wood and stumps, same autumn season — the site does NOT serve to distinguish them.','Shaggy scalycap rust-brown spore print, honey fungus white — note the gill colour with age (make a spore print).','Spore print colour decides: rust-brown = never a honey fungus, hands off. Always examine cluster fungi on wood individually, never harvest wholesale as honey fungus. The honey fungus is moreover only edible when thoroughly cooked.','{"Shaggy scalycap: dry, spreading (shaggy), coarse brown scales on cap AND stem; the honey fungus has only fine, fleeting, appressed flecks on the cap.","Spore print: scalycap rust-brown → gills turning brown; honey fungus white → gills staying pale/cream-white.","The honey fungus has a thick, membranous, white ring; the scalycap''s ring is shaggy-fibrous/woolly and indistinct.","The shaggy scalycap smells obtrusively spicy-radish/leek, the honey fungus rather mushroomy-mild.","The scalycap''s taste is bitter/unpleasant (spit out the sample, never swallow raw)."}',false),
('hallimasch','pholiota_squarrosa','es','Escamas gruesas, erizadas y enmarañadas en el sombrero y el pie en la foliota escamosa, en lugar de los finos flóculos eliminables y fugaces de la armilaria.','La foliota escamosa huele de forma penetrante a rábano/puerro, la armilaria tiene un olor suave a champiñón.','Ambas en grupos sobre madera de frondosas/coníferas y tocones, misma estación otoñal — la estación NO sirve para distinguirlas.','Foliota escamosa esporada pardo herrumbre, armilaria esporada blanca — observar el color de las láminas con la edad (hacer una esporada).','El color de la esporada decide: pardo herrumbre = nunca una armilaria, no tocar. Examinar siempre individualmente los hongos en grupos sobre madera, nunca recolectar en bloque como armilaria. La armilaria además solo es comestible bien cocida.','{"Foliota escamosa: escamas pardas secas, erizadas (enmarañadas), gruesas en el sombrero Y el pie; la armilaria solo tiene finos flóculos fugaces, adheridos, en el sombrero.","Esporada: foliota pardo herrumbre → láminas que pardean; armilaria blanca → láminas que permanecen claras/blanco crema.","La armilaria tiene un anillo grueso, membranoso, blanco; el anillo de la foliota es erizado-fibroso/lanoso e indistinto.","La foliota escamosa huele de forma penetrante especiada-rábano/puerro, la armilaria más bien suave-champiñón.","El sabor de la foliota es amargo/desagradable (escupir la muestra, nunca tragar cruda)."}',false),
('hallimasch','pholiota_squarrosa','fr','Des écailles grossières, dressées et hérissées sur le chapeau et le pied chez la pholiote écailleuse, au lieu des fines flocons effaçables et fugaces de l''armillaire.','La pholiote écailleuse a une odeur envahissante de radis/poireau, l''armillaire une odeur douce de champignon.','Les deux en touffes sur bois de feuillus/conifères et souches, même saison d''automne — la station NE permet PAS de les distinguer.','Pholiote écailleuse sporée brun rouille, armillaire sporée blanche — observer la couleur des lames avec l''âge (faire une sporée).','La couleur de la sporée décide : brun rouille = jamais une armillaire, ne pas y toucher. Toujours examiner individuellement les champignons en touffes sur bois, ne jamais récolter en bloc comme armillaire. L''armillaire n''est en outre comestible que bien cuite.','{"Pholiote écailleuse : écailles brunes sèches, dressées (hérissées), grossières sur le chapeau ET le pied ; l''armillaire n''a que de fines flocons fugaces, appliqués, sur le chapeau.","Sporée : pholiote brun rouille → lames brunissant ; armillaire blanche → lames restant claires/blanc crème.","L''armillaire a un anneau épais, membraneux, blanc ; l''anneau de la pholiote est hérissé-fibreux/laineux et indistinct.","La pholiote écailleuse a une odeur envahissante épicée-radis/poireau, l''armillaire plutôt douce-champignon.","Goût de la pholiote amer/désagréable (recracher l''échantillon, ne jamais avaler cru)."}',false),
('hallimasch','pholiota_squarrosa','it','Squame grossolane, sporgenti e irte sul cappello e sul gambo nella foliota squarrosa, al posto dei fini fiocchi asportabili e fugaci dell''armillaria.','La foliota squarrosa odora in modo invadente di ravanello/porro, l''armillaria ha un mite odore di fungo.','Entrambe a ciuffi su legno di latifoglie/conifere e ceppaie, stessa stagione autunnale — la stazione NON serve a distinguerle.','Foliota squarrosa sporata bruno ruggine, armillaria sporata bianca — osservare il colore delle lamelle con l''età (fare la sporata).','Il colore della sporata decide: bruno ruggine = mai un''armillaria, non toccare. Esaminare sempre singolarmente i funghi a ciuffi su legno, non raccogliere mai in blocco come armillaria. L''armillaria inoltre è commestibile solo ben cotta.','{"Foliota squarrosa: squame brune secche, sporgenti (irte), grossolane sul cappello E sul gambo; l''armillaria ha solo fini fiocchi fugaci, aderenti, sul cappello.","Sporata: foliota bruno ruggine → lamelle che imbruniscono; armillaria bianca → lamelle che restano chiare/bianco crema.","L''armillaria ha un anello spesso, membranoso, bianco; l''anello della foliota è irto-fibroso/lanoso e indistinto.","La foliota squarrosa odora in modo invadente speziato-ravanello/porro, l''armillaria piuttosto mite-fungina.","Sapore della foliota amaro/sgradevole (sputare l''assaggio, non inghiottire mai crudo)."}',false),
('kuehneromyces_mutabilis','conocybe_filaris','en','The decisive feature is the stem below the ring: brown with spreading scales (sheathed woodtuft) versus smooth to silvery longitudinally fibrillose (conocybe). The cap colours are in both honey to cinnamon brown and do NOT separate them.','Sheathed woodtuft smells pleasantly mushroomy-aromatic; the conocybe is odourless to faintly mealy — smell is NOT a reliable distinguishing feature.','Sheathed woodtuft in clusters on rotting hardwood/conifer wood (stumps, deadwood); Conocybe filaris terrestrial on lawns, meadows, wood chips, compost and conifer needle litter on the ground — the growth site (wood vs ground) is an important clue, but on its own not conclusive.','Both rust-brown to cinnamon-brown — UNUSABLE as a distinguishing feature. Therefore the stem scaling below the ring must absolutely be checked.','Only collect sheathed woodtuft if the stem below the ring is clearly brown and scaly/snake-patterned AND the mushroom grows in clusters on wood. If the stem is smooth/silvery-fibrillose or it grows on the ground on lawn, discard immediately — life-threatening due to amatoxins. When in doubt, go to mushroom inspection (VAPKO).','{"Sheathed woodtuft: stem below the ring distinctly brown, with spreading scales/snake-patterned — conifer conocybe (Conocybe filaris/Pholiotina rugosa): stem smooth to silvery longitudinally fibrillose, without scales. The stem feature is the most important distinguishing factor.","The conocybe contains amatoxins (the same poison as the death cap) — even a few caps can trigger fatal liver failure, with a 6-24 h symptom-free latency before organ damage.","The conocybe usually grows terrestrially on lawns, meadows, wood chips, compost soil and conifer needle litter on the ground — sheathed woodtuft in clusters directly on rotting hardwood/conifer wood (stumps, fallen trunks).","Sheathed woodtuft typically grows in dense clusters on the same piece of wood; the conocybe usually stands singly to gregariously on the ground, not in clusters out of wood.","The cap of sheathed woodtuft typically dries out two-toned (hygrophanous watery margin); the conocybe cap is more uniformly ochre-cinnamon-brown and barely two-tone zoned."}',false),
('kuehneromyces_mutabilis','conocybe_filaris','es','El rasgo decisivo es el pie por debajo del anillo: pardo con escamas erizadas (seta de chopo/foliota cambiante) frente a liso o fibriloso-plateado longitudinalmente (conocybe). Los colores del sombrero son en ambos pardo miel a pardo canela y NO sirven para distinguirlos.','La foliota cambiante huele agradablemente a champiñón, aromática; el conocybe es inodoro o ligeramente harinoso — el olor NO es un carácter distintivo seguro.','Foliota cambiante en grupos densos sobre madera podrida de frondosas/coníferas (tocones, madera muerta); Conocybe filaris terrícola sobre césped, prados, astillas de madera, compost y hojarasca de acículas en el suelo — el lugar de crecimiento (madera vs suelo) es un indicio importante, pero por sí solo no concluyente.','Ambos pardo herrumbre a pardo canela — INUTILIZABLE como carácter distintivo. Por ello hay que verificar obligatoriamente las escamas del pie por debajo del anillo.','Recolectar la foliota cambiante SOLO si el pie por debajo del anillo es claramente pardo y escamoso/jaspeado Y si el hongo crece en grupos sobre madera. Si el pie es liso/fibriloso-plateado o crece en el suelo sobre césped, descartar de inmediato — peligro mortal por amatoxinas. En caso de duda, control de setas (VAPKO).','{"Foliota cambiante: pie por debajo del anillo claramente pardo, con escamas erizadas/jaspeado — conocybe de coníferas (Conocybe filaris/Pholiotina rugosa): pie liso o fibriloso-plateado longitudinalmente, sin escamas. El carácter del pie es el principal factor distintivo.","El conocybe contiene amatoxinas (el mismo veneno que la oronja verde/Amanita phalloides) — bastan unos pocos sombreros para provocar una insuficiencia hepática mortal, con una latencia sin síntomas de 6-24 h antes del daño orgánico.","El conocybe crece sobre todo de forma terrícola en césped, prados, astillas de madera, tierra de compost y hojarasca de acículas en el suelo — la foliota cambiante en grupos directamente sobre madera podrida de frondosas/coníferas (tocones, troncos caídos).","La foliota cambiante crece típicamente en grupos densos sobre la misma madera; el conocybe se presenta casi siempre aislado o gregario en el suelo, no en grupos saliendo de la madera.","El sombrero de la foliota cambiante seca típicamente en dos tonos (margen higrófano empapado de agua); el sombrero del conocybe es más uniformemente ocre pardo canela y apenas zonado en dos colores."}',false),
('kuehneromyces_mutabilis','conocybe_filaris','fr','Le critère décisif est le pied sous l''anneau : brun et couvert d''écailles dressées (pholiote changeante) contre lisse à fibrilleux argenté longitudinalement (conocybe). Les couleurs du chapeau sont chez les deux brun miel à brun cannelle et NE permettent PAS de les distinguer.','La pholiote changeante a une odeur agréable de champignon, aromatique ; le conocybe est inodore à légèrement farineux — l''odeur n''est PAS un critère de distinction sûr.','Pholiote changeante en touffes sur bois mort de feuillus/conifères (souches, bois mort) ; Conocybe filaris terrestre sur gazon, prairies, copeaux de bois, compost et litière d''aiguilles au sol — le lieu de croissance (bois vs sol) est un indice important, mais à lui seul non probant.','Les deux brun rouille à brun cannelle — INUTILISABLE comme critère de distinction. Il faut donc impérativement vérifier les écailles du pied sous l''anneau.','Ne récolter la pholiote changeante QUE si le pied sous l''anneau est nettement brun et écailleux/chiné ET si le champignon pousse en touffes sur du bois. En cas de pied lisse/fibrilleux argenté ou de pousse au sol sur gazon, rejeter immédiatement — danger mortel par amatoxines. En cas de doute, contrôle des champignons (VAPKO).','{"Pholiote changeante : pied sous l''anneau nettement brun, à écailles dressées/chiné — conocybe des conifères (Conocybe filaris/Pholiotina rugosa) : pied lisse à fibrilleux argenté longitudinalement, sans écailles. Le caractère du pied est le principal facteur de distinction.","Le conocybe contient des amatoxines (le même poison que l''amanite phalloïde) — quelques chapeaux suffisent à provoquer une insuffisance hépatique mortelle, avec une latence sans symptômes de 6 à 24 h avant l''atteinte des organes.","Le conocybe pousse le plus souvent de façon terrestre sur gazon, prairies, copeaux de bois, terre de compost et litière d''aiguilles au sol — la pholiote changeante en touffes directement sur bois mort de feuillus/conifères (souches, troncs couchés).","La pholiote changeante pousse typiquement en touffes denses sur le même bois ; le conocybe se tient le plus souvent isolé à grégaire au sol, non en touffes sortant du bois.","Le chapeau de la pholiote changeante sèche typiquement en deux teintes (marge hygrophane gorgée d''eau) ; le chapeau du conocybe est plus uniformément ocre brun cannelle et à peine zoné en deux couleurs."}',false),
('kuehneromyces_mutabilis','conocybe_filaris','it','Il criterio decisivo è il gambo sotto l''anello: bruno e squamoso-sporgente (foliota mutabile) contro liscio o fibrilloso-argenteo longitudinalmente (conocybe). I colori del cappello sono in entrambi dal bruno miele al bruno cannella e NON sono distintivi.','La foliota mutabile ha un odore gradevole, fungino-aromatico; il conocybe è inodore o leggermente farinoso — l''odore NON è un carattere distintivo sicuro.','Foliota mutabile a ciuffi su legno marcescente di latifoglie/conifere (ceppaie, legno morto); Conocybe filaris terricolo su prati, erba, cippato, compost e lettiera di aghi al suolo — il luogo di crescita (legno vs suolo) è un indizio importante, ma da solo non probante.','Entrambi bruno ruggine o bruno cannella — INUTILIZZABILE come carattere distintivo. È quindi indispensabile verificare la squamosità del gambo sotto l''anello.','Raccogliere la foliota mutabile SOLO se il gambo sotto l''anello è chiaramente bruno e squamoso/zigrinato E se il fungo cresce a ciuffi su legno. In caso di gambo liscio/fibrilloso-argenteo o di crescita al suolo su prato, scartare subito — pericolo di morte per amatossine. In caso di dubbio, controllo dei funghi (VAPKO).','{"Foliota mutabile: gambo sotto l''anello nettamente bruno, con squame sporgenti/zigrinato — conocybe delle conifere (Conocybe filaris/Pholiotina rugosa): gambo liscio o fibrilloso-argenteo longitudinalmente, senza squame. Il carattere del gambo è il principale fattore distintivo.","Il conocybe contiene amatossine (lo stesso veleno dell''amanita falloide) — pochi cappelli bastano a scatenare un''insufficienza epatica mortale, con una latenza priva di sintomi di 6-24 h prima del danno d''organo.","Il conocybe cresce per lo più terricolo su prati, erba, cippato, terriccio di compost e lettiera di aghi al suolo — la foliota mutabile a ciuffi direttamente su legno marcescente di latifoglie/conifere (ceppaie, tronchi a terra).","La foliota mutabile cresce tipicamente a ciuffi densi sullo stesso legno; il conocybe si presenta per lo più isolato o gregario al suolo, non a ciuffi dal legno.","Il cappello della foliota mutabile si asciuga tipicamente in due colori (margine igrofano imbevuto d''acqua); il cappello del conocybe è più uniformemente ocra bruno cannella e quasi privo di zonatura bicolore."}',false),
('kuehneromyces_mutabilis','hypholoma_fasciculare','en','The sulphur tuft''s gills carry a greenish sulphur-yellow tone that the brown-gilled sheathed woodtuft (Kuehneromyces mutabilis) lacks; the brown-scaly snakeskin-patterned stem below the membranous ring is the woodtuft''s most important feature.','The sheathed woodtuft smells pleasantly mushroomy; the sulphur tuft is intensely bitter. CAUTION: a taste test ONLY rules out the sulphur tuft — the deadly funeral bell (Galerina) is not bitter, so tasting does NOT protect against it.','Both grow in clusters on deadwood/stumps of hardwood and conifer, so the habitat is NOT suitable for distinction.','Sheathed woodtuft: brown spore print (cinnamon/rust-brown); sulphur tuft: dark violet/purple-brown spore print. Both are dark-spored — the spore print only separates them roughly, so checking the stem and gill colour is mandatory.','Never trust the bitter taste alone: that only protects against the sulphur tuft, NOT against the deadly, mild-tasting funeral bell. Harvest the sheathed woodtuft exclusively if EVERY fruiting body shows the membranous ring AND below it the brown-scaly snakeskin-patterned stem AND no green tinge is visible on the gills — when in doubt, leave it.','{"Sheathed woodtuft: mild, nutty taste; sulphur tuft: distinctly and persistently BITTER","Sheathed woodtuft gills pale when young, then cinnamon to rust-brown; sulphur tuft gills sulphur-yellow, then greenish to greenish-black","Sheathed woodtuft has a membranous ring + below it dark, projecting scales on the stem; sulphur tuft has at most a fleeting ring zone, stem bare yellow-rust-brown","Sheathed woodtuft stem below the ring brown-scaly, snakeskin-patterned; sulphur tuft stem sulphur-yellow above, rust-brown towards the base, smooth","MORE IMPORTANT than the sulphur tuft: the DEADLY funeral bell (Galerina marginata) likewise grows in clusters on deadwood, looks very similar to the sheathed woodtuft and is NOT bitter — only harvest the sheathed woodtuft if you reliably recognise every fruiting body by its brown-scaly stem"}',false),
('kuehneromyces_mutabilis','hypholoma_fasciculare','es','Las láminas del hifoloma de láminas verdes (Schwefelkopf) tienen un tono amarillo azufre verdoso que le falta a la seta de chopo de láminas pardas (Kuehneromyces mutabilis); el pie con escamas pardas en disposición de piel de serpiente bajo el anillo membranoso es el carácter más importante del Kuehneromyces.','El Kuehneromyces huele agradablemente a hongo; el hifoloma es intensamente amargo. ATENCIÓN: una cata SOLO descarta el hifoloma — la Galerina mortal no es amarga, así que catar NO protege contra ella.','Ambos crecen en grupos sobre madera muerta/tocones de frondosas y coníferas, por lo que el hábitat NO sirve para la distinción.','Kuehneromyces: esporada parda (canela/pardo herrumbre); hifoloma de láminas verdes: esporada pardo violácea/púrpura oscura. Ambos tienen esporada oscura — la esporada solo los separa de forma aproximada, por eso es obligatorio comprobar el pie y el color de las láminas.','Nunca fiarse solo del sabor amargo: eso protege únicamente del hifoloma, NO de la Galerina mortal de sabor suave. Recolectar el Kuehneromyces exclusivamente si CADA carpóforo muestra el anillo membranoso Y, debajo, el pie con escamas pardas en piel de serpiente Y ninguna tonalidad verde visible en las láminas — en caso de duda, dejarlo.','{"Kuehneromyces: sabor suave-a nuez; hifoloma de láminas verdes: clara y persistentemente AMARGO","Láminas del Kuehneromyces de jóvenes claras, luego canela a pardo herrumbre; láminas del hifoloma amarillo azufre, luego verdosas a verde negruzco","El Kuehneromyces tiene un anillo membranoso + debajo escamas oscuras salientes en el pie; el hifoloma tiene a lo sumo una zona anular fugaz, pie glabro amarillo-pardo herrumbre","Pie del Kuehneromyces bajo el anillo con escamas pardas en piel de serpiente; pie del hifoloma amarillo azufre arriba, pardo herrumbre hacia abajo, liso","MÁS IMPORTANTE que el hifoloma: la Galerina marginata MORTAL crece igualmente en grupos sobre madera muerta, se parece mucho al Kuehneromyces y NO es amarga — recolectar el Kuehneromyces solo si se reconoce con certeza cada carpóforo por su pie con escamas pardas"}',false),
('kuehneromyces_mutabilis','hypholoma_fasciculare','fr','Les lames de l''hypholome (Schwefelkopf) portent une teinte jaune soufre verdâtre qui manque à la pholiote ridée à lames brunes (Stockschwämmchen / Kuehneromyces) ; le pied chiné de squames brunes sous l''anneau membraneux est le caractère le plus important du Kuehneromyces.','Le Kuehneromyces sent agréablement le champignon ; l''hypholome est intensément amer. ATTENTION : une dégustation ne distingue QUE l''hypholome — la galère mortelle (Galerina) n''est pas amère, une dégustation ne protège donc PAS d''elle.','Tous deux poussent en touffes sur bois mort/souches de feuillus et de conifères, de sorte que l''habitat ne convient PAS à la distinction.','Kuehneromyces : sporée brune (cannelle/brun rouille) ; hypholome à lames vertes : sporée brun violacé/pourpre foncé. Tous deux ont une sporée sombre — la sporée ne les sépare que grossièrement, vérifier donc impérativement le pied et la couleur des lames.','Ne jamais se fier uniquement au goût amer : cela protège seulement de l''hypholome, PAS de la galère mortelle au goût doux. Ne récolter le Kuehneromyces que si CHAQUE carpophore montre l''anneau membraneux ET, en dessous, le pied chiné de squames brunes ET aucune teinte verte visible sur les lames — dans le doute, laisser sur place.','{"Kuehneromyces : goût doux-noisette ; hypholome à lames vertes : nettement et durablement AMER","Lames du Kuehneromyces jeunes claires, puis cannelle à brun rouille ; lames de l''hypholome jaune soufre, puis verdâtres à vert noirâtre","Le Kuehneromyces a un anneau membraneux + en dessous des squames sombres dressées sur le pied ; l''hypholome a tout au plus une zone annulaire fugace, pied glabre jaune-brun rouille","Pied du Kuehneromyces sous l''anneau chiné de squames brunes ; pied de l''hypholome jaune soufre en haut, brun rouille vers le bas, lisse","PLUS IMPORTANT que l''hypholome : la galère marginée MORTELLE (Galerina marginata) pousse aussi en touffes sur bois mort, ressemble beaucoup au Kuehneromyces et n''est PAS amère — ne récolter le Kuehneromyces que si l''on reconnaît avec certitude chaque carpophore à son pied chiné de squames brunes"}',false),
('kuehneromyces_mutabilis','hypholoma_fasciculare','it','Le lamelle dell''ipoloma (Schwefelkopf) hanno una tinta giallo zolfo verdastra che manca alla foliota mutabile a lamelle brune (Kuehneromyces); il gambo zigrinato di squame brune sotto l''anello membranoso è il carattere più importante del Kuehneromyces.','Il Kuehneromyces ha odore gradevolmente fungino; l''ipoloma è intensamente amaro. ATTENZIONE: un assaggio distingue SOLO l''ipoloma — la galerina mortale (Galerina) non è amara, un assaggio quindi NON protegge da essa.','Entrambi crescono a ciuffi su legno morto/ceppi di latifoglie e conifere, per cui l''habitat NON è adatto alla distinzione.','Kuehneromyces: sporata bruna (cannella/bruno ruggine); ipoloma a lamelle verdi: sporata bruno violaceo/porpora scuro. Entrambi hanno sporata scura — la sporata li separa solo grossolanamente, verificare quindi obbligatoriamente il gambo e il colore delle lamelle.','Non affidarsi mai solo al sapore amaro: questo protegge soltanto dall''ipoloma, NON dalla galerina mortale dal sapore mite. Raccogliere il Kuehneromyces esclusivamente se OGNI carpoforo mostra l''anello membranoso E, sotto, il gambo zigrinato di squame brune E nessuna tinta verde visibile sulle lamelle — nel dubbio lasciare sul posto.','{"Kuehneromyces: sapore mite-nocciola; ipoloma a lamelle verdi: nettamente e durevolmente AMARO","Lamelle del Kuehneromyces da giovani chiare, poi cannella fino a bruno ruggine; lamelle dell''ipoloma giallo zolfo, poi verdastre fino a verde nerastro","Il Kuehneromyces ha un anello membranoso + sotto squame scure sporgenti sul gambo; l''ipoloma ha al massimo una zona anulare fugace, gambo glabro giallo-bruno ruggine","Gambo del Kuehneromyces sotto l''anello zigrinato di squame brune; gambo dell''ipoloma giallo zolfo in alto, bruno ruggine verso il basso, liscio","PIÙ IMPORTANTE dell''ipoloma: la galerina marginata MORTALE (Galerina marginata) cresce anch''essa a ciuffi su legno morto, somiglia molto al Kuehneromyces e NON è amara — raccogliere il Kuehneromyces solo se si riconosce con certezza ogni carpoforo dal gambo zigrinato di squame brune"}',false),
('kuehneromyces_mutabilis','pholiota_squarrosa','en','Dry, coarsely shaggy-scaly cap in the shaggy scalycap (Pholiota squarrosa) vs smooth, hygrophanous, two-toned cap with a fading margin in the sheathed woodtuft.','The scalycap smells obtrusively radish-like, the sheathed woodtuft pleasantly spicy-mild.','Both in clusters on wood/stumps — site not distinguishing.','Both rust-brown — does NOT serve for distinction here, so other features are mandatory.','Caution: the sheathed woodtuft is itself off-limits for beginners because of the deadly funeral bell (Galerina marginata). Scalycap, sheathed woodtuft and funeral bell all grow in clusters on wood — only harvest this group with expert knowledge and a spore print.','{"The shaggy scalycap has a dry, shaggy-scaly cap; the sheathed woodtuft has a smooth to finely fibrillose, hygrophanous cap with a fading margin (two-toned)","The scalycap is clearly larger and more robust, cap often 5–12 cm; the sheathed woodtuft is small, 3–6 cm","Sheathed woodtuft stem below the ring dark brown and finely scaly/snakeskin-patterned; scalycap stem coarsely shaggy-scaly","Taste: scalycap bitter/unpleasant, sheathed woodtuft mild","Both rust-brown spore print — no distinguishing feature here"}',false),
('kuehneromyces_mutabilis','pholiota_squarrosa','es','Sombrero seco y groseramente erizado-escamoso en la foliota escamosa (Pholiota squarrosa) frente a sombrero liso, higrófano y bicolor con margen que palidece en el Kuehneromyces.','La foliota escamosa tiene un olor invasivo a rábano, el Kuehneromyces un olor agradablemente especiado y suave.','Ambos en grupos sobre madera/tocones — el lugar no distingue.','Ambos pardo herrumbre — aquí NO sirve para la distinción, por lo que otros caracteres son imprescindibles.','Precaución: el Kuehneromyces es ya un tabú para principiantes a causa de la Galerina mortal (Galerina marginata). Foliota escamosa, Kuehneromyces y Galerina crecen todos en grupos sobre madera — recolectar este grupo solo con conocimientos de experto y una esporada.','{"La foliota escamosa tiene un sombrero seco, erizado-escamoso; el Kuehneromyces tiene un sombrero de liso a finamente fibriloso, higrófano, con margen que palidece (bicolor)","La foliota escamosa es claramente más grande y robusta, sombrero a menudo 5–12 cm; el Kuehneromyces es pequeño, 3–6 cm","Pie del Kuehneromyces bajo el anillo pardo oscuro y finamente escamoso/en piel de serpiente; pie de la foliota escamosa groseramente erizado de escamas","Sabor: foliota escamosa amargo/desagradable, Kuehneromyces suave","Ambos con esporada pardo herrumbre — aquí no es un criterio de distinción"}',false),
('kuehneromyces_mutabilis','pholiota_squarrosa','fr','Chapeau sec et grossièrement hérissé-squameux chez la pholiote (Schüppling) vs chapeau lisse, hygrophane et bicolore à marge se décolorant chez le Kuehneromyces.','La pholiote a une odeur envahissante de radis, le Kuehneromyces une odeur agréablement épicée et douce.','Tous deux en touffes sur bois/souches — le site ne distingue pas.','Tous deux brun rouille — ne convient PAS ici à la distinction, d''autres caractères sont donc impératifs.','Prudence : le Kuehneromyces est lui-même tabou pour les débutants à cause de la galère mortelle (Galerina marginata). Pholiote, Kuehneromyces et galère poussent tous en touffes sur bois — ne récolter ce groupe qu''avec un savoir d''expert et une sporée.','{"La pholiote hérissée a un chapeau sec, hérissé-squameux ; le Kuehneromyces a un chapeau lisse à finement fibrilleux, hygrophane, à marge se décolorant (bicolore)","La pholiote est nettement plus grande et plus robuste, chapeau souvent 5–12 cm ; le Kuehneromyces est petit, 3–6 cm","Pied du Kuehneromyces sous l''anneau brun foncé et finement squameux/chiné ; pied de la pholiote grossièrement hérissé de squames","Goût : pholiote amer/désagréable, Kuehneromyces doux","Tous deux à sporée brun rouille — ici pas un critère de distinction"}',false),
('kuehneromyces_mutabilis','pholiota_squarrosa','it','Cappello secco e grossolanamente irto-squamoso nella foliota squarrosa (Schüppling) vs cappello liscio, igrofano e bicolore con margine che sbiadisce nel Kuehneromyces.','La foliota squarrosa ha un odore invadente di ravanello, il Kuehneromyces un odore gradevolmente speziato e mite.','Entrambi a ciuffi su legno/ceppi — il sito non distingue.','Entrambi bruno ruggine — qui NON è adatto alla distinzione, altri caratteri sono quindi imperativi.','Prudenza: il Kuehneromyces è esso stesso un tabù per i principianti a causa della galerina mortale (Galerina marginata). Foliota squarrosa, Kuehneromyces e galerina crescono tutti a ciuffi su legno — raccogliere questo gruppo solo con conoscenze da esperto e una sporata.','{"La foliota squarrosa ha un cappello secco, irto-squamoso; il Kuehneromyces ha un cappello da liscio a finemente fibrilloso, igrofano, con margine che sbiadisce (bicolore)","La foliota squarrosa è nettamente più grande e robusta, cappello spesso 5–12 cm; il Kuehneromyces è piccolo, 3–6 cm","Gambo del Kuehneromyces sotto l''anello bruno scuro e finemente squamoso/zigrinato; gambo della foliota squarrosa grossolanamente irto di squame","Sapore: foliota squarrosa amaro/sgradevole, Kuehneromyces mite","Entrambi a sporata bruno ruggine — qui non un criterio di distinzione"}',false),
('kuehneromyces_mutabilis','pholiotina_rugosa','en','The sheathed woodtuft in clusters on wood with a snakeskin-patterned dark stem; Pholiotina solitary/gregarious on soil, smooth pale stem, wrinkled cap.','Sheathed woodtuft pleasantly spicy; Pholiotina rugosa inconspicuous to slightly rancid — smell is NOT a reliable distinguishing criterion.','Decisive, but do NOT rely on it alone: sheathed woodtuft in clusters on wood; Pholiotina rugosa on ground/lawn/mulch/wood chips. Since Pholiotina can also fruit on wood chips, proximity to wood alone is no free pass — always check several features.','Sheathed woodtuft rust-brown; Pholiotina rugosa rust-brown to cinnamon-brown — spore colour does NOT separate them, so site, stem snakeskin pattern and habit are decisive.','Never mistake little brown mushrooms (LBMs) with a ring for sheathed woodtufts if they grow on soil/lawn/mulch instead of in clusters on wood — danger to life from amatoxins. In an emergency call Tox Info Suisse 145.','{"Pholiotina rugosa (= Conocybe filaris) is a little brown mushroom (LBM) with a thin, brittle stem and a movable, membranous ring — contains deadly amatoxins like the death cap","Pholiotina grows SOLITARY to gregarious on soil, lawn, path edges, mulch, wood chips/compost soil — NOT in clusters on stumps; the sheathed woodtuft grows in dense clusters on rotten wood/stumps","Sheathed woodtuft stem below the ring distinctly dark brown and finely scaly snakeskin-patterned; Pholiotina stem smooth, pale, without snakeskin pattern","Sheathed woodtuft cap hygrophanous, two-toned with a fading margin; Pholiotina cap ochre-brown, wrinkled, without this two-tone colouring","Pholiotina is mostly much smaller and more slender than a typical sheathed woodtuft"}',false),
('kuehneromyces_mutabilis','pholiotina_rugosa','es','El Kuehneromyces en grupos sobre la madera con pie oscuro en piel de serpiente; Pholiotina solitaria/gregaria sobre la tierra, pie liso pálido, sombrero rugoso.','Kuehneromyces agradablemente especiado; Pholiotina rugosa inapreciable a ligeramente rancia — el olor NO es un criterio de distinción seguro.','Decisivo, pero NO fiarse de él solo: Kuehneromyces en grupos sobre madera; Pholiotina rugosa sobre suelo/césped/mantillo/astillas. Como Pholiotina también puede fructificar sobre astillas de madera, la mera cercanía a la madera no es un salvoconducto — comprobar siempre varios caracteres.','Kuehneromyces pardo herrumbre; Pholiotina rugosa pardo herrumbre a pardo canela — el color de las esporas NO distingue, por eso el lugar, el dibujo de piel de serpiente del pie y el porte son decisivos.','NUNCA tomar pequeños hongos pardos (LBM) con anillo por Kuehneromyces si crecen sobre tierra/césped/mantillo en lugar de en grupos sobre madera — peligro de muerte por amatoxinas. En caso de emergencia llamar a Tox Info Suisse 145.','{"Pholiotina rugosa (= Conocybe filaris) es un pequeño hongo pardo (LBM) con pie delgado y quebradizo y un anillo membranoso móvil — contiene amatoxinas mortales como la oronja verde (Amanita phalloides)","Pholiotina crece SOLITARIA a gregaria sobre tierra, césped, bordes de caminos, mantillo, astillas de madera/tierra de compost — NO en grupos sobre tocones; el Kuehneromyces crece en grupos densos sobre madera podrida/tocones","Pie del Kuehneromyces bajo el anillo claramente pardo oscuro y finamente escamoso en piel de serpiente; pie de Pholiotina liso, pálido, sin dibujo de piel de serpiente","Sombrero del Kuehneromyces higrófano, bicolor con margen que palidece; sombrero de Pholiotina pardo ocre, rugoso, sin esta bicromía","Pholiotina suele ser mucho más pequeña y grácil que un Kuehneromyces típico"}',false),
('kuehneromyces_mutabilis','pholiotina_rugosa','fr','Le Kuehneromyces en touffes sur le bois avec pied sombre chiné ; Pholiotina isolé/grégaire sur la terre, pied lisse pâle, chapeau ridé.','Kuehneromyces agréablement épicé ; Pholiotina rugosa discret à légèrement rance — l''odeur n''est PAS un critère de distinction sûr.','Décisif, mais à ne PAS utiliser seul : Kuehneromyces en touffes sur bois ; Pholiotina rugosa sur sol/gazon/paillis/copeaux. Comme Pholiotina peut aussi fructifier sur copeaux de bois, la proximité du bois seule n''est pas un blanc-seing — toujours vérifier plusieurs caractères.','Kuehneromyces brun rouille ; Pholiotina rugosa brun rouille à brun cannelle — la couleur des spores ne distingue PAS, le site, le chiné du pied et le port sont donc décisifs.','Ne JAMAIS prendre de petits champignons bruns (LBM) à anneau pour des Kuehneromyces s''ils poussent sur terre/gazon/paillis plutôt qu''en touffes sur bois — danger de mort par amatoxines. En cas d''urgence, appeler Tox Info Suisse 145.','{"Pholiotina rugosa (= Conocybe filaris) est un petit champignon brun (LBM) à pied mince et cassant et à anneau membraneux mobile — contient des amatoxines mortelles comme l''amanite phalloïde","Pholiotina pousse ISOLÉ à grégaire sur terre, gazon, bords de chemins, paillis, copeaux de bois/terreau de compost — PAS en touffes sur souches ; le Kuehneromyces pousse en touffes denses sur bois pourri/souches","Pied du Kuehneromyces sous l''anneau nettement brun foncé et finement chiné de squames ; pied de Pholiotina lisse, pâle, sans chiné","Chapeau du Kuehneromyces hygrophane, bicolore à marge se décolorant ; chapeau de Pholiotina brun ocre, ridé, sans cette bicoloration","Pholiotina est le plus souvent bien plus petit et plus gracile qu''un Kuehneromyces typique"}',false),
('kuehneromyces_mutabilis','pholiotina_rugosa','it','Il Kuehneromyces a ciuffi sul legno con gambo scuro zigrinato; Pholiotina isolata/gregaria sulla terra, gambo liscio pallido, cappello rugoso.','Kuehneromyces gradevolmente speziato; Pholiotina rugosa inappariscente fino a leggermente rancido — l''odore NON è un criterio di distinzione sicuro.','Decisivo, ma da NON usare da solo: Kuehneromyces a ciuffi su legno; Pholiotina rugosa su suolo/prato/pacciame/cippato. Poiché Pholiotina può fruttificare anche su cippato di legno, la sola vicinanza al legno non è un lasciapassare — verificare sempre più caratteri.','Kuehneromyces bruno ruggine; Pholiotina rugosa bruno ruggine fino a bruno cannella — il colore delle spore NON distingue, perciò il sito, la zigrinatura del gambo e il portamento sono decisivi.','Non scambiare MAI piccoli funghi bruni (LBM) con anello per Kuehneromyces se crescono su terra/prato/pacciame invece che a ciuffi su legno — pericolo di morte da amatossine. In caso d''emergenza chiamare Tox Info Suisse 145.','{"Pholiotina rugosa (= Conocybe filaris) è un piccolo fungo bruno (LBM) a gambo sottile e fragile e con un anello membranoso mobile — contiene amatossine mortali come l''amanita falloide","Pholiotina cresce ISOLATA fino a gregaria su terra, prato, bordi dei sentieri, pacciame, cippato di legno/terriccio di compost — NON a ciuffi su ceppi; il Kuehneromyces cresce a ciuffi densi su legno marcio/ceppi","Gambo del Kuehneromyces sotto l''anello nettamente bruno scuro e finemente zigrinato di squame; gambo di Pholiotina liscio, pallido, senza zigrinatura","Cappello del Kuehneromyces igrofano, bicolore con margine che sbiadisce; cappello di Pholiotina bruno ocra, rugoso, senza questa bicromia","Pholiotina è per lo più molto più piccola e gracile di un tipico Kuehneromyces"}',false),
('laetiporus_sulphureus','hapalopilus_nidulans','en','The sulphur polypore (chicken-of-the-woods) is, when young, a bright sulphur-yellow to orange and pale inside; the cinnamon bracket (Hapalopilus nidulans) is uniformly matt ochre, cinnamon to pinkish-brown throughout and clearly smaller (max. ~18 cm).','The smell is faint and unreliable in both; the mild taste of the poisonous fungus gives no warning — so NEVER rely on smell/taste, but do the KOH (potassium hydroxide) test.','The cinnamon bracket grows mostly on dead hardwood (oak, hazel); the sulphur polypore frequently in clustered brackets on (even living) hardwoods and fruit trees (oak, willow, black locust, plum).','The spore print is whitish in both polypores and barely checkable without collecting — so use the KOH test instead of the spore print.','Never collect brown/ochre polypores without testing them with potassium hydroxide (KOH): violet/lilac = poisonous cinnamon bracket, leave it. Only sulphur polypores growing young in bright sulphur-yellow to orange on hardwood, cooked and only the soft outer margin, are considered edible.','{"Cinnamon bracket (poisonous): KOH/potassium hydroxide on the pores or flesh → immediately strong violet/lilac (even on dried material). Sulphur polypore: no violet reaction. This is the most reliable distinguishing feature.","Colour of the sulphur polypore: when young bright sulphur-yellow to orange. Cinnamon bracket: at most dull ochre/leather-yellow when young, quickly turning cinnamon to pinkish/reddish-brown — never the bright sulphur-yellow-orange of the sulphur polypore.","The cinnamon bracket is the same cinnamon/pinkish-brown colour through and through (including the flesh/trama) and mostly small (bracket 3-12 cm, max. ~18 cm); the young sulphur polypore is whitish-yellow inside and grows clearly larger.","Growth site of the cinnamon bracket: mostly dead hardwood, readily oak and hazel; sulphur polypore often on (even living) hardwoods and fruit trees (oak, willow, black locust, plum, walnut).","Toxin: polyporic acid → after ~12 h latency central nervous disturbances, visual disturbances, vomiting, kidney/liver damage, violet urine — the mild taste gives NO warning, potentially fatal."}',false),
('laetiporus_sulphureus','hapalopilus_nidulans','es','El políporo azufrado (pollo del bosque) es de joven de un amarillo azufre-anaranjado brillante y claro por dentro; el políporo canela (Hapalopilus nidulans) es de un tono uniformemente mate ocre, canela a pardo rosado en todo su cuerpo y claramente más pequeño (máx. ~18 cm).','El olor es débil y poco fiable en ambos; el sabor suave del hongo venenoso no advierte — por eso NUNCA fiarse del olor/sabor, sino hacer la prueba con potasa (KOH).','El políporo canela crece sobre todo en madera muerta de frondosas (roble, avellano); el políporo azufrado con frecuencia en ménsulas agrupadas sobre frondosas y árboles frutales (incluso vivos) (roble, sauce, robinia, ciruelo).','La esporada es blanquecina en ambos políporos y apenas comprobable sin recolectar — por eso usar la prueba KOH en lugar de la esporada.','Nunca recolectar políporos pardos/ocre sin probarlos con potasa (KOH): violeta/lila = políporo canela venenoso, dejarlo. Solo los políporos azufrados que crecen de jóvenes de un amarillo azufre-anaranjado brillante sobre frondosas, cocinados y solo el margen externo tierno, se consideran comestibles.','{"Políporo canela (venenoso): KOH/potasa sobre los poros o la carne → de inmediato violeta/lila intenso (incluso en material seco). Políporo azufrado: ninguna reacción violeta. Es el criterio de distinción más seguro.","Color del políporo azufrado: de joven amarillo azufre brillante a anaranjado. Políporo canela: a lo sumo de joven ocre/amarillo cuero apagado, vira pronto a canela y pardo rosado/rojizo — nunca el amarillo azufre-anaranjado brillante del políporo azufrado.","El políporo canela es de un mismo color canela/pardo rosado de parte a parte (incluida la trama) y por lo general pequeño (ménsula 3-12 cm, máx. ~18 cm); el políporo azufrado joven es blanquecino-amarillo por dentro y se vuelve claramente más grande.","Lugar de crecimiento del políporo canela: sobre todo madera muerta de frondosas, de buena gana roble y avellano; políporo azufrado a menudo sobre frondosas y árboles frutales (incluso vivos) (roble, sauce, robinia, ciruelo, nogal).","Toxina: ácido polipórico → tras ~12 h de latencia, trastornos del sistema nervioso central, trastornos visuales, vómitos, daños renales/hepáticos, orina violeta — el sabor suave NO advierte, posiblemente mortal."}',false),
('laetiporus_sulphureus','hapalopilus_nidulans','fr','Le polypore soufré est jeune d''un jaune soufre-orange éclatant et clair à l''intérieur ; le polypore cannelle (Hapalopilus) est d''une teinte uniformément mate ocre, cannelle à brun rosé et nettement plus petit (max. ~18 cm).','L''odeur est faible et peu fiable chez les deux ; le goût doux du champignon vénéneux n''avertit pas — ne JAMAIS se fier à l''odeur/au goût, mais faire le test à la potasse (KOH).','Le polypore cannelle pousse surtout sur bois feuillu mort (chêne, noisetier) ; le polypore soufré fréquemment en touffes de consoles sur des feuillus et arbres fruitiers (même vivants) (chêne, saule, robinier, prunier).','La sporée est blanchâtre chez les deux polypores et à peine vérifiable sans récolte — utiliser donc le test KOH plutôt que la sporée.','Ne jamais récolter de polypores bruns/ocre sans les tester à la potasse (KOH) : violet/lilas = polypore cannelle vénéneux, à laisser. Seuls les polypores soufrés poussant jeunes d''un jaune soufre-orange éclatant sur feuillu, cuits et seulement la marge externe tendre, sont considérés comme comestibles.','{"Polypore cannelle (vénéneux) : KOH/potasse sur les pores ou la chair → immédiatement violet/lilas intense (même sur matériel sec). Polypore soufré : aucune réaction violette. C''est le critère de distinction le plus sûr.","Couleur du polypore soufré : jeune, jaune soufre éclatant à orange. Polypore cannelle : au mieux jeune ocre/jaune cuir terne, vire vite cannelle à brun rosé/rougeâtre — jamais le jaune soufre-orange éclatant du polypore soufré.","Le polypore cannelle est de part en part d''une même couleur cannelle/brun rosé (y compris la trame) et le plus souvent petit (console 3-12 cm, max. ~18 cm) ; le jeune polypore soufré est blanchâtre-jaune à l''intérieur et devient nettement plus grand.","Lieu de croissance du polypore cannelle : surtout bois feuillu mort, volontiers chêne et noisetier ; polypore soufré souvent sur feuillus et arbres fruitiers (même vivants) (chêne, saule, robinier, prunier, noyer).","Toxine : acide polyporique → après ~12 h de latence, troubles du système nerveux central, troubles visuels, vomissements, atteintes rénales/hépatiques, urine violette — le goût doux n''AVERTIT PAS, potentiellement mortel."}',false),
('laetiporus_sulphureus','hapalopilus_nidulans','it','Il poliporo zolfino da giovane è di un giallo zolfo-arancio brillante e chiaro all''interno; il poliporo cannella (Hapalopilus) è di una tinta uniformemente opaca ocra, cannella fino a bruno rosato e nettamente più piccolo (max. ~18 cm).','L''odore è debole e inaffidabile in entrambi; il sapore mite del fungo velenoso non avverte — NON affidarsi MAI a odore/sapore, ma fare il test con la potassa (KOH).','Il poliporo cannella per lo più su legno di latifoglie morto (quercia, nocciolo); il poliporo zolfino spesso a ciuffi di mensole su latifoglie e alberi da frutto (anche vivi) (quercia, salice, robinia, susino).','La sporata è biancastra in entrambi i polipori e quasi non verificabile senza raccolta — usare quindi il test KOH invece della sporata.','Non raccogliere mai polipori bruni/ocra senza testarli con la potassa (KOH): viola/lilla = poliporo cannella velenoso, da lasciare. Solo i polipori zolfini che crescono da giovani di un giallo zolfo-arancio brillante su latifoglie, cotti e soltanto il margine esterno tenero, sono considerati commestibili.','{"Poliporo cannella (velenoso): KOH/potassa sui pori o sulla carne → subito viola/lilla intenso (anche su materiale secco). Poliporo zolfino: nessuna reazione viola. È il criterio di distinzione più sicuro.","Colore del poliporo zolfino: da giovane giallo zolfo brillante fino all''arancio. Poliporo cannella: al massimo da giovane ocra/giallo cuoio spento, vira presto al cannella fino al bruno rosato/rossastro — mai il giallo zolfo-arancio brillante del poliporo zolfino.","Il poliporo cannella è da parte a parte dello stesso colore cannella/bruno rosato (anche la trama) e per lo più piccolo (mensola 3-12 cm, max. ~18 cm); il giovane poliporo zolfino è biancastro-giallo all''interno e diventa nettamente più grande.","Luogo di crescita del poliporo cannella: per lo più legno di latifoglie morto, volentieri quercia e nocciolo; poliporo zolfino spesso su latifoglie e alberi da frutto (anche vivi) (quercia, salice, robinia, susino, noce).","Tossina: acido poliporico → dopo ~12 h di latenza disturbi del sistema nervoso centrale, disturbi della vista, vomito, danni renali/epatici, urina viola — il sapore mite NON avverte, potenzialmente mortale."}',false),
('lepista_nuda','mycena_pura','en','Lepista nuda: large, fleshy, uniformly strong violet with an unstriated cap; Mycena pura: small, glassy-striate, pale lilac and fading quickly.','Mycena pura smells strongly and penetratingly of radish; Lepista nuda smells pleasantly spicy-perfumed — the radish smell is the most important warning signal.','Both in broadleaf and conifer forest on the leaf litter; Lepista nuda often gregarious or in fairy rings in fallen leaves, Mycena pura solitary to gregarious on litter and needles.','Lepista nuda: pink to pale lilac spore print; Mycena pura: white spore print — the spore print colour separates the two unambiguously.','Any small, thin-fleshed, striate-glassy lilac mushroom with a strong radish smell is suspect — radish smell + white spore print reliably rule out the edible wood blewit (Lepista nuda).','{"Mycena pura is poisonous (contains muscarine, formerly wrongly listed as edible); the wood blewit (Lepista nuda) is edible only THOROUGHLY COOKED","Mycena pura smells intensely and penetratingly of radish; Lepista nuda smells pleasantly spicy-perfumed, never of radish","Mycena pura is small and thin-fleshed (cap only up to ~4 cm, glassy-helmet-shaped, striate); Lepista nuda strongly fleshy (cap 5-15 cm, not striate)","Mycena pura with a thin, hollow, fragile stem; Lepista nuda with a firm, fibrous-solid, often violet stem","Lepista nuda uniformly strong violet to grey-lilac throughout (cap, gills, stem); Mycena pura only pale lilac/pink and fading rapidly"}',false),
('lepista_nuda','mycena_pura','es','Lepista nuda: grande, carnoso, uniformemente de un violeta intenso con sombrero no estriado; Mycena pura: pequeña, vítrea-estriada, lila pálido y que palidece rápidamente.','Mycena pura huele fuerte y penetrantemente a rábano; Lepista nuda tiene un olor agradablemente especiado-perfumado — el olor a rábano es la principal señal de alarma.','Ambos en bosque de frondosas y coníferas sobre la hojarasca; Lepista nuda a menudo gregario o en corros de brujas en la hojarasca caída, Mycena pura de solitaria a gregaria sobre hojarasca y acículas.','Lepista nuda: esporada rosa a lila pálido; Mycena pura: esporada blanca — el color de la esporada los distingue inequívocamente.','Todo hongo lila pequeño, de carne fina, estriado-vítreo y con fuerte olor a rábano es sospechoso — olor a rábano + esporada blanca descartan con seguridad la pie azul comestible (Lepista nuda).','{"Mycena pura es venenosa (contiene muscarina, antiguamente catalogada erróneamente como comestible); la pie azul (Lepista nuda) es comestible solo BIEN COCINADA","Mycena pura huele intensa y penetrantemente a rábano; Lepista nuda huele agradablemente especiado-perfumado, nunca a rábano","Mycena pura es pequeña y de carne fina (sombrero solo hasta ~4 cm, vítreo-en casco, estriado); Lepista nuda marcadamente carnoso (sombrero 5-15 cm, no estriado)","Mycena pura con pie fino, hueco y frágil; Lepista nuda con pie firme, fibroso-macizo, a menudo violeta","Lepista nuda uniformemente de un violeta intenso a gris-lila en todo su cuerpo (sombrero, láminas, pie); Mycena pura solo lila/rosa pálido y que palidece rápidamente"}',false),
('lepista_nuda','mycena_pura','fr','Lepista nuda : grand, charnu, uniformément d''un violet vif avec chapeau non strié ; Mycena pura : petit, vitreux-strié, lilas pâle et se décolorant vite.','Mycena pura sent fortement et de façon pénétrante le radis ; Lepista nuda a une odeur agréablement épicée-parfumée — l''odeur de radis est le principal signal d''alarme.','Tous deux en forêt de feuillus et de conifères sur la litière ; Lepista nuda souvent en groupe ou en ronds de sorcière dans les feuilles mortes, Mycena pura isolé à grégaire sur litière et aiguilles.','Lepista nuda : sporée rose à lilas pâle ; Mycena pura : sporée blanche — la couleur de la sporée les distingue clairement.','Tout petit champignon lilas à chair mince, strié-vitreux et à forte odeur de radis est suspect — odeur de radis + sporée blanche excluent avec certitude le pied-bleu comestible.','{"Mycena pura est vénéneux (contient de la muscarine, autrefois faussement réputé comestible) ; le pied-bleu (Lepista nuda) n''est comestible que BIEN CUIT","Mycena pura sent intensément et de façon pénétrante le radis ; Lepista nuda sent agréablement épicé-parfumé, jamais le radis","Mycena pura est petit et à chair mince (chapeau jusqu''à ~4 cm seulement, vitreux-en casque, strié) ; Lepista nuda est nettement charnu (chapeau 5-15 cm, non strié)","Mycena pura a un pied mince, creux et fragile ; Lepista nuda a un pied ferme, fibreux-plein, souvent violet","Lepista nuda est uniformément d''un violet vif à gris-lilas (chapeau, lames, pied) ; Mycena pura n''est que lilas/rose pâle et se décolore rapidement"}',false),
('lepista_nuda','mycena_pura','it','Lepista nuda: grande, carnoso, uniformemente di un viola intenso con cappello non striato; Mycena pura: piccola, vitrea-striata, lilla pallido e che sbiadisce rapidamente.','Mycena pura odora fortemente e in modo penetrante di ravanello; Lepista nuda ha un odore gradevolmente speziato-profumato — l''odore di ravanello è il principale segnale d''allarme.','Entrambi in bosco di latifoglie e conifere sulla lettiera; Lepista nuda spesso in gruppo o in cerchi delle streghe nelle foglie cadute, Mycena pura da isolata a gregaria su lettiera e aghi.','Lepista nuda: sporata rosa fino a lilla pallido; Mycena pura: sporata bianca — il colore della sporata li distingue chiaramente.','Ogni piccolo fungo lilla a carne sottile, striato-vitreo e con forte odore di ravanello è sospetto — odore di ravanello + sporata bianca escludono con certezza l''agarico violetto commestibile (Lepista nuda).','{"Mycena pura è velenosa (contiene muscarina, un tempo erroneamente ritenuta commestibile); l''agarico violetto (Lepista nuda) è commestibile solo BEN COTTO","Mycena pura odora intensamente e in modo penetrante di ravanello; Lepista nuda odora gradevolmente speziato-profumato, mai di ravanello","Mycena pura è piccola e a carne sottile (cappello solo fino a ~4 cm, vitreo-a elmo, striato); Lepista nuda nettamente carnoso (cappello 5-15 cm, non striato)","Mycena pura con gambo sottile, cavo e fragile; Lepista nuda con gambo sodo, fibroso-pieno, spesso viola","Lepista nuda uniformemente di un viola intenso fino a grigio-lilla (cappello, lamelle, gambo); Mycena pura solo lilla/rosa pallido e che sbiadisce rapidamente"}',false),
('lycoperdon_perlatum','scleroderma_citrinum','en','The common earthball (Scleroderma citrinum) is yellow-brown, hard, coarsely scurfy-areolate, without a true distinct stem; the common puffball (Lycoperdon perlatum) is white-grey with fine pyramidal spines and a distinctly set-off stem-like lower part.','The earthball smells unpleasantly metallic-rubbery; the puffball when young mild-mushroomy, inconspicuous.','The earthball on acidic, poor forest soil, mycorrhizal with trees (oak, beech, birch); the puffball on forest and meadow soils in conifer and broadleaf forest, on path edges.','Maturity assessment instead of spore print: the earthball already has, in half-ripe pieces, a brown-black spore mass inside; the young puffball in section is still completely white without a dark spore mass.','Cut EVERY round puffball lengthwise completely in two BEFORE eating: if the inside is not pure white and homogeneous throughout (dark-marbled, greyish or hard-shelled), throw it away — that is the poisonous earthball.','{"The cut test is decisive: puffball when young pure white and homogeneous-soft inside; earthball already when young with a greyish, then violet-black-marbled, hard inside.","The earthball has a thick (up to 5 mm), tough, hard outer rind with a coarse, scurfy-areolate surface; the puffball has a thin, soft skin with fine pyramidal spines/warts that fall off later.","The earthball smells unpleasantly metallic/rubbery; the puffball when young inconspicuously mild-mushroomy.","The earthball sits almost stemless and tuberous on the ground; the puffball has a distinctly set-off, slender sterile stem part (pear/bottle shape)."}',false),
('lycoperdon_perlatum','scleroderma_citrinum','es','El escleroderma (Scleroderma citrinum) es pardo amarillento, duro, groseramente costroso-areolado, sin un verdadero pie diferenciado; el pedo de lobo perlado (Lycoperdon perlatum) es blanco-gris con finas espinas piramidales y una parte inferior a modo de pie claramente diferenciada.','El escleroderma huele desagradablemente metálico-gomoso; el pedo de lobo joven suave-a hongo, inapreciable.','El escleroderma sobre suelo forestal ácido y pobre, micorrízico con árboles (roble, haya, abedul); el pedo de lobo sobre suelos de bosques y prados en bosque de coníferas y frondosas, en bordes de caminos.','Determinación por la madurez en lugar de la esporada: el escleroderma ya tiene, en piezas semimaduras, una masa esporal pardo-negra en el interior; el pedo de lobo joven en sección está aún completamente blanco sin masa esporal oscura.','Cortar en dos a lo largo CADA pedo de lobo redondo ANTES de comerlo: si el interior no es de un blanco puro y homogéneo en su totalidad (jaspeado oscuro, grisáceo o de cáscara dura), tirarlo — ese es el escleroderma venenoso.','{"La prueba del corte es decisiva: pedo de lobo joven blanco puro y homogéneo-blando por dentro; escleroderma ya de joven con interior grisáceo, luego jaspeado negro-violeta, duro.","El escleroderma tiene una corteza externa gruesa (hasta 5 mm), coriácea y dura con superficie grosera, costrosa-areolada; el pedo de lobo tiene una piel fina y blanda con finas espinas/verrugas piramidales que se desprenden más tarde.","El escleroderma huele desagradablemente metálico/gomoso; el pedo de lobo joven inapreciablemente suave-a hongo.","El escleroderma se asienta casi sin pie y tuberoso sobre el suelo; el pedo de lobo tiene una parte estéril a modo de pie claramente diferenciada y esbelta (forma de pera/botella)."}',false),
('lycoperdon_perlatum','scleroderma_citrinum','fr','Le scléroderme (Kartoffelbovist) est jaune-brun, dur, grossièrement croûteux-aréolé, sans véritable pied distinct ; la vesse-de-loup perlée (Lycoperdon) est blanc-gris avec de fins aiguillons pyramidaux et une partie inférieure nettement distincte en forme de pied.','Le scléroderme a une odeur désagréable métallique-caoutchouteuse ; la vesse-de-loup jeune douce-fongique, discrète.','Le scléroderme sur sol forestier acide et pauvre, mycorhizien sur les arbres (chêne, hêtre, bouleau) ; la vesse-de-loup sur sols de forêts et de prairies en forêt de conifères et de feuillus, sur les bords de chemins.','Détermination par la maturité plutôt que par sporée : le scléroderme a déjà, sur des pièces à demi mûres, une masse sporale brun-noir à l''intérieur ; la jeune vesse-de-loup en coupe est encore entièrement blanche sans masse sporale sombre.','Couper en deux dans la longueur CHAQUE vesse ronde AVANT de la manger : si l''intérieur n''est pas d''un blanc pur et homogène en continu (marbré sombre, grisâtre ou à coque dure), la jeter — c''est le scléroderme vénéneux.','{"Le test de coupe est décisif : vesse-de-loup jeune blanche pure et homogène-molle à l''intérieur ; scléroderme déjà jeune à intérieur grisâtre, puis marbré noir-violet, dur.","Le scléroderme a une enveloppe externe épaisse (jusqu''à 5 mm), coriace et dure à surface grossière, croûteuse-aréolée ; la vesse-de-loup a une peau mince et molle à fins aiguillons/verrues pyramidaux qui tombent plus tard.","Le scléroderme sent désagréablement métallique/caoutchouteux ; la vesse-de-loup jeune discrètement douce-fongique.","Le scléroderme repose au sol presque sans pied, tubéreux ; la vesse-de-loup a une partie inférieure stérile nettement distincte et élancée (forme de poire/bouteille)."}',false),
('lycoperdon_perlatum','scleroderma_citrinum','it','Lo scleroderma (Kartoffelbovist) è giallo-bruno, duro, grossolanamente crostoso-areolato, senza un vero gambo distinto; la vescia perlata (Lycoperdon) è bianco-grigia con fini aculei piramidali e una parte inferiore nettamente distinta a forma di gambo.','Lo scleroderma ha un odore sgradevole metallico-gommoso; la vescia da giovane mite-fungina, inappariscente.','Lo scleroderma su suolo forestale acido e povero, micorrizico sugli alberi (quercia, faggio, betulla); la vescia su suoli di boschi e prati in bosco di conifere e latifoglie, sui bordi dei sentieri.','Determinazione tramite la maturità invece della sporata: lo scleroderma ha già, in pezzi semimaturi, una massa sporale bruno-nera all''interno; la giovane vescia in sezione è ancora completamente bianca senza massa sporale scura.','Tagliare in due per il lungo OGNI vescia rotonda PRIMA di mangiarla: se l''interno non è di un bianco puro e omogeneo in modo continuo (marmorizzato scuro, grigiastro o a guscio duro), buttarla — è lo scleroderma velenoso.','{"Il test di taglio è decisivo: vescia da giovane bianca pura e omogenea-molle all''interno; scleroderma già da giovane con interno grigiastro, poi marmorizzato nero-viola, duro.","Lo scleroderma ha un involucro esterno spesso (fino a 5 mm), coriaceo e duro a superficie grossolana, crostosa-areolata; la vescia ha una pelle sottile e molle con fini aculei/verruche piramidali che cadono più tardi.","Lo scleroderma odora sgradevolmente metallico/gommoso; la vescia da giovane inappariscentemente mite-fungina.","Lo scleroderma siede al suolo quasi senza gambo, tuberoso; la vescia ha una parte inferiore sterile nettamente distinta e slanciata (forma di pera/bottiglia)."}',false),
('lycoperdon_perlatum','scleroderma_verrucosum','en','The thin-skinned earthball (Scleroderma verrucosum) is yellow-brown, finely warty, with a distinctly furrowed sterile stem base; the common puffball is white-grey with fine spines and a smooth, set-off stem part.','Earthball metallic-unpleasant; puffball when young mild-mushroomy.','The thin-skinned earthball on sandy soils in heath, broadleaf and conifer forest, often on path edges; the puffball in forests and on meadows.','Earthball in section early on dark-brown-spored; young puffball still with white flesh without a dark spore mass.','Cut every globular mushroom lengthwise: a dark, marbled or violet-black inside means earthball — never eat it. Only a pure white, homogeneous inside throughout is safe.','{"The thin-skinned earthball has — unlike the thick-skinned one — a distinctly developed, furrowed, sterile stem base with mycelial cords, which makes it outwardly more similar to the stalked puffball and therefore especially easy to confuse.","The cut flesh of the earthball turns greyish to dark-marbled already when young; the puffball when young pure white and homogeneous.","Earthball rind leathery-tough, finely brown-warty; puffball skin soft with fine, deciduous pyramidal spines.","The earthball smells metallic-unpleasant; the young puffball mild-mushroomy."}',false),
('lycoperdon_perlatum','scleroderma_verrucosum','es','El escleroderma de cáscara fina (Scleroderma verrucosum) es pardo amarillento, finamente verrugoso, con una base estéril a modo de pie claramente surcada; el pedo de lobo perlado es blanco-gris con finas espinas y una parte a modo de pie lisa y diferenciada.','Escleroderma metálico-desagradable; pedo de lobo joven suave-a hongo.','El escleroderma de cáscara fina sobre suelos arenosos en brezal, bosque de frondosas y coníferas, a menudo en bordes de caminos; el pedo de lobo en bosques y sobre prados.','Escleroderma en sección tempranamente de esporas pardo oscuras; pedo de lobo joven aún con carne blanca sin masa esporal oscura.','Cortar cada hongo globoso a lo largo: un interior oscuro, jaspeado o negro-violeta significa escleroderma — no comerlo nunca. Solo un interior de un blanco puro y homogéneo en su totalidad es seguro.','{"El escleroderma de cáscara fina tiene — a diferencia del de cáscara gruesa — una base estéril a modo de pie claramente marcada, surcada, con cordones miceliales, lo que lo hace exteriormente más parecido al pedo de lobo pedunculado y por ello especialmente confundible.","La carne de corte del escleroderma se vuelve ya de joven grisácea a jaspeada oscura; el pedo de lobo de joven es de un blanco puro y homogéneo.","Corteza del escleroderma coriácea, finamente verrugosa de pardo; piel del pedo de lobo blanda con finas espinas piramidales caducas.","El escleroderma huele metálico-desagradable; el pedo de lobo joven suave-a hongo."}',false),
('lycoperdon_perlatum','scleroderma_verrucosum','fr','Le scléroderme à coque mince (Scleroderma verrucosum) est jaune-brun, finement verruqueux, avec une base stérile nettement sillonnée en forme de pied ; la vesse-de-loup perlée est blanc-gris avec de fins aiguillons et une partie en pied lisse et distincte.','Scléroderme métallique-désagréable ; vesse-de-loup jeune douce-fongique.','Le scléroderme à coque mince sur sols sableux en lande, forêt de feuillus et de conifères, souvent sur les bords de chemins ; la vesse-de-loup en forêts et sur prairies.','Scléroderme en coupe précocement à spores brun foncé ; jeune vesse-de-loup encore à chair blanche sans masse sporale sombre.','Couper chaque champignon sphérique dans la longueur : un intérieur sombre, marbré ou noir-violet signifie scléroderme — ne jamais le manger. Seul un intérieur d''un blanc pur et homogène en continu est sûr.','{"Le scléroderme à coque mince a — contrairement à celui à coque épaisse — une base stérile nettement marquée, sillonnée, avec des cordons mycéliens, ce qui le rend extérieurement plus semblable à la vesse-de-loup pédicellée et donc particulièrement confondable.","La chair de coupe du scléroderme devient déjà jeune grisâtre à marbrée sombre ; la vesse-de-loup jeune est d''un blanc pur et homogène.","Coque du scléroderme coriace, finement verruqueuse de brun ; peau de la vesse-de-loup molle à fins aiguillons pyramidaux caducs.","Le scléroderme sent métallique-désagréable ; la jeune vesse-de-loup douce-fongique."}',false),
('lycoperdon_perlatum','scleroderma_verrucosum','it','Lo scleroderma a guscio sottile (Scleroderma verrucosum) è giallo-bruno, finemente verrucoso, con una base sterile nettamente solcata a forma di gambo; la vescia perlata è bianco-grigia con fini aculei e una parte a gambo liscia e distinta.','Scleroderma metallico-sgradevole; vescia da giovane mite-fungina.','Lo scleroderma a guscio sottile su suoli sabbiosi in brughiera, bosco di latifoglie e conifere, spesso sui bordi dei sentieri; la vescia in boschi e su prati.','Scleroderma in sezione precocemente a spore bruno scuro; giovane vescia ancora a carne bianca senza massa sporale scura.','Tagliare ogni fungo sferico per il lungo: un interno scuro, marmorizzato o nero-viola significa scleroderma — non mangiarlo mai. Solo un interno di un bianco puro e omogeneo in modo continuo è sicuro.','{"Lo scleroderma a guscio sottile ha — a differenza di quello a guscio spesso — una base sterile nettamente marcata, solcata, con cordoni miceliali, il che lo rende esteriormente più simile alla vescia peduncolata e quindi particolarmente confondibile.","La carne di taglio dello scleroderma diventa già da giovane grigiastra fino a marmorizzata scura; la vescia da giovane è di un bianco puro e omogenea.","Guscio dello scleroderma coriaceo, finemente verrucoso di bruno; pelle della vescia molle con fini aculei piramidali caduchi.","Lo scleroderma odora metallico-sgradevole; la giovane vescia mite-fungina."}',false),
('macrolepiota_mastoidea','lepiota_brunneoincarnata','en','The slender parasol (Macrolepiota mastoidea) shows a pronounced pointed central nipple and a movable ring; the deadly dapperling stays distinctly smaller, flesh-pink-brown in appearance, with an unpatterned, scale-belted stem.','Both inconspicuous to slightly sweetish - smell does NOT separate them, never rely on it.','Both at grassy forest edges, meadows and parks - strong overlap, so reliably separable only by size, the pointed nipple, stem features and the movable ring.','Both with a white spore print - no separating feature.','Since the size difference here is smaller, it applies all the more: accept only dapperlings with a clearly movable ring, a pointed central nipple and a cap clearly above 8 cm; when in doubt leave every small dapperling standing.','{"Slender parasol: cap 6-12 cm with a striking pointed nipple in the centre; flesh-pink dapperling: only 2-5 cm","Slender parasol: movable ring; poisonous dapperling: fleeting, non-movable fibrous ring zone","Slender parasol: stem at most finely/delicately snakeskin-patterned (weaker than in the parasol); poisonous dapperling: stem unpatterned, with flesh-brown scale belts","Slender parasol cap finely light-brown scaly on a whitish ground; poisonous dapperling cap flesh-pink-brown, broken up into concentric scales","The flesh-pink dapperling contains deadly amatoxins; the slender parasol is edible - because the size difference here is smaller, this confusion is especially tricky"}',false),
('macrolepiota_mastoidea','lepiota_brunneoincarnata','es','La galamperna mamelonada (Macrolepiota mastoidea) muestra un marcado mamelón central puntiagudo y un anillo deslizante; la lepiota mortal permanece claramente más pequeña, de aspecto pardo-rosa carne, con pie no jaspeado y ceñido de escamas.','Ambos discretos hasta ligeramente dulzones - el olor NO los separa, no fiarse nunca de él.','Ambos en bordes de bosque herbosos, prados y parques - fuerte solapamiento, por lo que solo separables con seguridad mediante el tamaño, el mamelón puntiagudo, los caracteres del pie y el anillo deslizante.','Ambos con esporada blanca - ningún rasgo de separación.','Como aquí la diferencia de tamaño es menor, vale con mayor razón: aceptar solo lepiotas con anillo claramente deslizante, mamelón central puntiagudo y sombrero claramente superior a 8 cm; en caso de duda dejar en su sitio toda lepiota pequeña.','{"Galamperna mamelonada: sombrero 6-12 cm con un mamelón puntiagudo llamativo en el centro; lepiota pardo-rosada: solo 2-5 cm","Galamperna mamelonada: anillo deslizante; lepiota tóxica: zona anular fibrosa fugaz, no deslizante","Galamperna mamelonada: pie a lo sumo fina/delicadamente jaspeado (más débil que en el parasol); lepiota tóxica: pie no jaspeado, con cinturones de escamas pardo carne","Sombrero de la galamperna mamelonada finamente escamoso pardo claro sobre fondo blanquecino; sombrero de la lepiota tóxica pardo-rosa carne, disgregado en escamas concéntricas","La lepiota pardo-rosada contiene amatoxinas mortales; la galamperna mamelonada es comestible - como aquí la diferencia de tamaño es menor, esta confusión es especialmente delicada"}',false),
('macrolepiota_mastoidea','lepiota_brunneoincarnata','fr','La lépiote mamelonnée présente un mamelon central pointu marqué et un anneau coulissant ; la lépiote mortelle reste nettement plus petite, d''aspect brun-rose chair, à pied non chiné et ceinturé de squames.','Tous deux discrets à légèrement douceâtres - l''odeur ne les sépare PAS, ne jamais s''y fier.','Tous deux en lisières de forêt herbeuses, prairies et parcs - fort chevauchement, donc séparables de façon sûre uniquement par la taille, le mamelon pointu, les caractères du pied et l''anneau coulissant.','Tous deux à sporée blanche - pas de critère de séparation.','Comme la différence de taille est ici plus faible, cela vaut d''autant plus : n''accepter que les lépiotes à anneau nettement coulissant, à mamelon central pointu et à chapeau nettement supérieur à 8 cm ; au moindre doute, laisser sur place toute petite lépiote.','{"Lépiote mamelonnée : chapeau 6-12 cm avec un mamelon pointu marquant au centre ; lépiote brun-incarnat : seulement 2-5 cm","Lépiote mamelonnée : anneau coulissant ; lépiote toxique : zone annulaire fibreuse fugace, non coulissante","Lépiote mamelonnée : pied tout au plus finement/délicatement chiné (plus faible que chez le parasol) ; lépiote toxique : pied non chiné, à ceintures de squames brun chair","Chapeau de la lépiote mamelonnée finement squameux brun clair sur fond blanchâtre ; chapeau de la lépiote toxique brun-rose chair, dissocié en squames concentriques","La lépiote brun-incarnat contient des amatoxines mortelles ; la lépiote mamelonnée est comestible - comme la différence de taille est ici plus faible, cette confusion est particulièrement délicate"}',false),
('macrolepiota_mastoidea','lepiota_brunneoincarnata','it','La lepiota mammellonata mostra un marcato umbone centrale appuntito e un anello scorrevole; la lepiota mortale resta nettamente più piccola, di aspetto bruno-rosa carne, con gambo non zebrato e cinto di squame.','Entrambi insignificanti fino a leggermente dolciastri - l''odore NON li distingue, non fidarsene mai.','Entrambi ai margini erbosi dei boschi, prati e parchi - forte sovrapposizione, quindi distinguibili in sicurezza solo tramite dimensione, umbone appuntito, caratteri del gambo e anello scorrevole.','Entrambi con sporata bianca - nessun criterio di separazione.','Poiché qui la differenza di dimensione è minore, vale a maggior ragione: accettare solo lepiote con anello chiaramente scorrevole, umbone centrale appuntito e cappello nettamente superiore a 8 cm; nel dubbio lasciare sul posto ogni piccola lepiota.','{"Lepiota mammellonata: cappello 6-12 cm con marcato umbone appuntito al centro; lepiota bruno-incarnata: solo 2-5 cm","Lepiota mammellonata: anello scorrevole; lepiota tossica: zona anulare fibrosa fugace, non scorrevole","Lepiota mammellonata: gambo al massimo finemente/delicatamente zebrato (più debole che nel parasol); lepiota tossica: gambo non zebrato, con cinture di squame bruno carne","Cappello della lepiota mammellonata finemente squamoso bruno chiaro su fondo biancastro; cappello della lepiota tossica bruno-rosa carne, dissociato in squame concentriche","La lepiota bruno-incarnata contiene amatossine mortali; la lepiota mammellonata è commestibile - poiché qui la differenza di dimensione è minore, questa confusione è particolarmente insidiosa"}',false),
('marasmius_oreades','clitocybe_phyllophila','en','The fairy ring mushroom is leather-yellow to beige with an umbo and widely spaced, non-decurrent gills; the white funnel caps are pure white and frosted, with crowded, (weakly) decurrent gills.','The fairy ring mushroom smells pleasantly spicy (clove/bitter almond); the funnel cap is musty-sweetish/perfumed — smell alone is not proof.','The fairy ring mushroom grows in meadows, pastures and lawns (often in fairy rings). Clitocybe phyllophila occurs mainly in the leaf/needle litter of forests, parks and gardens; the truly dangerous WHITE MEADOW funnel caps (C. rivulosa/dealbata), by contrast, share the grassy habitat of the fairy ring mushroom.','Fairy ring mushroom white, frosty funnel cap likewise white/cream — spore colour does NOT separate them here. Therefore check gill arrangement (widely spaced/non-decurrent) and stem toughness.','On meadow/lawn take only mushrooms with a tough-pliable, non-breaking stem and widely spaced, NON-decurrent gills — every white funnel cap with decurrent gills (whether forest or meadow species) is consistently left standing.','{"Fairy ring mushroom: gills widely spaced, pale, NOT decurrent, stem tough-pliable (twists without breaking) — frosty funnel cap: gills crowded and weakly decurrent, stem brittle.","The fairy ring mushroom smells spicy-sweetish (clove/bitter almond); the frosty funnel cap is musty-sweetish/perfumed.","White funnel caps (Clitocybe phyllophila and especially the meadow species C. rivulosa/dealbata) are muscarine-suspect/poisonous — they are the classic dangerous confusion among white-capped meadow mushrooms.","Fairy ring mushroom cap leather-yellow to beige with a blunt central umbo and a translucent-striate margin; white funnel caps glassy-white frosted, often depressed/funnel-shaped.","Safety rule: on grassy sites also watch for the more dangerous white meadow funnel caps (C. rivulosa/dealbata) — not just C. phyllophila."}',false),
('marasmius_oreades','clitocybe_phyllophila','es','El senderuela (Marasmius oreades) es de color amarillo cuero-beige con mamelón y láminas espaciadas, no decurrentes; los clitocibes blancos son de un blanco puro pruinoso, con láminas apretadas y (débilmente) decurrentes.','La senderuela huele agradablemente a especias (clavo/almendra amarga); el clitocibe es a moho-dulzón/perfumado — el olor por sí solo no es prueba.','La senderuela crece en prados, pastos y céspedes (a menudo en corros de brujas). Clitocybe phyllophila se encuentra sobre todo en la hojarasca de hojas/acículas de bosques, parques y jardines; en cambio, los clitocibes BLANCOS DE PRADO realmente peligrosos (C. rivulosa/dealbata) comparten el hábitat herboso de la senderuela.','Senderuela blanca, clitocibe blanquecino también blanco/crema — el color de las esporas aquí NO separa. Por ello, verificar la disposición de las láminas (espaciadas/no decurrentes) y la tenacidad del pie.','En prado/césped tomar solo setas con pie correoso-flexible, que no se rompe, y con láminas espaciadas, NO decurrentes — todo clitocibe blanco con láminas decurrentes (sea de bosque o de prado) se deja sistemáticamente en su sitio.','{"Senderuela: láminas espaciadas, pálidas, NO decurrentes, pie correoso-flexible (se retuerce sin romperse) — clitocibe blanquecino: láminas apretadas y débilmente decurrentes, pie quebradizo.","La senderuela huele a especias-dulzón (clavo/almendra amarga); el clitocibe blanquecino es a moho-dulzón/perfumado.","Los clitocibes blancos (Clitocybe phyllophila y sobre todo las especies de prado C. rivulosa/dealbata) son sospechosos de muscarina/tóxicos — son la clásica confusión peligrosa de las setas de prado de sombrero blanco.","Sombrero de la senderuela amarillo cuero-beige con mamelón central obtuso y margen translúcido-estriado; clitocibes blancos blanco vítreo pruinoso, a menudo deprimidos/en embudo.","Regla de seguridad: en estaciones herbosas vigilar además los clitocibes blancos de prado más peligrosos (C. rivulosa/dealbata) — no solo C. phyllophila."}',false),
('marasmius_oreades','clitocybe_phyllophila','fr','Le marasme des Oréades (faux mousseron) est jaune cuir-beige avec un mamelon et des lames espacées, non décurrentes ; les clitocybes blancs sont d''un blanc pur pruineux, à lames serrées et (faiblement) décurrentes.','Le marasme des Oréades a une odeur agréable épicée (clou de girofle/amande amère) ; le clitocybe est moisi-douceâtre/parfumé — l''odeur seule n''est pas une preuve.','Le marasme des Oréades pousse dans les prairies, pâturages et pelouses (souvent en ronds de sorcière). Clitocybe phyllophila se rencontre surtout dans la litière de feuilles/aiguilles des forêts, parcs et jardins ; en revanche les clitocybes BLANCS DES PRAIRIES réellement dangereux (C. rivulosa/dealbata) partagent le milieu gazonné du marasme des Oréades.','Marasme des Oréades blanc, clitocybe blanchâtre également blanc/crème — la couleur des spores ne sépare PAS ici. Vérifier donc la disposition des lames (espacées/non décurrentes) et la ténacité du pied.','En prairie/pelouse, ne prendre que des champignons à pied coriace et souple, ne cassant pas, et à lames espacées, NON décurrentes — tout clitocybe blanc à lames décurrentes (qu''il soit forestier ou prairial) reste systématiquement sur place.','{"Marasme des Oréades : lames espacées, pâles, NON décurrentes, pied coriace-souple (se tord sans casser) — clitocybe blanchâtre : lames serrées et faiblement décurrentes, pied cassant.","Le marasme des Oréades sent l''épicé-douceâtre (clou de girofle/amande amère) ; le clitocybe blanchâtre est moisi-douceâtre/parfumé.","Les clitocybes blancs (Clitocybe phyllophila et surtout les espèces prairiales C. rivulosa/dealbata) sont suspects de teneur en muscarine/toxiques — ils constituent la confusion dangereuse classique des champignons prairiaux à chapeau blanc.","Chapeau du marasme des Oréades jaune cuir-beige avec mamelon central obtus et marge translucide-striée ; clitocybes blancs blanc vitreux pruineux, souvent déprimés/en entonnoir.","Règle de sécurité : sur les stations herbeuses, surveiller en plus les clitocybes blancs des prairies plus dangereux (C. rivulosa/dealbata) — pas seulement C. phyllophila."}',false),
('marasmius_oreades','clitocybe_phyllophila','it','Il gambesecco (marasmio delle Oreadi) è giallo cuoio-beige con umbone e lamelle distanziate, non decorrenti; i clitocybe bianchi sono bianco puro pruinosi, con lamelle fitte e (debolmente) decorrenti.','Il gambesecco ha un odore gradevole speziato (chiodi di garofano/mandorla amara); il clitocybe è ammuffito-dolciastro/profumato — l''odore da solo non è probante.','Il gambesecco cresce in prati, pascoli e tappeti erbosi (spesso in cerchi delle streghe). Clitocybe phyllophila si trova soprattutto nella lettiera di foglie/aghi di boschi, parchi e giardini; invece i clitocybe BIANCHI DEI PRATI realmente pericolosi (C. rivulosa/dealbata) condividono l''habitat erboso del gambesecco.','Gambesecco bianco, clitocybe biancastro anch''esso bianco/crema — il colore delle spore qui NON distingue. Verificare quindi la disposizione delle lamelle (distanziate/non decorrenti) e la tenacia del gambo.','In prato/tappeto erboso prendere solo funghi con gambo tenace-flessibile, che non si spezza, e con lamelle distanziate, NON decorrenti — ogni clitocybe bianco con lamelle decorrenti (sia di bosco sia di prato) si lascia coerentemente sul posto.','{"Gambesecco: lamelle distanziate, pallide, NON decorrenti, gambo tenace-flessibile (si torce senza spezzarsi) — clitocybe biancastro: lamelle fitte e debolmente decorrenti, gambo fragile.","Il gambesecco profuma di speziato-dolciastro (chiodi di garofano/mandorla amara); il clitocybe biancastro è ammuffito-dolciastro/profumato.","I clitocybe bianchi (Clitocybe phyllophila e soprattutto le specie dei prati C. rivulosa/dealbata) sono sospetti di muscarina/tossici — costituiscono la classica confusione pericolosa dei funghi dei prati a cappello bianco.","Cappello del gambesecco giallo cuoio-beige con umbone centrale ottuso e margine traslucido-striato; clitocybe bianchi bianco vitreo pruinoso, spesso depressi/imbutiformi.","Regola di sicurezza: nelle stazioni erbose fare attenzione anche ai più pericolosi clitocybe bianchi dei prati (C. rivulosa/dealbata) — non solo a C. phyllophila."}',false),
('marasmius_oreades','inocybe_geophylla','en','The pure white-silky, sharply umbonate cap surface of the white fibrecap differs from the leather-yellow-brownish, bluntly umbonate fairy ring mushroom.','Fairy ring mushroom: of bitter almond; white fibrecap: spermatic-earthy.','Both at the edges of meadows, paths and woods in short grass; habitat does not separate them, so check gill colour, smell and stem consistency.','Fairy ring mushroom: WHITE spore print; white fibrecap: tobacco-/ochre-brown spore print - a sure separating feature.','Eat small white/light-brown meadow mushrooms only if the spore print stays WHITE; any silky-white cap with brown spore dust and a spermatic smell is a fibrecap - discard.','{"Fairy ring mushroom: gills whitish-cream, thick and distant; white fibrecap: gills whitish when young, soon clay-/tobacco-brown","Fairy ring mushroom: cap leather-yellow-light brown with a blunt umbo; white form of the fibrecap: pure white to cream, silky-fibrous with a pointed umbo","Fairy ring mushroom: stem tough-pliable (bends around the finger); fibrecap: stem brittle, thin","The white fibrecap contains much muscarine (sweating, salivation, watering eyes 15-30 min after eating); the fairy ring mushroom is edible"}',false),
('marasmius_oreades','inocybe_geophylla','es','La superficie del sombrero de un blanco puro-sedoso, con mamelón puntiagudo, del inocibe terrígeno se distingue de la senderuela amarillo cuero-parduzca con mamelón obtuso.','Senderuela: a almendra amarga; inocibe terrígeno: espermático-terroso.','Ambos en los bordes de prados, caminos y bosques en hierba corta; el hábitat no separa, por lo que hay que verificar el color de las láminas, el olor y la consistencia del pie.','Senderuela: esporada BLANCA; inocibe terrígeno: esporada pardo tabaco/ocre - rasgo de separación seguro.','Comer las setas pequeñas blancas/pardo claro de prado solo si la esporada permanece BLANCA; todo sombrero blanco sedoso con polvo de esporas pardo y olor espermático es un inocibe - desechar.','{"Senderuela: láminas blanquecinas-crema, gruesas y espaciadas; inocibe terrígeno: láminas de joven blanquecinas, pronto arcillosas-/pardo tabaco","Senderuela: sombrero amarillo cuero-pardo claro con mamelón obtuso; forma blanca del inocibe: blanco puro a crema, sedoso-fibrilloso con mamelón puntiagudo","Senderuela: pie correoso-flexible (se dobla alrededor del dedo); inocibe: pie quebradizo, delgado","El inocibe terrígeno contiene mucha muscarina (sudoración, salivación, lagrimeo 15-30 min después de comerlo); la senderuela es comestible"}',false),
('marasmius_oreades','inocybe_geophylla','fr','La surface du chapeau d''un blanc pur soyeux, à mamelon pointu, de l''inocybe à feuilles le distingue du marasme des Oréades jaune cuir-brunâtre à mamelon obtus.','Marasme des Oréades : odeur d''amande amère ; inocybe à feuilles : spermatique-terreux.','Tous deux en bordure de prairies, de chemins et de forêts dans l''herbe rase ; l''habitat ne sépare pas, donc vérifier la couleur des lames, l''odeur et la consistance du pied.','Marasme des Oréades : sporée BLANCHE ; inocybe à feuilles : sporée brun tabac/ocre - critère de séparation sûr.','Ne consommer les petits champignons blancs/brun clair des prairies que si la sporée reste BLANCHE ; tout chapeau blanc soyeux à poussière sporale brune et à odeur spermatique est un inocybe - à rejeter.','{"Marasme des Oréades : lames blanchâtres-crème, épaisses et espacées ; inocybe à feuilles : lames jeunes blanchâtres, bientôt argilo-/brun tabac","Marasme des Oréades : chapeau jaune cuir-brun clair à mamelon obtus ; forme blanche de l''inocybe : blanc pur à crème, soyeux-fibrilleux avec mamelon pointu","Marasme des Oréades : pied coriace-souple (se plie autour du doigt) ; inocybe : pied cassant, mince","L''inocybe à feuilles contient beaucoup de muscarine (sueur, salivation, larmoiement 15-30 min après ingestion) ; le marasme des Oréades est comestible"}',false),
('marasmius_oreades','inocybe_geophylla','it','La superficie del cappello bianco puro-setoso, ad umbone appuntito, dell''inocibe terrigeno si distingue dal gambesecco giallo cuoio-brunastro ad umbone ottuso.','Gambesecco: di mandorla amara; inocibe terrigeno: spermatico-terroso.','Entrambi ai margini di prati, sentieri e boschi nell''erba corta; l''habitat non distingue, quindi verificare colore delle lamelle, odore e consistenza del gambo.','Gambesecco: sporata BIANCA; inocibe terrigeno: sporata bruno tabacco/ocra - criterio di separazione sicuro.','Mangiare i piccoli funghi bianchi/bruno chiaro dei prati solo se la sporata resta BIANCA; ogni cappello bianco setoso con polvere sporale bruna e odore spermatico è un inocibe - scartare.','{"Gambesecco: lamelle biancastre-crema, spesse e distanziate; inocibe terrigeno: lamelle da giovani biancastre, presto argillose-/bruno tabacco","Gambesecco: cappello giallo cuoio-bruno chiaro con umbone ottuso; forma bianca dell''inocibe: bianco puro fino a crema, setoso-fibrilloso con umbone appuntito","Gambesecco: gambo tenace-flessibile (si piega attorno al dito); inocibe: gambo fragile, sottile","L''inocibe terrigeno contiene molta muscarina (sudorazione, salivazione, lacrimazione 15-30 min dopo l''ingestione); il gambesecco è commestibile"}',false),
('marasmius_oreades','inocybe_rimosa','en','The fairy ring mushroom''s tough, pliable stem and smooth leather-yellow cap distinguish it from the fissured-conical, brittle fibrecap.','Fairy ring mushroom: pleasant bitter-almond smell; fibrecap: spermatic-unpleasant.','Both in meadows and short grass; the fairy ring mushroom often grows in fairy rings, but habitat does not separate them reliably.','Fairy ring mushroom: WHITE spore print; conical fibrecap: tobacco-/grey-brown spore print - a sure separating feature.','In meadows take only mushrooms with whitish gills, a white spore print and a pliable-tough stem; any fissured, brown-spored, spermatic-smelling cap is a poisonous fibrecap - discard at once.','{"Fairy ring mushroom: gills whitish-cream, thick, distant; fibrecap: gills soon clay-grey-brown, more crowded","Fairy ring mushroom: cap light brown-leather yellow, smooth with a blunt umbo, stem tough-pliable (bends without breaking); fibrecap: cap radially SPLIT, conical, stem brittle","The fairy ring mushroom smells pleasantly of bitter almond; the fibrecap smells spermatic-earthy","Fibrecaps contain muscarine - dangerous in quantity; the fairy ring mushroom is edible (cook thoroughly)"}',false),
('marasmius_oreades','inocybe_rimosa','es','El pie correoso y flexible y el sombrero liso amarillo cuero de la senderuela la distinguen del inocibe fisurado-cónico y quebradizo.','Senderuela: agradable olor a almendra amarga; inocibe: espermático-desagradable.','Ambos en prados y hierba corta; la senderuela crece a menudo en corros de brujas, pero el hábitat no los separa de forma fiable.','Senderuela: esporada BLANCA; inocibe de sombrero cónico: esporada pardo tabaco/gris-parda - rasgo de separación seguro.','En el prado tomar solo setas con láminas blanquecinas, esporada blanca y pie flexible-correoso; todo sombrero fisurado, de esporas pardas, de olor espermático es un inocibe tóxico - desechar de inmediato.','{"Senderuela: láminas blanquecinas-crema, gruesas, espaciadas; inocibe: láminas pronto arcillosas-gris-pardas, más apretadas","Senderuela: sombrero pardo claro-amarillo cuero, liso con mamelón obtuso, pie correoso-flexible (se dobla sin romperse); inocibe: sombrero RASGADO radialmente, cónico, pie quebradizo","La senderuela huele agradablemente a almendra amarga; el inocibe huele a espermático-terroso","Los inocibes contienen muscarina - peligrosos en cantidad; la senderuela es comestible (cocinar bien)"}',false),
('marasmius_oreades','inocybe_rimosa','fr','Le pied coriace et souple et le chapeau lisse jaune cuir du marasme des Oréades le distinguent de l''inocybe fissuré-conique et cassant.','Marasme des Oréades : agréable odeur d''amande amère ; inocybe : spermatique-désagréable.','Tous deux dans les prairies et l''herbe rase ; le marasme des Oréades pousse souvent en ronds de sorcière, mais l''habitat ne les sépare pas de façon fiable.','Marasme des Oréades : sporée BLANCHE ; inocybe à chapeau conique : sporée brun tabac/gris-brun - critère de séparation sûr.','En prairie, ne prendre que des champignons à lames blanchâtres, sporée blanche et pied souple-coriace ; tout chapeau fissuré, à spores brunes, à odeur spermatique est un inocybe toxique - à rejeter aussitôt.','{"Marasme des Oréades : lames blanchâtres-crème, épaisses, espacées ; inocybe : lames bientôt argilo-gris-brun, plus denses","Marasme des Oréades : chapeau brun clair-jaune cuir, lisse à mamelon obtus, pied coriace-souple (se plie sans casser) ; inocybe : chapeau FENDU radialement, conique, pied cassant","Le marasme des Oréades sent agréablement l''amande amère ; l''inocybe sent le spermatique-terreux","Les inocybes contiennent de la muscarine - dangereux en quantité ; le marasme des Oréades est comestible (bien cuire)"}',false),
('marasmius_oreades','inocybe_rimosa','it','Il gambo tenace e flessibile e il cappello liscio giallo cuoio del gambesecco lo distinguono dall''inocibe fessurato-conico e fragile.','Gambesecco: gradevole odore di mandorla amara; inocibe: spermatico-sgradevole.','Entrambi in prati ed erba corta; il gambesecco cresce spesso in cerchi delle streghe, ma l''habitat non li distingue in modo affidabile.','Gambesecco: sporata BIANCA; inocibe a cappello conico: sporata bruno tabacco/grigio-bruna - criterio di separazione sicuro.','In prato prendere solo funghi con lamelle biancastre, sporata bianca e gambo flessibile-tenace; ogni cappello fessurato, a spore brune, dall''odore spermatico è un inocibe tossico - scartare subito.','{"Gambesecco: lamelle biancastre-crema, spesse, distanziate; inocibe: lamelle presto argillose-grigio-brune, più fitte","Gambesecco: cappello bruno chiaro-giallo cuoio, liscio con umbone ottuso, gambo tenace-flessibile (si piega senza spezzarsi); inocibe: cappello FESSURATO radialmente, conico, gambo fragile","Il gambesecco profuma gradevolmente di mandorla amara; l''inocibe profuma di spermatico-terroso","Gli inocibi contengono muscarina - pericolosi in quantità; il gambesecco è commestibile (cuocere bene)"}',false),
('marasmius_oreades','lepiota_cristata','en','Lepiota cristata whitish cap with a red-brown concentric ring of scales, dark centre and stem ring; fairy ring mushroom smooth ochre umbonate cap without scales and without a ring.','Lepiota cristata pungently unpleasant of coal gas/burnt rubber; fairy ring mushroom pleasant of bitter almond/hydrocyanic acid - the coal-gas smell is a clear warning signal.','Both at grassy spots, path edges, in parks and on meadows - the same habitat favours the confusion.','Both white (in Lepiota cristata occasionally minimally cream-coloured) spore print - no reliable separating feature.','As a matter of principle leave small ringed dapperlings standing in meadows; the ringless, tough, twistable stem is the only reliable feature of the fairy ring mushroom - if it is missing, do not collect.','{"Lepiota cristata is poisonous (gastrointestinal upset; in this genus every small dapperling is regarded as amatoxin-suspect); the fairy ring mushroom is edible","Lepiota cristata smells unpleasantly pungent of coal gas/burnt rubber; the fairy ring mushroom smells pleasantly of bitter almond/hydrocyanic acid to sweetish","Lepiota cristata has a (fleeting) ring and a brittle stem; the fairy ring mushroom has NO ring and a tough, pliable stem","Lepiota cristata: whitish cap with red-brown concentrically arranged scales and a small dark disc in the centre; fairy ring mushroom: smooth ochre- to buff-coloured umbonate cap without scales","Lepiota cristata with crowded, free, white gills; fairy ring mushroom with thick, widely spaced, emarginate-adnate gills"}',false),
('marasmius_oreades','lepiota_cristata','es','Lepiota cristata: sombrero blanquecino con una corona de escamas concéntricas pardo-rojas, centro oscuro y anillo en el pie; senderuela: sombrero liso ocre con mamelón, sin escamas y sin anillo.','Lepiota cristata: olor acre desagradable a gas de alumbrado/goma quemada; senderuela: agradable a almendra amarga/ácido cianhídrico - el olor a gas de alumbrado es una clara señal de alarma.','Ambos en lugares herbosos, bordes de caminos, parques y prados - el mismo hábitat favorece la confusión.','Ambos con esporada blanca (en Lepiota cristata ocasionalmente mínimamente color crema) - ningún rasgo de separación fiable.','Por principio dejar en su sitio en el prado las lepiotas pequeñas con anillo; el pie sin anillo, correoso y retorcible es el único rasgo fiable de la senderuela - si falta, no recolectar.','{"Lepiota cristata es tóxica (trastornos gastrointestinales; en este género toda lepiota pequeña se considera sospechosa de amatoxinas); la senderuela es comestible","Lepiota cristata huele desagradablemente acre a gas de alumbrado/goma quemada; la senderuela huele agradablemente a almendra amarga/ácido cianhídrico hasta dulzón","Lepiota cristata tiene un anillo (fugaz) y un pie quebradizo; la senderuela NO tiene anillo y tiene un pie correoso, flexible","Lepiota cristata: sombrero blanquecino con escamas pardo-rojas dispuestas concéntricamente y un pequeño disco oscuro en el centro; senderuela: sombrero con mamelón liso ocre hasta color pan sin escamas","Lepiota cristata con láminas apretadas, libres, blancas; senderuela con láminas gruesas, espaciadas, escotado-adnadas"}',false),
('marasmius_oreades','lepiota_cristata','fr','Lepiota cristata : chapeau blanchâtre à couronne de squames concentriques brun-rouge, centre sombre et anneau au pied ; marasme des Oréades : chapeau lisse ocre à mamelon, sans squames et sans anneau.','Lepiota cristata : odeur âcre désagréable de gaz d''éclairage/caoutchouc brûlé ; marasme des Oréades : agréable odeur d''amande amère/acide cyanhydrique - l''odeur de gaz d''éclairage est un signal d''alarme net.','Tous deux dans les endroits herbeux, bords de chemins, parcs et prairies - le même habitat favorise la confusion.','Tous deux à sporée blanche (parfois minimalement crème chez Lepiota cristata) - pas de critère de séparation fiable.','Par principe, laisser sur place en prairie les petites lépiotes annelées ; le pied sans anneau, coriace et torsadable est le seul critère fiable du marasme des Oréades - s''il manque, ne pas ramasser.','{"Lepiota cristata est toxique (troubles gastro-intestinaux ; dans ce genre, toute petite lépiote est considérée comme suspecte d''amatoxines) ; le marasme des Oréades est comestible","Lepiota cristata sent désagréablement âcre le gaz d''éclairage/caoutchouc brûlé ; le marasme des Oréades sent agréablement l''amande amère/acide cyanhydrique à douceâtre","Lepiota cristata a un anneau (fugace) et un pied cassant ; le marasme des Oréades n''a PAS d''anneau et a un pied coriace, souple","Lepiota cristata : chapeau blanchâtre à squames brun-rouge disposées concentriquement et petit disque sombre au centre ; marasme des Oréades : chapeau à mamelon lisse ocre à couleur pain sans squames","Lepiota cristata à lames serrées, libres, blanches ; marasme des Oréades à lames épaisses, espacées, échancrées-adnées"}',false),
('marasmius_oreades','lepiota_cristata','it','Lepiota cristata: cappello biancastro con corona di squame concentriche bruno-rosse, centro scuro e anello al gambo; gambesecco: cappello liscio ocra con umbone, senza squame e senza anello.','Lepiota cristata: odore acre sgradevole di gas illuminante/gomma bruciata; gambesecco: gradevole di mandorla amara/acido cianidrico - l''odore di gas illuminante è un chiaro segnale d''allarme.','Entrambi in luoghi erbosi, bordi di sentieri, parchi e prati - lo stesso habitat favorisce la confusione.','Entrambi con sporata bianca (in Lepiota cristata occasionalmente minimamente color crema) - nessun criterio di separazione affidabile.','Per principio lasciare sul posto in prato le piccole lepiote con anello; il gambo senza anello, tenace e torcibile è l''unico criterio affidabile del gambesecco - se manca, non raccogliere.','{"Lepiota cristata è tossica (disturbi gastro-intestinali; nel genere ogni piccola lepiota è considerata sospetta di amatossine); il gambesecco è commestibile","Lepiota cristata odora sgradevolmente acre di gas illuminante/gomma bruciata; il gambesecco odora gradevolmente di mandorla amara/acido cianidrico fino a dolciastro","Lepiota cristata ha un anello (fugace) e un gambo fragile; il gambesecco NON ha anello e ha un gambo tenace, flessibile","Lepiota cristata: cappello biancastro con squame bruno-rosse disposte concentricamente e piccolo disco scuro al centro; gambesecco: cappello con umbone liscio ocra fino a color pane senza squame","Lepiota cristata con lamelle fitte, libere, bianche; gambesecco con lamelle spesse, distanziate, smarginato-adnate"}',false),
('marasmius_oreades','lepiota_helveola','en','Fairy ring mushroom smooth ochre umbonate cap, ringless tough stem, thick widely spaced gills; Lepiota helveola finely scaly flesh-pinkish cap with a stem ring and crowded free gills.','The fairy ring mushroom smells pleasantly of hydrocyanic acid/bitter almond to sweetish (HCN + benzaldehyde, not perceptible to about a quarter of people); small poisonous dapperlings smell inconspicuous to slightly unpleasant - smell is NOT a sure separating feature.','Both on meadows, lawns, pastures and in parks - identical habitat, which is exactly what makes the confusion so dangerous.','Fairy ring mushroom white spore print, Lepiota helveola likewise white - no separating feature; watch for the ring, free gills and brittle stem.','NEVER eat small dapperlings (Lepiota) with a cap under about 8 cm - several species are deadly. In meadows do not collect any small, ringed, brittle mushroom; when in doubt leave it entirely standing.','{"Lepiota helveola is DEADLY poisonous (amatoxins -> liver failure); the fairy ring mushroom is a good edible - the confusion can end fatally","The fairy ring mushroom has a strikingly tough, pliable-elastic, solid stem (twists without breaking); small poisonous dapperlings have a fragile, easily breaking stem","Lepiota helveola has an (often fleeting) membranous ring on the stem; the fairy ring mushroom NEVER has a ring","The fairy ring mushroom has thick, widely spaced, emarginate-adnate, cream-coloured gills; Lepiota helveola crowded, free, white gills","Lepiota helveola: finely scaly flesh-pink to brownish-red cap with a darker centre; fairy ring mushroom: smooth ochre- to buff-coloured cap with a blunt umbo"}',false),
('marasmius_oreades','lepiota_helveola','es','Senderuela: sombrero liso ocre con mamelón, pie correoso sin anillo, láminas gruesas espaciadas; Lepiota helveola: sombrero finamente escamoso pardo-rosado carne con anillo en el pie y láminas libres apretadas.','La senderuela huele agradablemente a ácido cianhídrico/almendra amarga hasta dulzón (HCN + benzaldehído, no perceptible para alrededor de un cuarto de las personas); las pequeñas lepiotas tóxicas huelen discreto hasta ligeramente desagradable - el olor NO es un rasgo de separación seguro.','Ambos en prados, céspedes, pastos y parques - hábitat idéntico, justamente esto hace la confusión tan peligrosa.','Senderuela esporada blanca, Lepiota helveola también blanca - ningún rasgo de separación; vigilar el anillo, las láminas libres y el pie quebradizo.','NUNCA comer lepiotas pequeñas (Lepiota) con sombrero de menos de unos 8 cm - varias especies son mortales. En el prado no recolectar ninguna seta pequeña, con anillo y quebradiza; en caso de duda dejarla completamente en su sitio.','{"Lepiota helveola es MORTALMENTE tóxica (amatoxinas -> insuficiencia hepática); la senderuela es un buen comestible - la confusión puede acabar de forma mortal","La senderuela tiene un pie llamativamente correoso, flexible-elástico, lleno (se retuerce sin romperse); las pequeñas lepiotas tóxicas tienen un pie frágil, que se rompe fácilmente","Lepiota helveola posee un anillo membranoso (a menudo fugaz) en el pie; la senderuela NUNCA tiene anillo","La senderuela tiene láminas gruesas, espaciadas, escotado-adnadas al pie, de color crema; Lepiota helveola láminas apretadas, libres, blancas","Lepiota helveola: sombrero finamente escamoso pardo-rosado carne hasta pardo-rojizo con centro más oscuro; senderuela: sombrero liso ocre hasta color pan con mamelón obtuso"}',false),
('marasmius_oreades','lepiota_helveola','fr','Marasme des Oréades : chapeau lisse ocre à mamelon, pied coriace sans anneau, lames épaisses espacées ; Lepiota helveola : chapeau finement squameux brun-rosé chair avec anneau au pied et lames libres serrées.','Le marasme des Oréades sent agréablement l''acide cyanhydrique/amande amère à douceâtre (HCN + benzaldéhyde, non perçu par environ un quart des gens) ; les petites lépiotes toxiques ont une odeur discrète à légèrement désagréable - l''odeur n''est PAS un critère de séparation sûr.','Tous deux dans les prairies, pelouses, pâturages et parcs - habitat identique, c''est précisément ce qui rend la confusion si dangereuse.','Marasme des Oréades sporée blanche, Lepiota helveola également blanche - pas de critère de séparation ; surveiller l''anneau, les lames libres et le pied cassant.','Ne JAMAIS manger les petites lépiotes (Lepiota) à chapeau de moins de 8 cm environ - plusieurs espèces sont mortelles. En prairie, ne ramasser aucun petit champignon annelé et cassant ; au moindre doute, laisser entièrement sur place.','{"Lepiota helveola est MORTELLEMENT toxique (amatoxines -> insuffisance hépatique) ; le marasme des Oréades est un bon comestible - la confusion peut être mortelle","Le marasme des Oréades a un pied remarquablement coriace, souple-élastique, plein (se tord sans casser) ; les petites lépiotes toxiques ont un pied fragile, cassant facilement","Lepiota helveola possède un anneau membraneux (souvent fugace) au pied ; le marasme des Oréades n''a JAMAIS d''anneau","Le marasme des Oréades a des lames épaisses, espacées, échancrées-adnées au pied, couleur crème ; Lepiota helveola des lames serrées, libres, blanches","Lepiota helveola : chapeau finement squameux brun-rosé chair à brun-rougeâtre avec centre plus foncé ; marasme des Oréades : chapeau lisse ocre à couleur pain avec mamelon obtus"}',false),
('marasmius_oreades','lepiota_helveola','it','Gambesecco: cappello liscio ocra con umbone, gambo tenace senza anello, lamelle spesse distanziate; Lepiota helveola: cappello finemente squamoso bruno-rosato carne con anello al gambo e lamelle libere fitte.','Il gambesecco profuma gradevolmente di acido cianidrico/mandorla amara fino a dolciastro (HCN + benzaldeide, non percepito da circa un quarto delle persone); le piccole lepiote tossiche hanno odore insignificante fino a leggermente sgradevole - l''odore NON è un criterio di separazione sicuro.','Entrambi in prati, tappeti erbosi, pascoli e parchi - habitat identico, proprio questo rende la confusione così pericolosa.','Gambesecco sporata bianca, Lepiota helveola anch''essa bianca - nessun criterio di separazione; fare attenzione all''anello, alle lamelle libere e al gambo fragile.','Non mangiare MAI le piccole lepiote (Lepiota) con cappello sotto i circa 8 cm - diverse specie sono mortali. In prato non raccogliere alcun fungo piccolo, anellato e fragile; nel dubbio lasciare completamente sul posto.','{"Lepiota helveola è MORTALMENTE tossica (amatossine -> insufficienza epatica); il gambesecco è un buon commestibile - la confusione può finire in modo mortale","Il gambesecco ha un gambo notevolmente tenace, flessibile-elastico, pieno (si torce senza spezzarsi); le piccole lepiote tossiche hanno un gambo fragile, che si spezza facilmente","Lepiota helveola possiede un anello membranoso (spesso fugace) al gambo; il gambesecco non ha MAI un anello","Il gambesecco ha lamelle spesse, distanziate, smarginato-adnate al gambo, color crema; Lepiota helveola lamelle fitte, libere, bianche","Lepiota helveola: cappello finemente squamoso bruno-rosato carne fino a bruno-rossastro con centro più scuro; gambesecco: cappello liscio ocra fino a color pane con umbone ottuso"}',false),
('morchelchampignon','verpa_bohemica','en','Common morel: deeply pitted cap, fully fused to the stem; verpa: smooth-wrinkled, freely hanging thimble-like cap.','Both with a discreet pleasant mushroomy smell — smell does NOT help to tell them apart here, only structure and a cut do.','Both in spring; Verpa bohemica often somewhat earlier under ash/poplar in floodplain forests.',NULL,'Always cut lengthwise: if the cap is attached only at the tip and otherwise hangs free, it is NOT a true morel — and never eat it raw.','{"In the common morel the cap is fused to the stem over its entire length (a completely hollow unit); in the verpa the cap hangs free like a bell and is attached only at the very top, at the stem tip","The common morel''s cap shows deep honeycomb-like pits; Verpa bohemica has only longitudinal/transverse brain-like folds without true pits","The lengthwise cut is decisive: the common morel is hollow throughout from cap to stem base; the verpa''s stem is filled/chambered with a cottony-flaky interior","Both should be eaten only well cooked and never raw — Verpa bohemica is gastrointestinally toxic raw or insufficiently cooked"}',false),
('morchelchampignon','verpa_bohemica','es','Colmenilla común: sombrero profundamente alveolado, totalmente soldado al pie; verpa: sombrerillo liso-rugoso en forma de dedal, colgante libremente.','Ambas con olor fúngico-agradable discreto — el olor NO ayuda aquí a distinguirlas, solo la estructura y el corte lo permiten.','Ambas en primavera; Verpa bohemica a menudo algo antes bajo fresnos/álamos en bosques de ribera.',NULL,'Cortar siempre a lo largo: si el sombrerillo está unido solo en la punta y por lo demás cuelga libre, NO es una colmenilla verdadera — y nunca consumirla cruda.','{"En la colmenilla común el sombrero está soldado al pie en toda su longitud (unidad totalmente hueca); en la verpa el sombrerillo cuelga libre en forma de campana y solo está unido arriba del todo, en la punta del pie","El sombrero de la colmenilla común muestra alvéolos profundos en panal; Verpa bohemica solo tiene pliegues longitudinales/transversales cerebriformes sin verdaderos alvéolos","El corte longitudinal es decisivo: la colmenilla común es hueca de forma continua del sombrero a la base del pie; el pie de la verpa está relleno/tabicado internamente de modo algodonoso-flocoso","Ambas solo se comen bien cocinadas y nunca crudas — Verpa bohemica es gastrointestinalmente tóxica cruda o insuficientemente cocida"}',false),
('morchelchampignon','verpa_bohemica','fr','Morille commune : chapeau profondément alvéolé, entièrement soudé au pied ; verpe : chapeau lisse-ridé en forme de dé à coudre, librement pendant.','Toutes deux d''une odeur fongique-agréable discrète — l''odeur n''aide PAS ici à les distinguer, seuls la structure et la coupe le permettent.','Toutes deux au printemps ; Verpa bohemica souvent un peu plus tôt sous les frênes/peupliers en forêts alluviales.',NULL,'Toujours couper en long : si le chapeau n''est soudé qu''à son sommet et pend librement par ailleurs, ce n''est PAS une vraie morille — et ne jamais la consommer crue.','{"Chez la morille commune, le chapeau est soudé au pied sur toute sa longueur (unité entièrement creuse) ; chez la verpe, le chapeau pend librement en cloche et n''est soudé qu''tout en haut, à la pointe du pied","Le chapeau de la morille commune présente des alvéoles profondes en nid d''abeille ; Verpa bohemica n''a que des plis longitudinaux/transversaux cérébriformes sans véritables alvéoles","La coupe longitudinale tranche : la morille commune est entièrement creuse du chapeau jusqu''à la base du pied ; le pied de la verpe est rempli/cloisonné de manière cotonneuse-floconneuse à l''intérieur","Toutes deux ne se mangent que bien cuites et jamais crues — Verpa bohemica est toxique pour l''estomac et les intestins crue ou insuffisamment cuite"}',false),
('morchelchampignon','verpa_bohemica','it','Spugnola comune: cappello profondamente alveolato, completamente saldato al gambo; verpa: cappellino liscio-rugoso a forma di ditale, liberamente pendente.','Entrambe con odore fungino-gradevole discreto — l''odore NON aiuta qui a distinguerle, solo la struttura e il taglio lo permettono.','Entrambe in primavera; Verpa bohemica spesso un po'' prima sotto frassini/pioppi nei boschi ripariali.',NULL,'Tagliare sempre per il lungo: se il cappellino è attaccato solo all''apice e per il resto pende libero, NON è una vera spugnola — e non consumarla mai cruda.','{"Nella spugnola comune il cappello è saldato al gambo per tutta la lunghezza (unità completamente cava); nella verpa il cappellino pende libero a campana ed è attaccato solo in cima, alla punta del gambo","Il cappello della spugnola comune mostra profonde depressioni alveolate a nido d''ape; Verpa bohemica ha solo pieghe longitudinali/trasversali cerebriformi senza vere alveolature","Il taglio longitudinale è decisivo: la spugnola comune è cava in modo continuo dal cappello alla base del gambo; il gambo della verpa è riempito/camerato internamente in modo cotonoso-floccoso","Entrambe si mangiano solo ben cotte e mai crude — Verpa bohemica è gastro-intestinale-tossica cruda o cotta insufficientemente"}',false),
('morchella_elata','verpa_bohemica','en','Black morel: conical-pointed pitted cap, fully fused; verpa: rounded-blunt wrinkled cap, freely hanging.',NULL,'Black morel on wood chips/burn sites/in gardens; Verpa bohemica rather in moist floodplain forests under ash/poplar.',NULL,'Lengthwise-cut rule: it is a true morel only if the cap is fused to the stem over its entire length and is hollow throughout.','{"The black morel has a conical-pointed, longitudinally ribbed cap fully fused to the stem with true honeycomb chambers; Verpa bohemica bears a rounded cap attached only at the tip, hanging freely","The black morel is hollow over its whole height (cap + stem a single chamber); the verpa''s stem is filled inside in a cottony-flaky manner","The black morel''s cap surface is net-like-pitted with longitudinal ribs; the verpa is only irregularly brain-like wrinkled","Verpa bohemica raw/insufficiently cooked is gastrointestinally toxic — like all morels, enjoy only well cooked"}',false),
('morchella_elata','verpa_bohemica','es','Colmenilla cónica: sombrero alveolado cónico-puntiagudo, totalmente soldado; verpa: sombrerillo rugoso redondeado-obtuso, colgante libremente.',NULL,'Colmenilla cónica sobre virutas de madera/zonas quemadas/en jardines; Verpa bohemica más bien en bosques de ribera húmedos bajo fresno/álamo.',NULL,'Regla del corte longitudinal: solo es una colmenilla verdadera si el sombrero está soldado al pie en toda su longitud y es hueco de extremo a extremo.','{"La colmenilla cónica tiene un sombrero cónico-puntiagudo, costillado longitudinalmente y totalmente soldado al pie con verdaderas cámaras alveolares; Verpa bohemica lleva un sombrerillo redondeado, unido solo en la punta, colgante libremente","La colmenilla cónica es hueca en toda su altura (sombrero + pie una sola cámara); el pie de la verpa está relleno internamente de modo algodonoso-flocoso","La superficie del sombrero de la colmenilla cónica es reticulado-alveolada con costillas longitudinales; la verpa solo está rugosa irregularmente de modo cerebriforme","Verpa bohemica cruda/insuficientemente cocida es gastrointestinalmente tóxica — como todas las colmenillas, disfrutar solo bien cocida"}',false),
('morchella_elata','verpa_bohemica','fr','Morille conique : chapeau alvéolé conique-pointu, entièrement soudé ; verpe : chapeau ridé arrondi-obtus, librement pendant.',NULL,'Morille conique sur copeaux de bois/zones brûlées/dans les jardins ; Verpa bohemica plutôt en forêts alluviales humides sous frêne/peuplier.',NULL,'Règle de la coupe longitudinale : ce n''est une vraie morille que si le chapeau est soudé au pied sur toute sa longueur et est creux de bout en bout.','{"La morille conique a un chapeau conique-pointu, côtelé longitudinalement et entièrement soudé au pied, avec de vraies alvéoles ; Verpa bohemica porte un chapeau arrondi, soudé seulement au sommet, librement pendant","La morille conique est creuse sur toute sa hauteur (chapeau + pied une seule cavité) ; le pied de la verpe est rempli à l''intérieur de manière cotonneuse-floconneuse","La surface du chapeau de la morille conique est réticulée-alvéolée avec des côtes longitudinales ; la verpe est seulement ridée irrégulièrement de façon cérébriforme","Verpa bohemica crue/insuffisamment cuite est toxique pour l''estomac et les intestins — comme toutes les morilles, à déguster uniquement bien cuite"}',false),
('morchella_elata','verpa_bohemica','it','Spugnola conica: cappello alveolato conico-appuntito, completamente saldato; verpa: cappellino rugoso arrotondato-ottuso, liberamente pendente.',NULL,'Spugnola conica su cippato/aree bruciate/nei giardini; Verpa bohemica piuttosto in boschi ripariali umidi sotto frassino/pioppo.',NULL,'Regola del taglio longitudinale: è una vera spugnola solo se il cappello è saldato al gambo per tutta la lunghezza ed è cavo per intero.','{"La spugnola conica ha un cappello conico-appuntito, costolato longitudinalmente e completamente saldato al gambo con vere camere alveolari; Verpa bohemica porta un cappellino arrotondato, attaccato solo all''apice, liberamente pendente","La spugnola conica è cava per tutta l''altezza (cappello + gambo una sola camera); il gambo della verpa è riempito internamente in modo cotonoso-floccoso","La superficie del cappello della spugnola conica è reticolato-alveolata con coste longitudinali; la verpa è solo irregolarmente rugosa in modo cerebriforme","Verpa bohemica cruda/cotta insufficientemente è gastro-intestinale-tossica — come tutte le spugnole, da gustare solo ben cotta"}',false),
('parasol','lepiota_brunneoincarnata','en','The parasol mushroom is large with a distinctly snakeskin-patterned stem and a double movable ring; the deadly dapperling stays small (under 5 cm) with a flesh-pink-brown, finely scaly cap surface and an unpatterned stem.','The parasol smells mild-nutty; the poisonous dapperling sweetish-fruity - smell is NOT a sure separating feature, never rely on it.','Parasol at forest edges/meadows; the poisonous dapperling in warm, sandy-grassy spots, parks and path edges - overlap possible.','Both have a WHITE spore print - the spore print does NOT separate them, so size, stem patterning and the double movable ring must absolutely be checked.','Accept a dapperling as a parasol only if the cap clearly exceeds 10 cm AND the stem is snakeskin-patterned AND the ring is double and movable - as a matter of principle NEVER eat small dapperlings under 8-10 cm.','{"The parasol is large: cap 10-30 cm; the flesh-pink dapperling is small: cap only 2-5 cm - SIZE is the first warning signal","The parasol has a DOUBLE, freely movable ring on the stem; the poisonous dapperling has only a fleeting, fibrous, NON-movable ring zone","Parasol stem distinctly snakeskin-patterned (snakeskin-like banded); poisonous dapperling stem with flesh-brown fibrous scale belts, without snakeskin pattern","Parasol cap with large, coarse brown scales on a pale ground + umbo; poisonous dapperling cap finely flesh-brown-pink scaly, small","The flesh-pink dapperling contains amatoxins (like the death cap) - deadly, even a small amount damages the liver irreversibly"}',false),
('parasol','lepiota_brunneoincarnata','es','La galamperna (parasol) es grande con pie claramente jaspeado (piel de serpiente) y anillo doble deslizante; la lepiota mortal permanece pequeña (menos de 5 cm) con superficie del sombrero pardo-rosa carne finamente escamosa y pie no jaspeado.','El parasol huele suave a nuez; la lepiota tóxica dulzón-afrutado - el olor NO es un rasgo de separación seguro, no fiarse nunca de él.','Parasol en bordes de bosque/prados; la lepiota tóxica en lugares cálidos, arenoso-herbosos, parques y bordes de caminos - solapamiento posible.','Ambos tienen esporada BLANCA - la esporada NO los separa, por lo que es imprescindible verificar el tamaño, el jaspeado del pie y el anillo doble deslizante.','Aceptar una lepiota como parasol solo si el sombrero mide claramente más de 10 cm Y el pie está jaspeado Y el anillo es doble y deslizante - por principio NUNCA comer lepiotas pequeñas de menos de 8-10 cm.','{"El parasol es grande: sombrero 10-30 cm; la lepiota pardo-rosada es pequeña: sombrero solo 2-5 cm - el TAMAÑO es la primera señal de alarma","El parasol tiene un anillo DOBLE, libremente deslizante en el pie; la lepiota tóxica solo tiene una zona anular fugaz, fibrosa, NO deslizante","Pie del parasol claramente jaspeado (bandeado como piel de serpiente); pie de la lepiota tóxica con cinturones de escamas pardo-carne fibrosas, sin jaspeado","Sombrero del parasol con escamas pardas grandes y bastas sobre fondo claro + mamelón; sombrero de la lepiota tóxica finamente escamoso pardo-rosa carne, pequeño","La lepiota pardo-rosada contiene amatoxinas (como la oronja verde/Amanita phalloides) - mortal, ya una pequeña cantidad daña el hígado de forma irreversible"}',false),
('parasol','lepiota_brunneoincarnata','fr','La lépiote élevée (parasol) est grande, à pied nettement chiné et anneau double coulissant ; la lépiote mortelle reste petite (moins de 5 cm) avec une surface du chapeau brun-rose chair finement squameuse et un pied non chiné.','Le parasol sent l''odeur douce de noisette ; la lépiote toxique douceâtre-fruitée - l''odeur n''est PAS un critère de séparation sûr, ne jamais s''y fier.','Parasol en lisière de forêt/prairies ; la lépiote toxique dans les endroits chauds, sablo-herbeux, parcs et bords de chemins - chevauchement possible.','Tous deux ont une sporée BLANCHE - la sporée ne les sépare PAS, il faut donc impérativement vérifier la taille, le chinage du pied et l''anneau double coulissant.','N''accepter une lépiote comme parasol que si le chapeau mesure nettement plus de 10 cm ET que le pied est chiné ET que l''anneau est double et coulissant - ne JAMAIS manger par principe les petites lépiotes de moins de 8-10 cm.','{"Le parasol est grand : chapeau 10-30 cm ; la lépiote brun-incarnat est petite : chapeau seulement 2-5 cm - la TAILLE est le premier signal d''alarme","Le parasol a un anneau DOUBLE, librement coulissant sur le pied ; la lépiote toxique n''a qu''une zone annulaire fugace, fibreuse, NON coulissante","Pied du parasol nettement chiné (bandé comme une peau de serpent) ; pied de la lépiote toxique à ceintures de squames brun-chair fibreuses, sans chinage","Chapeau du parasol à grandes squames brunes grossières sur fond clair + mamelon ; chapeau de la lépiote toxique finement squameux brun-rose chair, petit","La lépiote brun-incarnat contient des amatoxines (comme l''amanite phalloïde) - mortelle, une petite quantité suffit à léser le foie de façon irréversible"}',false),
('parasol','lepiota_brunneoincarnata','it','La mazza di tamburo (parasol) è grande con gambo nettamente zebrato e anello doppio scorrevole; la lepiota mortale resta piccola (sotto i 5 cm) con superficie del cappello bruno-rosa carne finemente squamosa e gambo non zebrato.','Il parasol odora di nocciola dolce; la lepiota tossica dolciastro-fruttato - l''odore NON è un criterio di separazione sicuro, non fidarsene mai.','Parasol ai margini dei boschi/prati; la lepiota tossica in luoghi caldi, sabbioso-erbosi, parchi e bordi di sentieri - sovrapposizione possibile.','Entrambi hanno sporata BIANCA - la sporata NON li distingue, quindi verificare obbligatoriamente la dimensione, la zebratura del gambo e l''anello doppio scorrevole.','Accettare una lepiota come parasol solo se il cappello misura nettamente più di 10 cm E il gambo è zebrato E l''anello è doppio e scorrevole - per principio non mangiare MAI le piccole lepiote sotto gli 8-10 cm.','{"Il parasol è grande: cappello 10-30 cm; la lepiota bruno-incarnata è piccola: cappello solo 2-5 cm - la DIMENSIONE è il primo segnale d''allarme","Il parasol ha un anello DOPPIO, liberamente scorrevole sul gambo; la lepiota tossica ha solo una zona anulare fugace, fibrosa, NON scorrevole","Gambo del parasol nettamente zebrato (fasciato come pelle di serpente); gambo della lepiota tossica con cinture di squame bruno-carne fibrose, senza zebratura","Cappello del parasol con grandi squame brune grossolane su fondo chiaro + umbone; cappello della lepiota tossica finemente squamoso bruno-rosa carne, piccolo","La lepiota bruno-incarnata contiene amatossine (come l''amanita falloide) - mortale, già una piccola quantità danneggia il fegato in modo irreversibile"}',false),
('russula_paludosa','russula_queletii','en','Tall russula (apple brittlegill) bright blood-red/orange-red with an almost white stem; primrose brittlegill a darker purple-violet with a violet-flushed stem.','Primrose brittlegill smells fruity like gooseberry compote; tall russula is low in odour.','Tall russula often in damp spots/bog edges under pine/spruce; primrose brittlegill prefers spruce on lime.','Tall russula has an ochre-yellow spore print, primrose brittlegill a cream-yellow one.','Only eat russulas that stay completely mild after 30 s of chewing - lasting acridity means poisonous.','{"The primrose brittlegill tastes persistently EXTREMELY acrid; the tall russula is mild or only slightly acrid at first and turns mild (brittlegill rule).","The tall russula has a blood-red/orange-red/copper-red cap; the primrose brittlegill a darker purple-violet-red.","Tall russula stem white, often faintly flushed pink; primrose brittlegill stem distinctly flushed violet-purple.","The primrose brittlegill smells fruity of gooseberry compote; the tall russula is inconspicuous.","Both under conifers (spruce/pine) - taste is the safety criterion."}',false),
('russula_paludosa','russula_queletii','es','Rúsula de las turberas rojo sangre/anaranjado vivo con pie casi blanco; rúsula de Quélet de un púrpura-violeta más oscuro con pie teñido de violeta.','Rúsula de Quélet con olor afrutado a compota de grosella espinosa; rúsula de las turberas poco olorosa.','Rúsula de las turberas a menudo en lugares húmedos/bordes de turberas bajo pino/abeto rojo; rúsula de Quélet prefiere el abeto rojo sobre cal.','Esporada amarillo ocre en la rúsula de las turberas, amarillo crema en la rúsula de Quélet.','Comer solo las rúsulas que permanecen completamente suaves tras 30 s de masticación - un picor persistente significa venenosa.','{"La rúsula de Quélet sabe de forma duradera EXTREMADAMENTE picante; la rúsula de las turberas es suave o solo ligeramente picante al principio y se vuelve suave (regla de las rúsulas).","La rúsula de las turberas tiene sombrero rojo sangre/rojo anaranjado/rojo cobrizo; la rúsula de Quélet de un rojo púrpura-violeta más oscuro.","Pie de la rúsula de las turberas blanco, a menudo débilmente teñido de rosa; pie de la rúsula de Quélet claramente teñido de violeta-púrpura.","La rúsula de Quélet huele afrutado a compota de grosella espinosa; la rúsula de las turberas es poco llamativa.","Ambas bajo coníferas (abeto rojo/pino) - el sabor es el criterio de seguridad."}',false),
('russula_paludosa','russula_queletii','fr','Russule des marais rouge sang/orangé vif avec un pied presque blanc ; russule de Quélet d''un pourpre-violet plus sombre avec un pied lavé de violet.','Russule de Quélet à odeur fruitée de compote de groseille à maquereau ; russule des marais peu odorante.','Russule des marais souvent dans les endroits humides/bordures de tourbières sous pin/épicéa ; russule de Quélet préfère l''épicéa sur calcaire.','Sporée jaune ocre pour la russule des marais, jaune crème pour la russule de Quélet.','Ne consommer que les russules qui restent entièrement douces après 30 s de mastication - une âcreté persistante signifie toxique.','{"La russule de Quélet a un goût durablement EXTRÊMEMENT âcre ; la russule des marais est douce ou seulement légèrement âcre au début puis devient douce (règle des russules).","La russule des marais a un chapeau rouge sang/rouge orangé/rouge cuivré ; la russule de Quélet d''un rouge pourpre-violet plus sombre.","Pied de la russule des marais blanc, souvent faiblement teinté de rose ; pied de la russule de Quélet nettement lavé de violet-pourpre.","La russule de Quélet sent le fruité de compote de groseille à maquereau ; la russule des marais est discrète.","Les deux sous conifères (épicéa/pin) - le goût est le critère de sécurité."}',false),
('russula_paludosa','russula_queletii','it','Russula delle paludi rosso sangue/arancio vivo con gambo quasi bianco; russula di Quélet di un porpora-violetto più scuro con gambo soffuso di violetto.','Russula di Quélet con odore fruttato di composta di uva spina; russula delle paludi poco odorosa.','Russula delle paludi spesso in luoghi umidi/bordi di torbiere sotto pino/abete rosso; russula di Quélet predilige l''abete rosso su calcare.','Sporata giallo ocra per la russula delle paludi, giallo crema per la russula di Quélet.','Mangiare solo le russule che restano completamente miti dopo 30 s di masticazione - una piccantezza persistente significa velenosa.','{"La russula di Quélet ha sapore durevolmente ESTREMAMENTE piccante; la russula delle paludi è mite o solo leggermente piccante all''inizio e poi diventa mite (regola delle russule).","La russula delle paludi ha cappello rosso sangue/rosso arancio/rosso ramato; la russula di Quélet di un rosso porpora-violetto più scuro.","Gambo della russula delle paludi bianco, spesso debolmente soffuso di rosa; gambo della russula di Quélet nettamente soffuso di violetto-porpora.","La russula di Quélet odora di fruttato di composta di uva spina; la russula delle paludi è inappariscente.","Entrambe sotto conifere (abete rosso/pino) - il gusto è il criterio di sicurezza."}',false),
('russula_paludosa','russula_sardonia','en','Strikingly lemon-yellow gills and a violet stem in the primrose/sardonia (dark-purple) russula; tall russula with cream gills and a white stem.','Sardonia russula faintly fruity; tall russula low in odour - smell hardly separates, taste all the more.','Both under pine on acidic soils - habitat does not separate them.','Sardonia russula has a cream spore print, tall russula an ochre-yellow one.','Lemon-yellow gills under a violet cap plus acrid taste = poisonous, leave it standing, never confuse with the mild tall russula.','{"The sardonia russula tastes very acrid (one of the most acrid); the tall russula turns mild (brittlegill rule: acrid = poisonous).","The sardonia russula has bright LEMON-YELLOW gills; the tall russula cream-white to ochre-yellow gills.","The sardonia russula has a purple-violet-blackish cap and a violet stem; the tall russula a blood-red/orange-red cap with an almost white stem.","In damp weather the sardonia russula weeps droplets on the gills (''weeping russula''); the tall russula does not.","Both under pine/spruce - only taste and gill colour separate them reliably."}',false),
('russula_paludosa','russula_sardonia','es','Láminas de un amarillo limón llamativo y pie violeta en la rúsula sardonia; rúsula de las turberas con láminas crema y pie blanco.','Rúsula sardonia débilmente afrutada; rúsula de las turberas poco olorosa - el olor apenas distingue, el sabor mucho más.','Ambas bajo pino en suelos ácidos - el hábitat no distingue.','Esporada crema en la rúsula sardonia, amarillo ocre en la rúsula de las turberas.','Láminas amarillo limón bajo un sombrero violeta más sabor picante = venenosa, dejarla, nunca confundir con la rúsula de las turberas suave.','{"La rúsula sardonia sabe muy picante (una de las más picantes); la rúsula de las turberas se vuelve suave (regla de las rúsulas: picante = venenosa).","La rúsula sardonia tiene láminas de un AMARILLO LIMÓN intenso; la rúsula de las turberas láminas de blanco crema a amarillo ocre.","La rúsula sardonia tiene sombrero púrpura-violeta-negruzco y pie violeta; la rúsula de las turberas sombrero rojo sangre/anaranjado con pie casi blanco.","Con tiempo húmedo la rúsula sardonia llora gotas en las láminas (''rúsula llorona''); la rúsula de las turberas no.","Ambas bajo pino/abeto rojo - solo el sabor y el color de las láminas distinguen con seguridad."}',false),
('russula_paludosa','russula_sardonia','fr','Lames d''un jaune citron frappant et pied violet chez la russule sardonie ; russule des marais à lames crème et pied blanc.','Russule sardonie faiblement fruitée ; russule des marais peu odorante - l''odeur distingue à peine, le goût d''autant plus.','Les deux sous pin sur sols acides - l''habitat ne distingue pas.','Sporée crème pour la russule sardonie, jaune ocre pour la russule des marais.','Des lames jaune citron sous un chapeau violet plus un goût âcre = toxique, laisser sur place, ne jamais confondre avec la russule des marais douce.','{"La russule sardonie a un goût très âcre (l''une des plus âcres) ; la russule des marais devient douce (règle des russules : âcre = toxique).","La russule sardonie a des lames d''un JAUNE CITRON éclatant ; la russule des marais des lames blanc crème à jaune ocre.","La russule sardonie a un chapeau pourpre-violet-noirâtre et un pied violet ; la russule des marais un chapeau rouge sang/orangé avec un pied presque blanc.","Par temps humide la russule sardonie pleure des gouttes sur les lames (''russule larmoyante'') ; pas la russule des marais.","Les deux sous pin/épicéa - seuls le goût et la couleur des lames distinguent avec certitude."}',false),
('russula_paludosa','russula_sardonia','it','Lamelle di un giallo limone appariscente e gambo violetto nella russula sardonia; russula delle paludi con lamelle crema e gambo bianco.','Russula sardonia debolmente fruttata; russula delle paludi poco odorosa - l''odore distingue appena, il gusto molto di più.','Entrambe sotto pino su suoli acidi - l''habitat non distingue.','Sporata crema per la russula sardonia, giallo ocra per la russula delle paludi.','Lamelle giallo limone sotto un cappello violetto più sapore piccante = velenosa, lasciar stare, mai confondere con la russula delle paludi mite.','{"La russula sardonia ha sapore molto piccante (una delle più piccanti); la russula delle paludi diventa mite (regola delle russule: piccante = velenosa).","La russula sardonia ha lamelle di un GIALLO LIMONE sgargiante; la russula delle paludi lamelle da bianco crema a giallo ocra.","La russula sardonia ha cappello porpora-violetto-nerastro e gambo violetto; la russula delle paludi cappello rosso sangue/arancio con gambo quasi bianco.","Con tempo umido la russula sardonia lacrima gocce sulle lamelle (''russula lacrimosa''); non la russula delle paludi.","Entrambe sotto pino/abete rosso - solo il gusto e il colore delle lamelle distinguono con sicurezza."}',false),
('russula_vesca','russula_nobilis','en','Bare-toothed russula (the flirt) with characteristically retracted cap cuticle (free cap margin) and a duller red; beechwood sickener vivid vermilion-red with cuticle covering the margin.','The beechwood sickener smells sweetish-fruity; the bare-toothed russula is almost odourless to faintly nutty.','Both under beech on rather dry soils - habitat does not separate them.','Both have a whitish spore print - hardly distinguishing.','With red russulas ALWAYS chew a small piece of the cap margin and spit it out - burning/acrid means poisonous and does not belong in the basket.','{"The beechwood sickener tastes immediately EXTREMELY acrid/burning; the bare-toothed russula tastes mild and nutty (brittlegill rule: acrid = poisonous).","In the bare-toothed russula the cap cuticle is typically too short and leaves the cap margin free (''coat too short''); in the beechwood sickener it covers the margin.","The beechwood sickener has a vivid vermilion-red cap colour; the bare-toothed russula rather flesh-red, wine-red to brownish, often blotchily faded.","The gills of the bare-toothed russula become rust-spotted with age; in the beechwood sickener they stay whitish to pale cream-yellow.","Both have a white stem and grow in beech forest - only the taste test separates them reliably."}',false),
('russula_vesca','russula_nobilis','es','Rúsula comestible con cutícula característicamente retraída (margen del sombrero libre) y tono rojo más apagado; rúsula del haya rojo bermellón vivo con cutícula que cubre el margen.','La rúsula del haya huele dulzón-afrutado; la rúsula comestible es casi inodora o débilmente a nuez.','Ambas bajo haya en suelos más bien secos - el hábitat no distingue.','Ambas esporada blanquecina - apenas distintivo.','Con las rúsulas rojas SIEMPRE masticar un trocito del margen del sombrero y escupir - ardiente y picante significa venenosa y no va a la cesta.','{"La rúsula del haya sabe de inmediato EXTREMADAMENTE picante/ardiente; la rúsula comestible sabe suave y a nuez (regla de las rúsulas: picante = venenosa).","En la rúsula comestible la cutícula es típicamente demasiado corta y deja libre el margen del sombrero (''manto demasiado corto''); en la rúsula del haya cubre el margen.","La rúsula del haya tiene color de sombrero rojo bermellón vivo; la rúsula comestible más bien rojo carne, rojo vinoso a parduzco, a menudo descolorida a manchas.","Las láminas de la rúsula comestible se manchan de herrumbre con la edad; en la rúsula del haya permanecen blanquecinas a amarillo crema pálido.","Ambas tienen pie blanco y crecen en hayedo - solo la prueba de sabor distingue con seguridad."}',false),
('russula_vesca','russula_nobilis','fr','Russule comestible avec une cuticule caractéristiquement rétractée (marge du chapeau dégagée) et un rouge plus terne ; russule des hêtres rouge vermillon vif avec cuticule couvrant la marge.','La russule des hêtres sent le sucré et le fruité ; la russule comestible est presque inodore à faiblement de noisette.','Les deux sous hêtre sur sols plutôt secs - l''habitat ne distingue pas.','Les deux ont une sporée blanchâtre - guère discriminant.','Pour les russules rouges, TOUJOURS mâcher un petit morceau de la marge du chapeau et recracher - brûlant et âcre signifie toxique et n''a pas sa place dans le panier.','{"La russule des hêtres a un goût immédiatement EXTRÊMEMENT âcre/brûlant ; la russule comestible a un goût doux et de noisette (règle des russules : âcre = toxique).","Chez la russule comestible la cuticule est typiquement trop courte et laisse la marge du chapeau dégagée (''manteau trop court'') ; chez la russule des hêtres elle couvre la marge.","La russule des hêtres a une couleur de chapeau rouge vermillon vif ; la russule comestible plutôt rouge chair, rouge vineux à brunâtre, souvent décolorée par plaques.","Les lames de la russule comestible se tachent de rouille avec l''âge ; chez la russule des hêtres elles restent blanchâtres à jaune crème pâle.","Les deux ont un pied blanc et poussent en hêtraie - seul le test gustatif distingue avec certitude."}',false),
('russula_vesca','russula_nobilis','it','Russula commestibile con cuticola caratteristicamente ritratta (margine del cappello libero) e tonalità rossa più spenta; russula del faggio rosso cinabro vivo con cuticola che copre il margine.','La russula del faggio odora di dolciastro-fruttato; la russula commestibile è quasi inodore o debolmente di nocciola.','Entrambe sotto faggio su suoli piuttosto secchi - l''habitat non distingue.','Entrambe sporata biancastra - poco distintivo.','Con le russule rosse SEMPRE masticare un pezzetto del margine del cappello e sputare - bruciante e piccante significa velenosa e non va nel cesto.','{"La russula del faggio ha sapore subito ESTREMAMENTE piccante/bruciante; la russula commestibile ha sapore mite e di nocciola (regola delle russule: piccante = velenosa).","Nella russula commestibile la cuticola è tipicamente troppo corta e lascia libero il margine del cappello (''mantello troppo corto''); nella russula del faggio copre il margine.","La russula del faggio ha colore del cappello rosso cinabro vivo; la russula commestibile piuttosto rosso carne, rosso vinoso fino a brunastro, spesso scolorita a chiazze.","Le lamelle della russula commestibile si macchiano di ruggine con l''età; nella russula del faggio restano biancastre fino a giallo crema pallido.","Entrambe hanno gambo bianco e crescono in faggeta - solo il test del gusto distingue con sicurezza."}',false),
('russula_xerampelina','russula_queletii','en','The crab brittlegill browns in the flesh and on the stem; the primrose brittlegill stays purple-red to violet without browning.','The crab brittlegill smells of fish/herring, the primrose brittlegill smells fruity like gooseberry compote.','Both under spruce on rather calcareous soil - habitat does not separate them.','Crab brittlegill has an ochre-yellow spore print, primrose brittlegill a cream-yellow one.','The taste test decides: burning hot/acrid = poisonous primrose brittlegill; mild plus fishy smell = edible crab brittlegill.','{"The primrose brittlegill tastes EXTREMELY acrid (one of the most acrid brittlegills); the crab brittlegill is mild (brittlegill rule: acrid = poisonous).","The crab brittlegill smells typically of herring/fish brine (especially in a warm hand and with age); the primrose brittlegill smells fruity like gooseberry compote.","Crab brittlegill flesh browns/yellows and gives a green reaction with iron sulphate; the primrose brittlegill does not.","The primrose brittlegill has a stem flushed purple-red and tinted violet; the crab brittlegill often has a pink-reddish stem that later browns.","Both grow under spruce - taste and smell separate them reliably."}',false),
('russula_xerampelina','russula_queletii','es','La rúsula de arenque pardea en la carne y en el pie; la rúsula de Quélet permanece rojo púrpura-violácea sin pardear.','La rúsula de arenque huele a pescado/arenque, la rúsula de Quélet tiene olor afrutado a compota de grosella espinosa.','Ambas bajo abeto rojo en suelo más bien calcáreo - el hábitat no distingue.','Esporada amarillo ocre en la rúsula de arenque, amarillo crema en la rúsula de Quélet.','La prueba de sabor decide: ardiente y picante = rúsula de Quélet venenosa; suave más olor a pescado = rúsula de arenque comestible.','{"La rúsula de Quélet sabe EXTREMADAMENTE picante (una de las rúsulas más picantes); la rúsula de arenque es suave (regla de las rúsulas: picante = venenosa).","La rúsula de arenque huele típicamente a arenque/salmuera de pescado (sobre todo en mano caliente y con la edad); la rúsula de Quélet huele afrutado a compota de grosella espinosa.","La carne de la rúsula de arenque pardea/amarillea y da reacción verde con sulfato de hierro; la rúsula de Quélet no.","La rúsula de Quélet tiene el pie teñido de rojo púrpura, matizado de violeta; la rúsula de arenque suele tener el pie rosa-rojizo, que luego pardea.","Ambas crecen bajo abeto rojo - el sabor y el olor distinguen con seguridad."}',false),
('russula_xerampelina','russula_queletii','fr','La russule des chevreuils brunit dans la chair et sur le pied ; la russule de Quélet reste rouge pourpre-violacé sans brunissement.','La russule des chevreuils sent le poisson/hareng, la russule de Quélet a une odeur fruitée de compote de groseille à maquereau.','Les deux sous épicéa sur sol plutôt calcaire - l''habitat ne distingue pas.','Sporée jaune ocre pour la russule des chevreuils, jaune crème pour la russule de Quélet.','Le test gustatif tranche : brûlant et âcre = russule de Quélet toxique ; doux plus odeur de poisson = russule des chevreuils comestible.','{"La russule de Quélet a un goût EXTRÊMEMENT âcre (l''une des russules les plus âcres) ; la russule des chevreuils est douce (règle des russules : âcre = toxique).","La russule des chevreuils sent typiquement le hareng/la saumure de poisson (surtout dans une main chaude et avec l''âge) ; la russule de Quélet a une odeur fruitée de compote de groseille à maquereau.","La chair de la russule des chevreuils brunit/jaunit et donne une réaction verte au sulfate de fer ; pas la russule de Quélet.","La russule de Quélet a un pied lavé de rouge pourpre, teinté de violet ; la russule des chevreuils a souvent un pied rose rougeâtre, brunissant plus tard.","Les deux poussent sous épicéa - le goût et l''odeur distinguent avec certitude."}',false),
('russula_xerampelina','russula_queletii','it','La russula delle aringhe imbrunisce nella carne e sul gambo; la russula di Quélet resta rosso porpora-violaceo senza imbrunire.','La russula delle aringhe odora di pesce/aringa, la russula di Quélet ha odore fruttato di composta di uva spina.','Entrambe sotto abete rosso su suolo piuttosto calcareo - l''habitat non distingue.','Sporata giallo ocra per la russula delle aringhe, giallo crema per la russula di Quélet.','Il test del gusto è decisivo: bruciante e piccante = russula di Quélet velenosa; mite più odore di pesce = russula delle aringhe commestibile.','{"La russula di Quélet ha un sapore ESTREMAMENTE piccante (una delle russule più piccanti); la russula delle aringhe è mite (regola delle russule: piccante = velenosa).","La russula delle aringhe odora tipicamente di aringa/salamoia di pesce (specie in mano calda e con l''età); la russula di Quélet ha odore fruttato di composta di uva spina.","La carne della russula delle aringhe imbrunisce/ingiallisce e dà reazione verde con il solfato di ferro; non così la russula di Quélet.","La russula di Quélet ha il gambo soffuso di rosso porpora, tinto di violetto; la russula delle aringhe ha spesso il gambo rosa-rossastro, poi imbrunente.","Entrambe crescono sotto abete rosso - il gusto e l''odore distinguono con sicurezza."}',false),
('russula_xerampelina','russula_sardonia','en','Sardonia russula with lemon-yellow gills and a violet cap; crab brittlegill brownish-red with browning gills and stem.','Crab brittlegill distinctly of fish/herring; sardonia russula faintly fruity, never fishy.','Both under conifers (pine/spruce) - habitat does not separate them.','Crab brittlegill has an ochre-yellow spore print, sardonia russula a cream one.','Mild plus fishy smell = edible crab brittlegill; acrid with lemon-yellow gills = poisonous sardonia russula.','{"The sardonia russula tastes very acrid; the crab brittlegill is mild (brittlegill rule: acrid = poisonous).","The crab brittlegill smells of herring/fish brine and browns in the flesh; the sardonia russula smells faintly fruity and does not brown.","The sardonia russula has bright lemon-yellow gills; the crab brittlegill cream-ochre, browning later.","The crab brittlegill reacts green with iron sulphate; the sardonia russula does not turn green.","Both under pine/spruce - taste and fishy smell are the safety criteria."}',false),
('russula_xerampelina','russula_sardonia','es','Rúsula sardonia con láminas amarillo limón y sombrero violeta; rúsula de arenque pardo-rojiza con láminas y pie que pardean.','Rúsula de arenque claramente a pescado/arenque; rúsula sardonia débilmente afrutada, nunca a pescado.','Ambas bajo coníferas (pino/abeto rojo) - el hábitat no distingue.','Esporada amarillo ocre en la rúsula de arenque, crema en la rúsula sardonia.','Suave más olor a pescado = rúsula de arenque comestible; picante con láminas amarillo limón = rúsula sardonia venenosa.','{"La rúsula sardonia sabe muy picante; la rúsula de arenque es suave (regla de las rúsulas: picante = venenosa).","La rúsula de arenque huele a arenque/salmuera de pescado y pardea en la carne; la rúsula sardonia huele débilmente afrutado y no pardea.","La rúsula sardonia tiene láminas de un amarillo limón intenso; la rúsula de arenque ocre crema, que pardea más tarde.","La rúsula de arenque reacciona en verde con sulfato de hierro; la rúsula sardonia no se vuelve verde.","Ambas bajo pino/abeto rojo - el sabor y el olor a pescado son los criterios de seguridad."}',false),
('russula_xerampelina','russula_sardonia','fr','Russule sardonie à lames jaune citron et chapeau violet ; russule des chevreuils brun-rougeâtre avec lames et pied brunissants.','Russule des chevreuils nettement de poisson/hareng ; russule sardonie faiblement fruitée, jamais de poisson.','Les deux sous conifères (pin/épicéa) - l''habitat ne distingue pas.','Sporée jaune ocre pour la russule des chevreuils, crème pour la russule sardonie.','Doux plus odeur de poisson = russule des chevreuils comestible ; âcre avec lames jaune citron = russule sardonie toxique.','{"La russule sardonie a un goût très âcre ; la russule des chevreuils est douce (règle des russules : âcre = toxique).","La russule des chevreuils sent le hareng/la saumure de poisson et brunit dans la chair ; la russule sardonie sent faiblement le fruité et ne brunit pas.","La russule sardonie a des lames d''un jaune citron éclatant ; la russule des chevreuils ocre crème, brunissant plus tard.","La russule des chevreuils réagit en vert au sulfate de fer ; la russule sardonie pas en vert.","Les deux sous pin/épicéa - le goût et l''odeur de poisson sont les critères de sécurité."}',false),
('russula_xerampelina','russula_sardonia','it','Russula sardonia con lamelle giallo limone e cappello violetto; russula delle aringhe bruno-rossastra con lamelle e gambo imbrunenti.','Russula delle aringhe nettamente di pesce/aringa; russula sardonia debolmente fruttata, mai di pesce.','Entrambe sotto conifere (pino/abete rosso) - l''habitat non distingue.','Sporata giallo ocra per la russula delle aringhe, crema per la russula sardonia.','Mite più odore di pesce = russula delle aringhe commestibile; piccante con lamelle giallo limone = russula sardonia velenosa.','{"La russula sardonia ha sapore molto piccante; la russula delle aringhe è mite (regola delle russule: piccante = velenosa).","La russula delle aringhe odora di aringa/salamoia di pesce e imbrunisce nella carne; la russula sardonia odora debolmente di fruttato e non imbrunisce.","La russula sardonia ha lamelle di un giallo limone sgargiante; la russula delle aringhe ocra crema, poi imbrunente.","La russula delle aringhe reagisce in verde con il solfato di ferro; la russula sardonia non in verde.","Entrambe sotto pino/abete rosso - il gusto e l''odore di pesce sono i criteri di sicurezza."}',false),
('steinpilz','caloboletus_calopus','en','Bitter beech bolete: clay-grey cap, bright red netted stem, blue-staining flesh. Porcini (cep): brown cap, beige netted stem, flesh staying white.','Porcini with a pleasant mushroomy smell; bitter beech bolete inconspicuous - the bitter taste decides.','Both in mixed conifer/broadleaf forest; habitat does not separate them reliably.','Both have an olive-brown spore print - NO distinguishing feature.','Taste test (tiny piece of the tube layer on the tongue, do NOT swallow, spit out): bitter plus red stem net plus blue-staining = bitter beech bolete (gastrointestinally toxic/inedible), not a porcini.','{"The bitter beech bolete tastes extremely BITTER (bitter even after cooking, inedible) - the porcini tastes mild and nutty","The bitter beech bolete quickly stains blue-green in flesh and tubes when cut; porcini flesh stays white and unchanged (does not stain blue)","The stem of the bitter beech bolete is strongly red with a fine net (red below, yellow above); the porcini stem is brown-beige with a pale net, NEVER red","The cap of the bitter beech bolete is clay-grey/grey-brown; the porcini is warm brown to chestnut brown","Tubes/pores of the porcini white to yellow-green without blue-staining; in the poisonous mushroom yellow and blue-staining on pressure"}',false),
('steinpilz','caloboletus_calopus','es','Boleto de pie hermoso: sombrero gris arcilloso, pie reticulado rojo intenso, carne que azulea. Boleto comestible (porcini): sombrero pardo, pie reticulado beige, carne que permanece blanca.','Boleto comestible con agradable olor a hongo; boleto de pie hermoso poco llamativo - el sabor amargo decide.','Ambos en bosque mixto de coníferas/frondosas; el hábitat no distingue de forma fiable.','Ambos esporada pardo-oliva - NINGÚN rasgo distintivo.','Prueba de sabor (trocito diminuto de la capa de tubos sobre la lengua, NO tragar, escupir): amargo más red roja en el pie más azulamiento = boleto de pie hermoso (tóxico gastrointestinal/no comestible), no un boleto comestible.','{"El boleto de pie hermoso sabe extremadamente AMARGO (amargo incluso tras la cocción, no comestible) - el boleto comestible sabe suave y a nuez","El boleto de pie hermoso azulea rápidamente a azul-verdoso en carne y tubos al herirlo; la carne del boleto comestible permanece blanca e inalterada (no azulea)","El pie del boleto de pie hermoso es de un rojo intenso con red fina (rojo abajo, amarillo arriba); el pie del boleto comestible es pardo-beige con red clara, NUNCA rojo","El sombrero del boleto de pie hermoso es gris arcilloso/gris-pardo; el boleto comestible es pardo cálido hasta pardo castaño","Tubos/poros del boleto comestible blancos a amarillo-verdoso sin azulear; en el hongo venenoso amarillos y azuleantes a la presión"}',false),
('steinpilz','caloboletus_calopus','fr','Bolet à beau pied : chapeau gris argileux, pied réticulé rouge vif, chair bleuissante. Cèpe : chapeau brun, pied réticulé beige, chair restant blanche.','Cèpe à odeur agréable de champignon ; bolet à beau pied discret - le goût amer tranche.','Les deux en forêt mixte de conifères/feuillus ; l''habitat ne distingue pas de façon fiable.','Les deux ont une sporée brun olive - AUCUN critère de distinction.','Épreuve gustative (minuscule morceau de la couche de tubes sur la langue, NE PAS avaler, recracher) : amer plus réseau rouge sur le pied plus bleuissement = bolet à beau pied (toxique gastro-intestinal/immangeable), pas un cèpe.','{"Le bolet à beau pied a un goût extrêmement AMER (amer même après cuisson, immangeable) - le cèpe a un goût doux et de noisette","Le bolet à beau pied bleuit rapidement en bleu-vert à la chair et aux tubes en cas de blessure ; la chair du cèpe reste blanche et inchangée (ne bleuit pas)","Le pied du bolet à beau pied est franchement rouge avec un fin réseau (rouge en bas, jaune en haut) ; le pied du cèpe est brun-beige avec un réseau clair, JAMAIS rouge","Le chapeau du bolet à beau pied est gris argileux/gris-brun ; le cèpe est brun chaud à brun châtaigne","Les tubes/pores du cèpe sont blancs à jaune-vert sans bleuir ; chez le champignon toxique ils sont jaunes et bleuissent à la pression"}',false),
('steinpilz','caloboletus_calopus','it','Boleto dal bel piede: cappello grigio argilloso, gambo reticolato rosso vivo, carne virante al blu. Porcino: cappello bruno, gambo reticolato beige, carne che resta bianca.','Porcino con gradevole odore fungino; boleto dal bel piede inappariscente - il sapore amaro è decisivo.','Entrambi in bosco misto di conifere/latifoglie; l''habitat non distingue in modo affidabile.','Entrambi sporata bruno-olivacea - NESSUN criterio distintivo.','Prova di sapore (minuscolo pezzo dello strato dei tubuli sulla lingua, NON ingoiare, sputare): amaro più reticolo rosso sul gambo più viraggio al blu = boleto dal bel piede (tossico gastrointestinale/immangiabile), non un porcino.','{"Il boleto dal bel piede ha sapore estremamente AMARO (amaro anche dopo la cottura, immangiabile) - il porcino ha sapore mite e di nocciola","Il boleto dal bel piede vira rapidamente al blu-verde nella carne e nei tubuli alla lesione; la carne del porcino resta bianca e immutata (non vira al blu)","Il gambo del boleto dal bel piede è di un rosso intenso con fine reticolo (rosso in basso, giallo in alto); il gambo del porcino è bruno-beige con reticolo chiaro, MAI rosso","Il cappello del boleto dal bel piede è grigio argilloso/grigio-bruno; il porcino è bruno caldo fino a bruno castagna","Tubuli/pori del porcino bianchi fino a giallo-verde senza virare al blu; nel fungo velenoso gialli e viranti al blu alla pressione"}',false),
('steinpilz','roehrling_flockenstielig','en','Red stem net + blue-staining yellow pore surface in the bitter beech bolete vs. white net + stably white flesh and non-staining tubes in the porcini.','Both pleasantly mushroomy; the taste test decides — bitter beech bolete bitter, porcini mild and nutty.','Large overlap in mixed/coniferous forest — location does not separate them reliably.','Both olive-brown — no distinguishing feature.','Mnemonic: if the flesh/pores stain blue or the stem net is red, it is not a porcini. In the porcini the flesh stays white and the net pale — any blue-staining or red net = not a porcini, not in the basket.','{"The bitter beech bolete tastes bitter and its flesh STAINS BLUE when cut; the porcini tastes nutty-mild and its flesh stays white/unchanged (does not stain blue)","The bitter beech bolete has a distinctly RED net/red area on the stem; the porcini has a white to pale-brown net on a pale stem","Bitter beech bolete pores yellow (staining blue on pressure); porcini tubes white → yellow → olive-green, without staining blue","Bitter beech bolete cap clay-grey/grey-brown matt; porcini cap warm light to dark brown, often greasy and shiny","Taste sample: bitter beech bolete bitter, porcini mild — a reliable separating criterion"}',false),
('steinpilz','roehrling_flockenstielig','es','Red roja en el pie + superficie de poros amarilla azuleante en el boleto de pie hermoso vs. red blanca + carne establemente blanca y tubos no azuleantes en el boleto comestible.','Ambos con agradable olor a hongo; la prueba de sabor decide — boleto de pie hermoso amargo, boleto comestible suave y a nuez.','Gran solapamiento en bosque mixto/de coníferas — la estación no distingue de forma fiable.','Ambos pardo-oliva — ningún rasgo distintivo.','Regla mnemotécnica: si la carne/los poros azulean o la red del pie es roja, no es un boleto comestible. En el boleto comestible la carne permanece blanca y la red clara — cualquier azulamiento o red roja = no es boleto comestible, no a la cesta.','{"El boleto de pie hermoso sabe amargo y su carne AZULEA al corte; el boleto comestible sabe a nuez suave y su carne permanece blanca/inalterada (no azulea)","El boleto de pie hermoso tiene una red/zona claramente ROJA en el pie; el boleto comestible tiene una red de blanca a pardo claro sobre pie claro","Poros del boleto de pie hermoso amarillos (azuleantes a la presión); tubos del boleto comestible blancos → amarillos → verde oliva, sin azulear","Sombrero del boleto de pie hermoso gris arcilloso/gris-pardo mate; sombrero del boleto comestible pardo claro a oscuro cálido, a menudo lustroso y graso","Cata de sabor: boleto de pie hermoso amargo, boleto comestible suave — criterio de separación seguro"}',false),
('steinpilz','roehrling_flockenstielig','fr','Réseau rouge sur le pied + champ de pores jaune bleuissant chez le bolet à beau pied vs. réseau blanc + chair restant blanche et tubes ne bleuissant pas chez le cèpe.','Les deux à odeur agréable de champignon ; le test gustatif tranche — bolet à beau pied amer, cèpe doux et de noisette.','Grande superposition en forêt mixte/de conifères — la station ne distingue pas de façon fiable.','Les deux brun olive — aucun critère de distinction.','Aide-mémoire : si la chair/les pores bleuissent ou si le réseau du pied est rouge, ce n''est pas un cèpe. Chez le cèpe la chair reste blanche et le réseau clair — tout bleuissement ou réseau rouge = pas un cèpe, pas dans le panier.','{"Le bolet à beau pied a un goût amer et sa chair BLEUIT à la coupe ; le cèpe a un goût doux de noisette et sa chair reste blanche/inchangée (ne bleuit pas)","Le bolet à beau pied a un réseau/une zone nettement ROUGE sur le pied ; le cèpe a un réseau blanc à brun clair sur un pied clair","Pores du bolet à beau pied jaunes (bleuissant à la pression) ; tubes du cèpe blancs → jaunes → vert olive, sans bleuir","Chapeau du bolet à beau pied gris argileux/gris-brun mat ; chapeau du cèpe brun clair à foncé chaud, souvent luisant et gras","Dégustation : bolet à beau pied amer, cèpe doux — critère de séparation sûr"}',false),
('steinpilz','roehrling_flockenstielig','it','Reticolo rosso sul gambo + campo dei pori giallo virante al blu nel boleto dal bel piede vs. reticolo bianco + carne stabilmente bianca e tubuli non viranti nel porcino.','Entrambi con gradevole odore fungino; il test del gusto è decisivo — boleto dal bel piede amaro, porcino mite e di nocciola.','Ampia sovrapposizione in bosco misto/di conifere — la stazione non distingue in modo affidabile.','Entrambi bruno-olivacei — nessun criterio distintivo.','Promemoria: se la carne/i pori virano al blu o se il reticolo del gambo è rosso, non è un porcino. Nel porcino la carne resta bianca e il reticolo chiaro — qualsiasi viraggio al blu o reticolo rosso = non porcino, non nel cesto.','{"Il boleto dal bel piede ha sapore amaro e la sua carne VIRA AL BLU al taglio; il porcino ha sapore di nocciola mite e la sua carne resta bianca/immutata (non vira al blu)","Il boleto dal bel piede ha un reticolo/una zona nettamente ROSSA sul gambo; il porcino ha un reticolo da bianco a bruno chiaro su gambo chiaro","Pori del boleto dal bel piede gialli (viranti al blu alla pressione); tubuli del porcino bianchi → gialli → verde olivastro, senza virare al blu","Cappello del boleto dal bel piede grigio argilloso/grigio-bruno opaco; cappello del porcino bruno chiaro fino a scuro caldo, spesso lucido e untuoso","Assaggio: boleto dal bel piede amaro, porcino mite — criterio di separazione sicuro"}',false),
('steinpilz','rubroboletus_satanas','en','The decisive feature is pore colour: red/orange in the Devil''s bolete, never in the porcino (cep) — plus the red stem net instead of a white net, and the faint bluing instead of no colour change at all.','The old Devil''s bolete stinks of carrion/rot, the cep smells pleasantly nutty and mushroomy.','Both in warm deciduous woods on lime under oak/beech — the habitat does not separate them reliably.','Both have an olive-brown spore print — no practical distinguishing feature.','Always leave behind any bolete with even a hint of red/orange pores — a true cep NEVER has red pores.','{"The Devil''s bolete has RED to orange-red pores; the cep NEVER has red pores (white when young, then yellowish-olive).","The Devil''s bolete''s flesh bluish only weakly to moderately when cut; the cep''s flesh stays completely white and does not change colour.","The Devil''s bolete has a distinctly red, close-meshed stem net on a yellow ground (later blood-red) on a bulbous-tuberous stem; the cep has a fine white to brownish net.","The mature/old Devil''s bolete smells repulsively of carrion; the cep smells pleasantly mushroomy and nutty.","Both have a pale, whitish-grey-green to chalk-white cap when young — the pale cap colour alone must NEVER be used for identification."}',false),
('steinpilz','rubroboletus_satanas','es','El criterio decisivo es el color de los poros: rojo/naranja en el boleto de Satanás, nunca en el cep (boletus edulis) — además de la red roja del pie en lugar de la red blanca, y el ligero azuleamiento en lugar de no cambiar de color.','El boleto de Satanás viejo apesta a carroña/putrefacción, el cep huele agradablemente a avellana y a champiñón.','Ambos en bosques caducifolios cálidos sobre caliza bajo roble/haya — el hábitat no los distingue de forma fiable.','Ambos esporada pardo-oliva — ningún criterio de distinción práctico.','Dejar siempre en el sitio cualquier boleto con poros aunque sea levemente rojizos/anaranjados — un cep verdadero NUNCA tiene poros rojos.','{"El boleto de Satanás tiene poros ROJOS hasta rojo anaranjado; el cep NUNCA tiene poros rojos (blancos de joven, luego amarillento-oliva).","La carne del boleto de Satanás al corte azulea solo débil a moderadamente; la carne del cep permanece completamente blanca y no cambia de color.","El boleto de Satanás tiene una red claramente roja, de malla densa sobre fondo amarillo (más tarde rojo sangre) en el pie ventrudo-bulboso; el cep tiene una red fina blanca a parduzca.","El boleto de Satanás maduro/viejo huele repugnantemente a carroña; el cep huele agradablemente a champiñón y avellana.","Ambos tienen de jóvenes un sombrero claro, blanquecino-gris-verde a blanco calizo — el color claro del sombrero por sí solo NUNCA debe servir para la identificación."}',false),
('steinpilz','rubroboletus_satanas','fr','Le critère décisif est la couleur des pores : rouge/orange chez le bolet Satan, jamais chez le cèpe — plus le réseau rouge sur le pied au lieu d''un réseau blanc, et le léger bleuissement au lieu d''aucun changement de couleur.','Le vieux bolet Satan empeste la charogne/la putréfaction, le cèpe sent agréablement la noisette et le champignon.','Tous deux dans les forêts feuillues chaudes sur calcaire sous chêne/hêtre — l''habitat ne permet pas de les distinguer de façon fiable.','Tous deux une sporée brun-olive — aucun critère de distinction pratique.','Laisser systématiquement sur place tout bolet présentant ne serait-ce qu''une nuance de pores rouges/orange — un vrai cèpe n''a JAMAIS de pores rouges.','{"Le bolet Satan a des pores ROUGES à rouge orangé ; le cèpe n''a JAMAIS de pores rouges (blancs jeunes, puis jaunâtre-olive).","La chair du bolet Satan bleuit faiblement à modérément à la coupe ; la chair du cèpe reste entièrement blanche et ne change pas de couleur.","Le bolet Satan a un réseau nettement rouge, à mailles serrées sur fond jaune (plus tard rouge sang) sur un pied ventru-bulbeux ; le cèpe a un fin réseau blanc à brunâtre.","Le bolet Satan mûr/vieux dégage une odeur répugnante de charogne ; le cèpe sent agréablement le champignon et la noisette.","Tous deux ont jeune un chapeau clair, blanchâtre-gris-vert à blanc calcaire — la couleur claire du chapeau seule ne doit JAMAIS servir à l''identification."}',false),
('steinpilz','rubroboletus_satanas','it','Il criterio decisivo è il colore dei pori: rosso/arancione nel boleto di Satana, mai nel porcino — più il reticolo rosso sul gambo invece del reticolo bianco e il leggero viraggio al blu invece di nessun cambiamento di colore.','Il vecchio boleto di Satana puzza di carogna/putrefazione, il porcino profuma gradevolmente di nocciola e di fungo.','Entrambi nei boschi di latifoglie caldi su calcare sotto quercia/faggio — l''habitat non li distingue in modo affidabile.','Entrambi sporata bruno-olivacea — nessun criterio di distinzione pratico.','Lasciare sempre sul posto ogni boleto con pori anche solo accennati al rosso/arancione — un vero porcino non ha MAI pori rossi.','{"Il boleto di Satana ha pori ROSSI fino a rosso-arancio; il porcino non ha MAI pori rossi (da giovane bianchi, poi giallastro-olivacei).","La carne del boleto di Satana al taglio vira al blu solo debolmente o moderatamente; la carne del porcino rimane completamente bianca e non cambia colore.","Il boleto di Satana ha un reticolo nettamente rosso a maglie fitte su fondo giallo (più tardi rosso sangue) sul gambo ventricoso-bulboso; il porcino ha un reticolo fine bianco fino a brunastro.","Il boleto di Satana maturo/vecchio emana un odore disgustoso di carogna; il porcino profuma gradevolmente di fungo e nocciola.","Entrambi da giovani hanno un cappello chiaro, biancastro-grigio-verde fino a bianco calce — il colore chiaro del cappello da solo non deve MAI servire all''identificazione."}',false),
('suillellus_luridus','caloboletus_calopus','en','Lurid bolete (netted-stem): red-orange pores, red stem net, Batsch line. Bitter beech bolete (Caloboletus calopus): yellow pores, grey cap, red-yellow netted stem.','Both inconspicuous — the bitter taste of the Caloboletus calopus is the separating feature.','Both with broadleaf trees; the lurid bolete prefers lime-rich soil. Habitat does not separate them reliably.','Both have an olive-brown spore print — NO distinguishing feature.','Check the pores AND do a taste test (spit out): yellow pores plus bitter = Caloboletus calopus (discard); red/orange pores without bitterness = lurid bolete — this one is toxic raw and edible only when thoroughly cooked, never taste it raw except for the spit-out taste test.','{"The Caloboletus calopus tastes strongly BITTER (inedible/gastrointestinal-toxic even when cooked); the lurid bolete is mild, but edible ONLY when thoroughly cooked (toxic raw).","The lurid bolete has RED-ORANGE pores and a reddish line (Batsch line) above the tubes; the Caloboletus calopus has yellow pores.","The lurid bolete''s cap is olive-brown/leather-brown, often cushion-shaped; the Caloboletus calopus is clay-grey.","Both bruise strongly blue — but the lurid bolete with red pores and a red net on a brownish-yellow stem, the Caloboletus calopus with yellow pores and a red-yellow stem.","Taste decides: Caloboletus calopus is bitter (discard); the lurid bolete is mild and edible only after sufficient cooking."}',false),
('suillellus_luridus','caloboletus_calopus','es','Boleto lúrido (de pie reticulado): poros rojo-anaranjados, red roja en el pie, línea de Batsch. Boleto de pie bonito (Caloboletus calopus): poros amarillos, sombrero gris, pie reticulado rojo-amarillo.','Ambos discretos — el sabor amargo del boleto de pie bonito es el criterio de separación.','Ambos junto a frondosas; el boleto lúrido prefiere suelos calcáreos. El hábitat no separa de forma fiable.','Ambos esporada pardo-oliva — NINGÚN criterio de distinción.','Comprobar los poros Y hacer una prueba de sabor (escupir): poros amarillos más amargo = boleto de pie bonito (descartar); poros rojos/anaranjados sin amargor = boleto lúrido — este es tóxico crudo y comestible solo bien cocinado, nunca probarlo crudo salvo para la prueba de sabor en la que se escupe.','{"El boleto de pie bonito sabe fuertemente AMARGO (incomible/tóxico gastrointestinal incluso cocinado); el boleto lúrido es suave, pero comestible SOLO bien cocinado (tóxico crudo).","El boleto lúrido tiene poros ROJO-ANARANJADOS y una línea rojiza (línea de Batsch) sobre los tubos; el boleto de pie bonito tiene poros amarillos.","El sombrero del boleto lúrido es pardo-oliva/pardo-cuero, a menudo acolchado; el boleto de pie bonito es gris-arcilla.","Ambos azulean fuertemente — pero el boleto lúrido con poros rojos y red roja sobre pie parduzco-amarillo, el boleto de pie bonito con poros amarillos y pie rojo-amarillo.","El sabor decide: el pie bonito es amargo (descartar); el boleto lúrido es suave y comestible solo tras una cocción suficiente."}',false),
('suillellus_luridus','caloboletus_calopus','fr','Bolet blafard (à pied réticulé) : pores rouge-orange, réseau rouge sur le pied, ligne de Batsch. Bolet à beau pied : pores jaunes, chapeau gris, pied réticulé rouge-jaune.','Tous deux discrets — le goût amer du bolet à beau pied est le critère de séparation.','Tous deux sous feuillus ; le bolet blafard préfère les sols calcaires. L''habitat ne sépare pas de façon fiable.','Tous deux sporée brun-olive — AUCUN critère de distinction.','Vérifier les pores ET faire un test gustatif (recracher) : pores jaunes plus goût amer = bolet à beau pied (à écarter) ; pores rouges/orange sans amertume = bolet blafard — celui-ci est toxique cru et comestible uniquement bien cuit, ne jamais le goûter cru sauf pour le test gustatif où l''on recrache.','{"Le bolet à beau pied a un goût fortement AMER (immangeable/toxique gastro-intestinal même cuit) ; le bolet blafard est doux, mais comestible UNIQUEMENT bien cuit (toxique cru).","Le bolet blafard a des pores ROUGE-ORANGE et une ligne rougeâtre (ligne de Batsch) au-dessus des tubes ; le bolet à beau pied a des pores jaunes.","Le chapeau du bolet blafard est brun-olive/brun-cuir, souvent en coussin ; le bolet à beau pied est gris-argile.","Tous deux bleuissent fortement — mais le bolet blafard avec des pores rouges et un réseau rouge sur un pied brunâtre-jaune, le bolet à beau pied avec des pores jaunes et un pied rouge-jaune.","Le goût décide : le beau pied est amer (à écarter) ; le bolet blafard est doux et comestible seulement après une cuisson suffisante."}',false),
('suillellus_luridus','caloboletus_calopus','it','Boleto lurido (a gambo reticolato): pori rosso-arancio, reticolo rosso sul gambo, linea di Batsch. Boleto dal bel piede: pori gialli, cappello grigio, gambo reticolato rosso-giallo.','Entrambi poco appariscenti — il sapore amaro del boleto dal bel piede è il criterio distintivo.','Entrambi presso latifoglie; il boleto lurido predilige suoli calcarei. L''habitat non separa in modo affidabile.','Entrambi sporata bruno-olivacea — NESSUN criterio di distinzione.','Controllare i pori E fare una prova di sapore (sputare): pori gialli più amaro = boleto dal bel piede (da scartare); pori rossi/arancio senza amaro = boleto lurido — quest''ultimo è tossico crudo e commestibile solo ben cotto, non assaggiarlo mai crudo se non per la prova di sapore con sputo.','{"Il boleto dal bel piede ha un sapore fortemente AMARO (immangiabile/tossico gastrointestinale anche cotto); il boleto lurido è dolce, ma commestibile SOLO ben cotto (tossico crudo).","Il boleto lurido ha pori ROSSO-ARANCIO e una linea rossastra (linea di Batsch) sopra i tubuli; il boleto dal bel piede ha pori gialli.","Il cappello del boleto lurido è bruno-olivaceo/bruno-cuoio, spesso pulvinato; il boleto dal bel piede è grigio-argilla.","Entrambi virano fortemente al blu — ma il boleto lurido con pori rossi e reticolo rosso su gambo brunastro-giallo, il boleto dal bel piede con pori gialli e gambo rosso-giallo.","Il sapore decide: il bel piede è amaro (da scartare); il boleto lurido è dolce e commestibile solo dopo cottura sufficiente."}',false),
('suillellus_luridus','rubroboletus_legaliae','en','Pale whitish/grey-pink cap in Le Gal''s bolete vs ochre/brick-red-dark-olive cap in the lurid bolete; in Le Gal''s NO bluing of the cap cuticle, in the lurid bolete strong bluing.','Le Gal''s distinctly of celery/lovage; the lurid bolete neutral in smell.','Le Gal''s rare, warmth-loving under old oaks/beeches on lime; the lurid bolete more frequent in deciduous/mixed woodland on lime — overlap possible, the site does not separate them with certainty.','Both olive-brown spore print — no separating feature.','Take red-pored boletes only as an experienced forager: pale/pink cap + celery smell + only faint bluing = Le Gal/Satan group, toxic. The so-called Bataille line (red line above the tubes) is NOT a reliable identification feature — it is absent in many true lurid boletes and is overrated. When in doubt, leave it standing.','{"Le Gal''s bolete (Rubroboletus legaliae) has a pale, whitish/grey to wine-pink-old-rose cap; the lurid bolete has an ochre-brown to brick-red-dark-olive cap.","Le Gal''s smells conspicuously spicy of lovage/celery/chicory; the lurid bolete smells neutral, mushroomy.","Le Gal''s bluish only weakly/moderately in the flesh and NOT in the cap cuticle; the lurid bolete bluish immediately and strongly dark blue (cap cuticle/flesh too).","Both have red/carmine pores and a stem net — these features do NOT separate them; decisive are cap colour, celery smell and bluing intensity.","Le Gal''s is toxic/intolerable even well heated (severe gastrointestinal disturbances reported); the lurid bolete is toxic ONLY raw, edible after sufficient heating (even then not with alcohol)."}',false),
('suillellus_luridus','rubroboletus_legaliae','es','Sombrero pálido blanco/gris-rosado en el boleto de Le Gal vs sombrero ocre/rojo-ladrillo-verde oliva oscuro en el boleto lúrido; en el Le Gal NINGÚN azuleamiento de la cutícula, en el boleto lúrido fuerte azuleamiento.','Le Gal claramente a olor de apio/levístico; el boleto lúrido neutro olfativamente.','Le Gal raro, termófilo bajo viejos robles/hayas sobre caliza; el boleto lúrido más frecuente en bosque caducifolio/mixto sobre caliza — solapamiento posible, el lugar no separa con certeza.','Ambos esporada pardo-oliva — ningún criterio de separación.','Recoger boletos de poros rojos solo como recolector experimentado: sombrero pálido/rosado + olor a apio + azuleamiento solo débil = grupo Le Gal/Satanás, tóxico. La llamada línea de Bataille (línea roja sobre los tubos) NO es un criterio de identificación fiable — falta en muchos boletos lúridos verdaderos y está sobrevalorada. En caso de duda, dejar en el sitio.','{"El boleto de Le Gal (Rubroboletus legaliae) tiene un sombrero pálido, blanquecino/gris hasta rosa vinoso-rosa viejo; el boleto lúrido tiene un sombrero ocre-pardo hasta rojo-ladrillo-verde oliva oscuro.","Le Gal huele de forma llamativa y especiada a levístico/apio/achicoria; el boleto lúrido huele neutro, a champiñón.","Le Gal azulea solo débil/moderadamente en la carne y NO en la cutícula; el boleto lúrido azulea de inmediato e intensamente en azul oscuro (también cutícula/carne).","Ambos tienen poros rojos/rojo carmín y una red en el pie — estos caracteres NO los separan; decisivos son el color del sombrero, el olor a apio y la intensidad del azuleamiento.","Le Gal es tóxico/indigesto incluso bien calentado (se han notificado trastornos gastrointestinales graves); el boleto lúrido es tóxico SOLO crudo, comestible tras un calentamiento suficiente (ni siquiera entonces con alcohol)."}',false),
('suillellus_luridus','rubroboletus_legaliae','fr','Chapeau pâle blanc/gris-rosé chez le bolet de Le Gal vs chapeau ocre/rouge-brique-vert olive foncé chez le bolet blafard ; chez Le Gal AUCUN bleuissement de la cuticule, chez le bolet blafard fort bleuissement.','Le Gal nettement odeur de céleri/livèche ; le bolet blafard neutre du point de vue olfactif.','Le Gal rare, thermophile sous vieux chênes/hêtres sur calcaire ; le bolet blafard plus fréquent en forêt feuillue/mixte sur calcaire — chevauchement possible, le site ne sépare pas avec certitude.','Tous deux sporée brun-olive — pas de critère de séparation.','Ne prendre les bolets à pores rouges qu''en tant que cueilleur expérimenté : chapeau pâle/rosé + odeur de céleri + bleuissement seulement faible = groupe Le Gal/Satan, toxique. La fameuse ligne de Bataille (ligne rouge au-dessus des tubes) n''est PAS un critère d''identification fiable — elle manque à beaucoup de vrais bolets blafards et est surestimée. En cas de doute, laisser sur place.','{"Le bolet de Le Gal (Rubroboletus legaliae) a un chapeau pâle, blanchâtre/gris à rose vineux-vieux rose ; le bolet blafard a un chapeau ocre-brun à rouge-brique-vert olive foncé.","Le Gal sent de façon marquée et épicée la livèche/le céleri/la chicorée ; le bolet blafard sent neutre, comme un champignon.","Le Gal bleuit seulement faiblement/modérément dans la chair et PAS dans la cuticule ; le bolet blafard bleuit aussitôt fortement en bleu foncé (cuticule/chair également).","Tous deux ont des pores rouges/rouge carmin et un réseau sur le pied — ces caractères ne séparent PAS ; ce qui est décisif, c''est la couleur du chapeau, l''odeur de céleri et l''intensité du bleuissement.","Le Gal est toxique/indigeste même bien chauffé (graves troubles gastro-intestinaux signalés) ; le bolet blafard est toxique UNIQUEMENT cru, comestible après une cuisson suffisante (même alors pas avec de l''alcool)."}',false),
('suillellus_luridus','rubroboletus_legaliae','it','Cappello pallido bianco/grigio-rosato nel boleto di Le Gal vs cappello ocra/rosso-mattone-verde oliva scuro nel boleto lurido; nel Le Gal NESSUN viraggio al blu della cuticola, nel boleto lurido forte viraggio al blu.','Le Gal odore netto di sedano/levistico; il boleto lurido neutro dal punto di vista olfattivo.','Le Gal raro, termofilo sotto vecchie querce/faggi su calcare; il boleto lurido più frequente in bosco di latifoglie/misto su calcare — sovrapposizione possibile, il sito non separa con certezza.','Entrambi sporata bruno-olivacea — nessun criterio distintivo.','Raccogliere i boleti a pori rossi solo da raccoglitori esperti: cappello pallido/rosato + odore di sedano + viraggio solo debole = gruppo Le Gal/Satana, tossico. La cosiddetta linea di Bataille (linea rossa sopra i tubuli) NON è un criterio di identificazione affidabile — manca a molti veri boleti luridi ed è sopravvalutata. In caso di dubbio, lasciare sul posto.','{"Il boleto di Le Gal (Rubroboletus legaliae) ha un cappello pallido, biancastro/grigio fino a rosa vinoso-rosa antico; il boleto lurido ha un cappello ocra-bruno fino a rosso-mattone-verde oliva scuro.","Le Gal odora in modo marcato e speziato di levistico/sedano/cicoria; il boleto lurido odora neutro, di fungo.","Le Gal vira al blu solo debolmente/moderatamente nella carne e NON nella cuticola; il boleto lurido vira subito intensamente al blu scuro (anche cuticola/carne).","Entrambi hanno pori rossi/rosso carminio e un reticolo sul gambo — questi caratteri NON separano; decisivi sono il colore del cappello, l''odore di sedano e l''intensità del viraggio al blu.","Le Gal è tossico/indigesto anche ben riscaldato (segnalati gravi disturbi gastrointestinali); il boleto lurido è tossico SOLO crudo, commestibile dopo cottura sufficiente (anche allora non con alcol)."}',false),
('suillellus_luridus','rubroboletus_satanas','en','Pale whitish-grey cap in the Devil''s bolete vs olive-yellow-brown cap in the lurid bolete; the lurid bolete bluish immediately and intensely, the Devil''s bolete only weakly.','Devil''s bolete when old of carrion, the netted-stem lurid bolete neutral, mushroomy.','Both on lime under broadleaf trees — no reliable separating feature.','Both olive-brown — not separating.','Eat red-pored boletes only if identified beyond doubt as the edible lurid bolete AND thoroughly heated — when in doubt, to the mushroom inspection (VAPKO).','{"The netted-stem lurid bolete bluish QUICKLY and intensely deep blue when cut; the Devil''s bolete bluish only weakly/with delay.","The netted-stem lurid bolete has an olive-yellow to grey-brown cap; the Devil''s bolete when young a pale, chalk-white-grey-green cap.","Both have red/orange-red pores AND a red stem net — the red pore colour does NOT separate them, only bluing speed, cap colour and smell.","The Devil''s bolete smells repulsively of carrion with age; the netted-stem lurid bolete smells neutral, mushroomy.","The netted-stem lurid bolete is toxic/intolerable raw and edible only when well heated; the Devil''s bolete remains toxic even when cooked."}',false),
('suillellus_luridus','rubroboletus_satanas','es','Sombrero claro blanquecino-gris en el boleto de Satanás vs sombrero amarillo-oliva-pardo en el boleto lúrido; el boleto lúrido azulea de inmediato e intensamente, el boleto de Satanás solo débilmente.','Boleto de Satanás viejo a carroña, el boleto lúrido de pie reticulado neutro, a champiñón.','Ambos sobre caliza bajo frondosas — ningún criterio de separación seguro.','Ambos pardo-oliva — no distintivo.','Comer boletos de poros rojos solo si se identifican sin lugar a dudas como boleto lúrido comestible Y bien calentados — en caso de duda, al control de setas (VAPKO).','{"El boleto lúrido de pie reticulado al corte azulea RÁPIDAMENTE e intensamente en azul profundo; el boleto de Satanás azulea solo débilmente/con retraso.","El boleto lúrido de pie reticulado tiene un sombrero amarillo-oliva a gris-pardo; el boleto de Satanás de joven un sombrero claro, blanco calizo-gris-verde.","Ambos tienen poros rojos/rojo anaranjado Y una red roja en el pie — el color rojo de los poros NO los separa, solo la velocidad del azuleamiento, el color del sombrero y el olor.","El boleto de Satanás con la edad huele repugnantemente a carroña; el boleto lúrido de pie reticulado huele neutro, a champiñón.","El boleto lúrido de pie reticulado es tóxico/indigesto crudo y comestible solo bien calentado; el boleto de Satanás permanece tóxico incluso cocinado."}',false),
('suillellus_luridus','rubroboletus_satanas','fr','Chapeau clair blanchâtre-gris chez le bolet Satan vs chapeau jaune-olive-brun chez le bolet blafard ; le bolet blafard bleuit aussitôt intensément, le bolet Satan seulement faiblement.','Bolet Satan vieux odeur de charogne, bolet blafard neutre, de champignon.','Tous deux sur calcaire sous feuillus — pas de critère de séparation sûr.','Tous deux brun-olive — non distinctif.','Ne manger les bolets à pores rouges que s''ils sont identifiés sans doute possible comme bolet blafard comestible ET bien cuits — en cas de doute, au contrôle des champignons (VAPKO).','{"Le bolet blafard bleuit à la coupe RAPIDEMENT et intensément en bleu profond ; le bolet Satan bleuit seulement faiblement/avec retard.","Le bolet blafard a un chapeau jaune-olive à gris-brun ; le bolet Satan jeune un chapeau clair, blanc calcaire-gris-vert.","Tous deux ont des pores rouges/rouge orangé ET un réseau rouge sur le pied — la couleur rouge des pores ne les sépare PAS, seules la vitesse de bleuissement, la couleur du chapeau et l''odeur.","Le bolet Satan sent avec l''âge de façon répugnante la charogne ; le bolet blafard sent neutre, de champignon.","Le bolet blafard est toxique/indigeste cru et comestible seulement bien cuit ; le bolet Satan reste toxique même cuit."}',false),
('suillellus_luridus','rubroboletus_satanas','it','Cappello chiaro biancastro-grigio nel boleto di Satana vs cappello giallo-olivaceo-bruno nel boleto lurido; il boleto lurido vira subito intensamente al blu, il boleto di Satana solo debolmente.','Boleto di Satana vecchio odore di carogna, boleto lurido neutro, di fungo.','Entrambi su calcare sotto latifoglie — nessun criterio distintivo sicuro.','Entrambi bruno-olivacei — non distintivo.','Mangiare i boleti a pori rossi solo se identificati senza alcun dubbio come boleto lurido commestibile E ben cotti — in caso di dubbio, al controllo dei funghi (VAPKO).','{"Il boleto lurido al taglio vira RAPIDAMENTE e intensamente al blu profondo; il boleto di Satana vira solo debolmente/con ritardo.","Il boleto lurido ha un cappello giallo-olivaceo fino a grigio-bruno; il boleto di Satana da giovane un cappello chiaro, bianco calce-grigio-verde.","Entrambi hanno pori rossi/rosso-arancio E un reticolo rosso sul gambo — il colore rosso dei pori NON li separa, solo la velocità del viraggio al blu, il colore del cappello e l''odore.","Il boleto di Satana con l''età odora in modo disgustoso di carogna; il boleto lurido odora neutro, di fungo.","Il boleto lurido è tossico/indigesto crudo e commestibile solo ben cotto; il boleto di Satana rimane tossico anche cotto."}',false),
('tricholoma_columbetta','tricholoma_pardinum','en','The dove-coloured tricholoma (St George''s-grey relative) is pure silky-white and smooth; the tiger tricholoma (Tricholoma pardinum) is grey with a coarse dark scaly covering.','The dove tricholoma is mild to faintly mealy; the tiger tricholoma mealy/cucumber-like — the smell is not decisive, cap colour and scaliness count.','Both possible in deciduous and mountain forests; the site does not separate them reliably — cap colour and scaliness are decisive.','Both white spore print — no distinguishing feature.','EVEN more important than the tiger tricholoma: pure-white tricholomas can be confused with the deadly white death-cap relatives (Amanita) — always check for the absence of a bulb/volva and ring. Only flawlessly white, scale-free specimens without a stem bulb count as the dove tricholoma.','{"The dove/silky tricholoma is pure white to silky shining with a smooth surface; the tiger tricholoma is grey to grey-brown with coarse dark scales on the cap.","A genuinely pure-white, scale-free cap argues clearly against the tiger tricholoma; any grey tinge or coarse scale is a warning sign.","The dove tricholoma may turn blue-greenish/pink on the stem under pressure but stays overall white-silky; the tiger tricholoma is grey from the base up and patterned-scaly.","The tiger tricholoma causes a severe gastrointestinal syndrome (vomiting/diarrhoea after 15-30 min) — with any grey tinge or scales never count it as the dove tricholoma."}',false),
('tricholoma_columbetta','tricholoma_pardinum','es','Tricoloma colombeta de un blanco sedoso puro y liso; tricoloma atigrado gris con un grosero revestimiento escamoso oscuro.','Tricoloma colombeta suave hasta débilmente harinoso; tricoloma atigrado harinoso/a pepino — el olor no es decisivo, cuentan el color del sombrero y la escamosidad.','Ambos posibles en bosques caducifolios y de montaña; el lugar no los separa de forma fiable — el color del sombrero y la escamosidad son determinantes.','Ambos esporada blanca — ningún criterio de distinción.','AÚN más importante que el tricoloma atigrado: los tricolomas de un blanco puro pueden confundirse con las mortales amanitas blancas (Amanita) — comprobar siempre la ausencia de bulbo/volva y anillo. Solo ejemplares de un blanco impecable, sin escamas y sin bulbo en el pie, se consideran tricoloma colombeta.','{"El tricoloma colombeta/sedoso es de un blanco puro hasta sedoso brillante, con superficie lisa; el tricoloma atigrado es gris hasta gris-pardo con grandes escamas oscuras en el sombrero.","Un sombrero realmente de un blanco puro, sin escamas, habla claramente en contra del tricoloma atigrado; cualquier tonalidad gris o escama grande es una señal de alarma.","El tricoloma colombeta en el pie bajo presión puede virar a azul-verdoso/rosa, pero permanece en conjunto blanco-sedoso; el tricoloma atigrado es gris desde la base y escamoso-jaspeado.","El tricoloma atigrado provoca un síndrome gastrointestinal grave (vómitos/diarrea tras 15-30 min) — ante cualquier tonalidad gris o escamas, nunca considerarlo tricoloma colombeta."}',false),
('tricholoma_columbetta','tricholoma_pardinum','fr','Tricholome colombette d''un blanc soyeux pur et lisse ; tricholome tigré gris avec un grossier revêtement écailleux sombre.','Tricholome colombette doux à faiblement farineux ; tricholome tigré farineux/concombre — l''odeur n''est pas décisive, ce qui compte c''est la couleur du chapeau et l''écaillure.','Tous deux possibles en forêts feuillues et de montagne ; le site ne les sépare pas de façon fiable — la couleur du chapeau et l''écaillure sont déterminantes.','Tous deux sporée blanche — aucun critère de distinction.','PLUS important encore que le tricholome tigré : les tricholomes d''un blanc pur peuvent être confondus avec les amanites blanches mortelles (Amanita) — toujours vérifier l''absence de bulbe/volve et d''anneau. Seuls des exemplaires d''un blanc impeccable, sans écailles et sans bulbe au pied, sont considérés comme tricholome colombette.','{"Le tricholome colombette/soyeux est d''un blanc pur à soyeux brillant, à surface lisse ; le tricholome tigré est gris à gris-brun avec de grosses écailles sombres sur le chapeau.","Un chapeau réellement d''un blanc pur, sans écailles, plaide clairement contre le tricholome tigré ; toute teinte grise ou grosse écaille est un signal d''alarme.","Le tricholome colombette peut se colorer en bleu-vert/rose au pied sous la pression, mais reste globalement blanc-soyeux ; le tricholome tigré est gris à la base et écailleux-tacheté.","Le tricholome tigré provoque un syndrome gastro-intestinal sévère (vomissements/diarrhée après 15-30 min) — en cas de teinte grise ou d''écailles, ne jamais le considérer comme tricholome colombette."}',false),
('tricholoma_columbetta','tricholoma_pardinum','it','Tricoloma colombetta bianco-serico puro e liscio; tricoloma tigrato grigio con un grossolano rivestimento squamoso scuro.','Tricoloma colombetta dolce fino a debolmente farinoso; tricoloma tigrato farinoso/cetriolo — l''odore non è decisivo, contano il colore del cappello e la squamosità.','Entrambi possibili in boschi di latifoglie e di montagna; il sito non li separa in modo affidabile — il colore del cappello e la squamosità sono determinanti.','Entrambi sporata bianca — nessun criterio di distinzione.','ANCORA più importante del tricoloma tigrato: i tricolomi bianco puro possono essere confusi con le mortali amanite bianche (Amanita) — controllare sempre l''assenza di bulbo/volva e anello. Solo esemplari di un bianco impeccabile, privi di squame e senza bulbo al gambo, sono considerati tricoloma colombetta.','{"Il tricoloma colombetta/serico è bianco puro fino a serico brillante, con superficie liscia; il tricoloma tigrato è grigio fino a grigio-bruno con grosse squame scure sul cappello.","Un cappello davvero bianco puro, privo di squame, depone chiaramente contro il tricoloma tigrato; ogni tonalità grigia o grossa squama è un segnale d''allarme.","Il tricoloma colombetta al gambo sotto pressione può virare al blu-verdastro/rosa, ma rimane nel complesso bianco-serico; il tricoloma tigrato è grigio sin dalla base e squamoso-screziato.","Il tricoloma tigrato provoca una sindrome gastrointestinale grave (vomito/diarrea dopo 15-30 min) — in caso di tonalità grigia o squame, non considerarlo mai tricoloma colombetta."}',false),
('tricholoma_portentosum','tricholoma_equestre','en','The man-on-horseback (Tricholoma equestre) is yellowish throughout, especially the sulphur-yellow gills; the dingy/grey tricholoma (Tricholoma portentosum) is grey with black radial fibrils and pale, when-young white gills.','Both mild, mealy to cucumber-like — the smell does NOT distinguish them reliably.','Both under pines/Scots pines on poor sandy soils — hence a high risk of confusion; the site does not separate them.','Both white spore print — no distinguishing feature.','Avoid every yellowish tricholoma with sulphur-yellow gills from the pinewood — the man-on-horseback, despite its former edible status, is today classified as toxic because of documented fatal muscle-breakdown poisonings.','{"Man-on-horseback (toxic): gills and stem flesh conspicuously sulphur- to lemon-yellow; dingy tricholoma (edible): gills white when young, at most faintly tinged yellow-green with age, never deep sulphur-yellow.","Man-on-horseback cap yellowish-olive-brown with a distinct yellow ground tone; dingy tricholoma silver-grey with black radial fibrous streaks, often with a lilac/greenish sheen.","Both grow under pines on sandy soil — the site is NOT a distinguishing feature; gill and stem colour are decisive.","The man-on-horseback can, with repeated consumption of larger amounts (several meals within a few days), trigger rhabdomyolysis (muscle breakdown) — in 2001 in France 12 cases, 3 deaths; classified as toxic for this reason and protected in some countries."}',false),
('tricholoma_portentosum','tricholoma_equestre','es','El tricoloma ecuestre (Tricholoma equestre) enteramente amarillento, sobre todo las láminas amarillo azufre; el tricoloma portentoso gris con fibrillas radiales negras y láminas pálidas, blancas de joven.','Ambos suaves, harinosos hasta olor a pepino — el olor NO los distingue de forma fiable.','Ambos bajo pinos/silvestres en suelos arenosos pobres — de ahí un alto riesgo de confusión; el lugar no los separa.','Ambos esporada blanca — ningún criterio de distinción.','Evitar todo tricoloma amarillento con láminas amarillo azufre del pinar — el tricoloma ecuestre, pese a su antiguo estatus de comestible, hoy está clasificado como tóxico debido a envenenamientos mortales documentados por destrucción muscular.','{"Tricoloma ecuestre (tóxico): láminas y carne del pie claramente amarillo azufre hasta amarillo limón; tricoloma portentoso (comestible): láminas blancas de joven, con la edad a lo sumo débilmente teñidas de amarillo-verde, nunca de un amarillo azufre intenso.","Sombrero del tricoloma ecuestre amarillento-pardo oliva con un claro fondo amarillo; tricoloma portentoso gris plateado con estrías fibrosas radiales negras, a menudo con un reflejo lila/verdoso.","Ambos crecen bajo pinos en suelo arenoso — el lugar NO es un criterio de distinción; el color de las láminas y del pie es determinante.","El tricoloma ecuestre puede, con el consumo repetido de grandes cantidades (varias comidas en pocos días), desencadenar una rabdomiólisis (destrucción muscular) — en 2001 en Francia 12 casos, 3 muertes; clasificado por ello como tóxico y protegido en algunos países."}',false),
('tricholoma_portentosum','tricholoma_equestre','fr','Le tricholome équestre (bidaou) entièrement jaunâtre, surtout les lames jaune soufre ; le tricholome prétentieux gris à fibrilles radiales noires et lames pâles, blanches dans la jeunesse.','Tous deux doux, farineux à odeur de concombre — l''odeur ne les distingue PAS de façon fiable.','Tous deux sous pins/sylvestres sur sols sableux pauvres — d''où un fort risque de confusion ; le site ne les sépare pas.','Tous deux sporée blanche — aucun critère de distinction.','Éviter tout tricholome jaunâtre à lames jaune soufre de la pinède — le tricholome équestre, malgré son ancien statut de comestible, est aujourd''hui classé toxique en raison d''empoisonnements mortels documentés par destruction musculaire.','{"Tricholome équestre (toxique) : lames et chair du pied nettement jaune soufre à jaune citron ; tricholome prétentieux (comestible) : lames blanches dans la jeunesse, au plus faiblement teintées de jaune-vert avec l''âge, jamais d''un jaune soufre soutenu.","Chapeau du tricholome équestre jaunâtre-brun olive avec un net fond jaune ; tricholome prétentieux gris argenté avec des stries fibreuses radiales noires, souvent avec un reflet lilas/verdâtre.","Tous deux poussent sous les pins sur sol sableux — le site n''est PAS un critère de distinction ; la couleur des lames et du pied est déterminante.","Le tricholome équestre peut, en cas de consommation répétée de grandes quantités (plusieurs repas en quelques jours), déclencher une rhabdomyolyse (destruction musculaire) — en 2001 en France 12 cas, 3 décès ; classé de ce fait toxique et protégé dans certains pays."}',false),
('tricholoma_portentosum','tricholoma_equestre','it','Il tricoloma equestre (giallone) interamente giallastro, soprattutto le lamelle giallo zolfo; il tricoloma portentoso grigio con fibrille radiali nere e lamelle pallide, da giovani bianche.','Entrambi dolci, farinosi fino a odore di cetriolo — l''odore NON li distingue in modo affidabile.','Entrambi sotto pini/silvestri su suoli sabbiosi poveri — da cui un alto rischio di confusione; il sito non li separa.','Entrambi sporata bianca — nessun criterio di distinzione.','Evitare ogni tricoloma giallastro con lamelle giallo zolfo del bosco di pini — il tricoloma equestre, nonostante il suo precedente status di commestibile, è oggi classificato come tossico a causa di documentati avvelenamenti mortali per disgregazione muscolare.','{"Tricoloma equestre (tossico): lamelle e carne del gambo nettamente giallo zolfo fino a giallo limone; tricoloma portentoso (commestibile): lamelle da giovani bianche, con l''età al più debolmente sfumate di giallo-verde, mai di un giallo zolfo intenso.","Cappello del tricoloma equestre giallastro-bruno olivaceo con un netto fondo giallo; tricoloma portentoso grigio argenteo con striature fibrose radiali nere, spesso con un riflesso lilla/verdastro.","Entrambi crescono sotto i pini su suolo sabbioso — il sito NON è un criterio di distinzione; il colore delle lamelle e del gambo è determinante.","Il tricoloma equestre può, in caso di consumo ripetuto di grandi quantità (più pasti in pochi giorni), scatenare una rabdomiolisi (disgregazione muscolare) — nel 2001 in Francia 12 casi, 3 decessi; classificato perciò come tossico e protetto in alcuni Paesi."}',false),
('tricholoma_portentosum','tricholoma_pardinum','en','The tiger tricholoma is coarsely scaly-patterned/felty with a covering of scales; the dingy tricholoma is smooth with fine black radial fibrils, no covering of scales.','Both mealy/cucumber-like — the smell does not separate them and must not be used for identification.','The tiger tricholoma prefers calcareous mountain forests under beech/spruce; the dingy tricholoma under pines on acidic sandy soils.','Both white spore print — no distinguishing feature.','Always leave behind grey tricholomas with a coarsely scaly-patterned cap surface — the tiger tricholoma is one of the most frequent causes of severe mushroom poisoning in Central Europe.','{"The tiger tricholoma has a coarsely scaly-patterned, felty cap surface with dark-grey scales on a lighter ground; the dingy tricholoma has a smooth, radially fibrillose cap surface, greasy when wet, WITHOUT coarse scales.","Tiger tricholoma often more robust/larger (cap up to 15 cm) with a thick stem; dingy tricholoma slenderer with a grey-fibrous cap, often with a lilac/greenish tone.","Tiger tricholoma readily grows in mountain forests on lime under beech/spruce; dingy tricholoma typically under pines on acidic sand.","The tiger tricholoma causes a violent gastrointestinal syndrome (vomiting/diarrhoea already after 15-30 min), severe poisonings are possible; even a spat-out taste test can trigger symptoms."}',false),
('tricholoma_portentosum','tricholoma_pardinum','es','Tricoloma atigrado groseramente escamoso-jaspeado/afieltrado con un revestimiento de escamas; tricoloma portentoso liso con finas fibrillas radiales negras, sin revestimiento de escamas.','Ambos harinosos/a pepino — el olor no los separa y no debe usarse para la identificación.','Tricoloma atigrado prefiere los bosques montanos calcáreos bajo haya/pícea; tricoloma portentoso bajo pinos en suelos arenosos ácidos.','Ambos esporada blanca — ningún criterio de distinción.','Dejar siempre en el sitio los tricolomas grises con superficie del sombrero groseramente escamosa-jaspeada — el tricoloma atigrado es uno de los más frecuentes causantes de intoxicaciones graves por setas de Europa central.','{"El tricoloma atigrado tiene una superficie del sombrero groseramente escamosa-jaspeada, afieltrada, con escamas gris oscuro sobre fondo más claro; el tricoloma portentoso tiene una superficie del sombrero lisa, fibrillosa radialmente, viscosa con la humedad, SIN escamas grandes.","Tricoloma atigrado a menudo más robusto/grande (sombrero hasta 15 cm) con pie grueso; tricoloma portentoso más esbelto con sombrero gris-fibroso, a menudo con una tonalidad lila/verdosa.","Tricoloma atigrado crece de buena gana en bosques montanos sobre caliza bajo haya/pícea; tricoloma portentoso típicamente bajo pinos sobre arena ácida.","El tricoloma atigrado provoca un violento síndrome gastrointestinal (vómitos/diarrea ya tras 15-30 min), son posibles intoxicaciones graves; incluso una prueba de sabor escupida puede desencadenar molestias."}',false),
('tricholoma_portentosum','tricholoma_pardinum','fr','Tricholome tigré grossièrement écailleux-tacheté/feutré avec un revêtement d''écailles ; tricholome prétentieux lisse avec de fines fibrilles radiales noires, sans revêtement d''écailles.','Tous deux farineux/concombre — l''odeur ne les sépare pas et ne doit pas servir à l''identification.','Tricholome tigré préfère les forêts de montagne calcaires sous hêtre/épicéa ; tricholome prétentieux sous les pins sur sols sableux acides.','Tous deux sporée blanche — aucun critère de distinction.','Laisser systématiquement sur place les tricholomes gris à surface du chapeau grossièrement écailleuse-tachetée — le tricholome tigré est l''un des plus fréquents responsables d''intoxications graves par champignons d''Europe centrale.','{"Le tricholome tigré a une surface du chapeau grossièrement écailleuse-tachetée, feutrée, avec des écailles gris foncé sur fond plus clair ; le tricholome prétentieux a une surface du chapeau lisse, à fibrilles radiales, visqueuse par temps humide, SANS grosses écailles.","Tricholome tigré souvent plus robuste/grand (chapeau jusqu''à 15 cm) à pied épais ; tricholome prétentieux plus élancé à chapeau gris-fibreux, souvent avec une tonalité lilas/verdâtre.","Tricholome tigré pousse volontiers en forêts de montagne sur calcaire sous hêtre/épicéa ; tricholome prétentieux typiquement sous les pins sur sable acide.","Le tricholome tigré provoque un violent syndrome gastro-intestinal (vomissements/diarrhée dès 15-30 min), des intoxications graves sont possibles ; même un test gustatif recraché peut déclencher des troubles."}',false),
('tricholoma_portentosum','tricholoma_pardinum','it','Tricoloma tigrato grossolanamente squamoso-screziato/feltroso con un rivestimento di squame; tricoloma portentoso liscio con fini fibrille radiali nere, senza rivestimento di squame.','Entrambi farinosi/cetriolo — l''odore non li separa e non deve essere usato per l''identificazione.','Tricoloma tigrato predilige i boschi montani calcarei sotto faggio/abete rosso; tricoloma portentoso sotto i pini su suoli sabbiosi acidi.','Entrambi sporata bianca — nessun criterio di distinzione.','Lasciare sempre sul posto i tricolomi grigi con superficie del cappello grossolanamente squamosa-screziata — il tricoloma tigrato è uno dei più frequenti responsabili di gravi intossicazioni da funghi dell''Europa centrale.','{"Il tricoloma tigrato ha una superficie del cappello grossolanamente squamosa-screziata, feltrosa, con squame grigio scuro su fondo più chiaro; il tricoloma portentoso ha una superficie del cappello liscia, fibrillosa radialmente, viscida con l''umidità, SENZA grosse squame.","Tricoloma tigrato spesso più robusto/grande (cappello fino a 15 cm) con gambo spesso; tricoloma portentoso più slanciato con cappello grigio-fibroso, spesso con una tonalità lilla/verdastra.","Tricoloma tigrato cresce volentieri in boschi montani su calcare sotto faggio/abete rosso; tricoloma portentoso tipicamente sotto i pini su sabbia acida.","Il tricoloma tigrato provoca una violenta sindrome gastrointestinale (vomito/diarrea già dopo 15-30 min), sono possibili gravi intossicazioni; già una prova di sapore sputata può scatenare disturbi."}',false),
('tricholoma_portentosum','tricholoma_saponaceum','en','portentosum has a moist-greasy cap streaked with black radial fibrils, with at most a faint yellow-green tint; saponaceum is matt, dry and highly variable in colour (grey to grey-/yellow-brown), finely scaly, and its flesh (especially the stem base) reddens when cut.','A soap/washing-lye smell points to saponaceum, mealy-mild to portentosum. WARNING: the soap smell is often faint or absent (especially after rain) — its absence is NOT an all-clear.','saponaceum, a symbiotic fungus, grows in mixed and coniferous forest (Aug-Nov); portentosum mainly under pine/spruce on sandy soil — the habitat does not separate them reliably.','Both have a white spore print — not a distinguishing feature.','Cut the stem base and smell it: reddening flesh and/or a soap/laundry-room smell mean soap knight (Tricholoma saponaceum) — do not eat. Since the soap smell may be missing, only collect grey knights when identification is 100% certain.','{"Soap knight (mildly toxic): typical SOAP/washing-powder smell — but NOT always present (often faint, almost absent after heavy rain), therefore not a sole criterion.","Soap knight: the flesh often turns slightly reddish when injured, especially at the stem base; taste unpleasantly bitter-mealy.","Sticky knight (edible): mealy-mild smell, NO distinct reddening of the flesh; cap moist greasy with black radial fibrils.","Soap knight cap very variable, grey to grey-/yellow-brown, finely scaly, matt — WITHOUT the greasy slimy sheen of portentosum; stem often spindle-shaped/twisted.","When in doubt, cut test at the stem base + smell test: reddening stem flesh and/or a soap/washing-lye smell are clear warning signs against consumption."}',false),
('tricholoma_portentosum','tricholoma_saponaceum','es','portentosum tiene un sombrero húmedo-viscoso, surcado de fibrillas radiales negras, con a lo sumo un leve tono amarillo-verde; saponaceum es mate, seco y muy variable en color (del gris al gris-/amarillo-pardo), finamente escamoso, y su carne (sobre todo en la base del pie) enrojece al corte.','Un olor a jabón/a lejía apunta a saponaceum, harinoso-suave a portentosum. ATENCIÓN: el olor a jabón a menudo es débil o está ausente (sobre todo tras la lluvia) — su ausencia NO es una señal de vía libre.','saponaceum, hongo simbionte, crece en bosque mixto y de coníferas (ago-nov); portentosum sobre todo bajo pino/abeto rojo en suelo arenoso — la estación no los separa con seguridad.','Ambos tienen esporada blanca — no es un rasgo distintivo.','Cortar la base del pie y olerla: carne que enrojece y/o un olor a jabón/a lavadero significan tricholoma jabonoso (Tricholoma saponaceum) — no comer. Como el olor a jabón puede faltar, recolectar los tricholomas grises solo con identificación 100% segura.','{"Tricholoma jabonoso (ligeramente tóxico): olor típico a JABÓN/a detergente — pero NO siempre presente (a menudo débil, casi ausente tras lluvia intensa), por lo tanto no un criterio único.","Tricholoma jabonoso: la carne suele virar algo al rojizo al herirse, sobre todo en la base del pie; sabor desagradablemente amargo-harinoso.","Tricholoma portentosum (comestible): olor harinoso-suave, NINGÚN enrojecimiento neto de la carne; sombrero húmedo viscoso con fibrillas radiales negras.","Sombrero del tricholoma jabonoso muy variable, del gris al gris-/amarillo-pardo, finamente escamoso, mate — SIN el brillo viscoso y gelatinoso de portentosum; pie a menudo fusiforme/retorcido.","En caso de duda, prueba de corte en la base del pie + prueba olfativa: carne del pie que enrojece y/o olor a jabón/a lejía son señales de alarma claras contra el consumo."}',false),
('tricholoma_portentosum','tricholoma_saponaceum','fr','portentosum a un chapeau humide-visqueux, strié de fibrilles radiales noires, avec tout au plus une faible teinte jaune-vert ; saponaceum est mat, sec et très variable en couleur (du gris au gris-/jaune-brun), finement squameux, et sa chair (surtout à la base du pied) rougit à la coupe.','Une odeur de savon/de lessive plaide pour saponaceum, farineuse-douce pour portentosum. ATTENTION : l''odeur de savon est souvent faible ou absente (surtout après la pluie) — son absence N''EST PAS un feu vert.','saponaceum, champignon symbiotique, pousse en forêt mixte et de conifères (août-nov.) ; portentosum surtout sous pin/épicéa sur sol sableux — la station ne sépare pas de façon sûre.','Les deux ont une sporée blanche — pas un critère de distinction.','Couper la base du pied et sentir : une chair qui rougit et/ou une odeur de savon/de buanderie signifient tricholome à odeur de savon — ne pas manger. Comme l''odeur de savon peut manquer, ne récolter les tricholomes gris que si l''identification est sûre à 100 %.','{"Tricholome à odeur de savon (légèrement toxique) : odeur typique de SAVON/de lessive — mais PAS toujours présente (souvent faible, presque absente après une forte pluie), donc non un critère unique.","Tricholome à odeur de savon : la chair vire souvent légèrement au rougeâtre à la blessure, surtout à la base du pied ; goût désagréablement amer-farineux.","Tricholome prétentieux (comestible) : odeur farineuse-douce, AUCUN rougissement net de la chair ; chapeau humide visqueux avec fibrilles radiales noires.","Chapeau du tricholome à odeur de savon très variable, du gris au gris-/jaune-brun, finement squameux, mat — SANS l''éclat visqueux et gluant de portentosum ; pied souvent fusiforme/tordu.","En cas de doute, test de coupe à la base du pied + test olfactif : une chair du pied qui rougit et/ou une odeur de savon/de lessive sont des signaux d''alarme nets contre la consommation."}',false),
('tricholoma_portentosum','tricholoma_saponaceum','it','portentosum ha un cappello umido-viscido, striato di fibrille radiali nere, con tutt''al più una debole tonalità giallo-verde; saponaceum è opaco, asciutto e molto variabile nel colore (dal grigio al grigio-/giallo-bruno), finemente squamoso, e la sua carne (soprattutto alla base del gambo) arrossa al taglio.','Un odore di sapone/di lisciva depone per saponaceum, farinoso-mite per portentosum. ATTENZIONE: l''odore di sapone è spesso debole o assente (soprattutto dopo la pioggia) — la sua assenza NON è un via libera.','saponaceum, fungo simbionte, cresce in boschi misti e di conifere (ago-nov); portentosum soprattutto sotto pino/abete rosso su terreno sabbioso — la stazione non distingue con sicurezza.','Entrambi hanno sporata bianca — non un carattere distintivo.','Tagliare la base del gambo e annusare: carne che arrossa e/o odore di sapone/di lavanderia indicano il tricholoma saponaceo — non mangiare. Poiché l''odore di sapone può mancare, raccogliere i tricholomi grigi solo con identificazione sicura al 100%.','{"Tricholoma saponaceo (leggermente tossico): tipico odore di SAPONE/di detersivo — ma NON sempre presente (spesso debole, quasi assente dopo forti piogge), quindi non un criterio unico.","Tricholoma saponaceo: la carne vira spesso un po'' al rossastro alla lesione, soprattutto alla base del gambo; sapore sgradevolmente amaro-farinoso.","Tricholoma portentosum (commestibile): odore farinoso-mite, NESSUN netto arrossamento della carne; cappello umido viscido con fibrille radiali nere.","Cappello del tricholoma saponaceo molto variabile, dal grigio al grigio-/giallo-bruno, finemente squamoso, opaco — SENZA la lucentezza viscida e gelatinosa di portentosum; gambo spesso fusiforme/contorto.","In caso di dubbio, prova di taglio alla base del gambo + prova olfattiva: carne del gambo che arrossa e/o odore di sapone/di lisciva sono chiari segnali d''allarme contro il consumo."}',false),
('tricholoma_portentosum','tricholoma_terreum','en','The sticky/dingy knight (Tricholoma portentosum) has a moist-greasy (slimy) cap with ingrown black radial fibrils and at most a faint yellow-green tint; the grey knight (Tricholoma terreum) is dry, finely felty-scaly and pure mouse-grey. The slimy cap in damp weather is the most striking distinguishing feature.','portentosum is mildly mealy; terreum is almost odourless. A strong mealy smell on a grey knight is NOT an all-clear — it also fits the deadly tiger knight.','Both grow under conifers (especially pine, also spruce) on rather sandy, lime-poor soils in autumn; the habitat does NOT separate them reliably.','Both have a white spore print — not usable as a distinguishing feature.','Grey knights are a beginner''s taboo: this colour group contains several toxic to deadly species (incl. the tiger knight T. pardinum). Only collect if the greasy cap WITH black radial fibrils is unambiguously identified and any suspicion of coarse scales/robust growth has been ruled out — when in doubt, leave it standing.','{"Black-fibrilled/sticky knight (edible): cap grey to grey-white with ingrown black RADIAL FIBRILS, distinctly greasy-sticky in damp weather (slimy cap), often a faint yellow-greenish sheen at the cap margin/bruised spots.","Grey knight (listed here as toxic): cap mouse-grey, finely FELTY-SCALY (not radially fibrilled, never greasy), dry and matt, without yellow-green tint.","portentosum flesh/gills can show a faint yellow-greenish tone (especially on pressure/cut) — do NOT use as the sole safety feature, as it is variable; terreum stays purely grey.","portentosum smells/tastes mealy-mild; terreum is practically odourless and mild.","WARNING life-threatening danger in the grey knight group: the deadly poisonous tiger knight (T. pardinum) looks similar (mealy smell, coarse tile-like scales, robust growth) — at any doubt, leave ALL grey knights standing."}',false),
('tricholoma_portentosum','tricholoma_terreum','es','El tricholoma portentosum tiene un sombrero húmedo-viscoso (gelatinoso) con fibrillas radiales negras incrustadas y a lo sumo un leve tono amarillo-verde; el tricholoma terreum es seco, finamente afieltrado-escamoso y de un gris ratón puro. El sombrero viscoso con la humedad es el rasgo distintivo más llamativo.','portentosum es de olor harinoso suave; terreum es casi inodoro. Un fuerte olor harinoso en un tricholoma gris NO es una señal de vía libre — también encaja con el tricholoma atigrado, mortal.','Ambos crecen bajo coníferas (sobre todo pino, también abeto rojo), en suelos más bien arenosos y pobres en cal, en otoño; la estación NO los separa de forma fiable.','Ambos tienen esporada blanca — no utilizable como rasgo distintivo.','Los tricholomas grises son un tabú para principiantes: en este grupo cromático figuran varias especies de tóxicas a mortales (incl. el tricholoma atigrado T. pardinum). Recolectar solo si el sombrero viscoso CON fibrillas radiales negras está identificado sin ambigüedad y se ha descartado toda sospecha de escamas gruesas/porte robusto — en caso de duda, dejar en el sitio.','{"Tricholoma de fibrillas negras/portentosum (comestible): sombrero gris a gris-blanco con FIBRILLAS RADIALES negras incrustadas, claramente viscoso-pegajoso con la humedad (sombrero gelatinoso), a menudo un leve brillo amarillo-verdoso en el borde del sombrero/zonas magulladas.","Tricholoma terreum (aquí clasificado como tóxico): sombrero gris ratón, finamente AFIELTRADO-ESCAMOSO (no radial-fibrilloso, nunca viscoso), seco y mate, sin tono amarillo-verde.","La carne/las láminas de portentosum pueden mostrar un leve tono amarillo-verdoso (sobre todo a la presión/al corte) — NO usar como único rasgo de seguridad, pues es variable; terreum permanece puramente gris.","portentosum huele/sabe harinoso-suave; terreum es prácticamente inodoro y suave.","ATENCIÓN peligro de muerte en el grupo de los tricholomas grises: el tricholoma atigrado mortal (T. pardinum) se le parece (olor harinoso, escamas gruesas en forma de tejas, porte robusto) — ante cualquier duda, dejar TODOS los tricholomas grises en el sitio."}',false),
('tricholoma_portentosum','tricholoma_terreum','fr','Le tricholome prétentieux a un chapeau humide-visqueux (gluant) avec des fibrilles radiales noires incluses et tout au plus une faible teinte jaune-vert ; le tricholome terreux est sec, finement feutré-squameux et d''un gris souris pur. Le chapeau visqueux par temps humide est le critère de distinction le plus marquant.','portentosum a une odeur farineuse douce ; terreum est presque inodore. Une forte odeur farineuse chez un tricholome gris N''EST PAS un feu vert — elle correspond aussi au tricholome tigré, mortel.','Les deux poussent sous les conifères (surtout pin, aussi épicéa), sur des sols plutôt sableux et pauvres en calcaire, en automne ; la station NE sépare PAS de façon fiable.','Les deux ont une sporée blanche — inutilisable comme critère de distinction.','Les tricholomes gris sont un tabou pour les débutants : dans ce groupe de couleur figurent plusieurs espèces toxiques à mortelles (dont le tricholome tigré T. pardinum). Ne récolter que si le chapeau visqueux AVEC fibrilles radiales noires est identifié sans ambiguïté et que tout soupçon de grosses squames/port robuste est écarté — en cas de doute, laisser sur place.','{"Tricholome à fibrilles noires/prétentieux (comestible) : chapeau gris à gris-blanc avec des FIBRILLES RADIALES noires incluses, nettement visqueux-collant par temps humide (chapeau gluant), souvent un faible reflet jaune-verdâtre au bord du chapeau/aux endroits meurtris.","Tricholome terreux (ici classé comme toxique) : chapeau gris souris, finement FEUTRÉ-SQUAMEUX (non radial-fibrilleux, jamais visqueux), sec et mat, sans teinte jaune-vert.","La chair/les lamelles de portentosum peuvent montrer une faible teinte jaune-verdâtre (surtout à la pression/coupe) — à NE PAS utiliser comme seul critère de sécurité, car variable ; terreum reste purement gris.","portentosum sent/a un goût farineux-doux ; terreum est pratiquement inodore et doux.","ATTENTION danger de mort dans le groupe des tricholomes gris : le tricholome tigré mortel (T. pardinum) lui ressemble (odeur farineuse, grosses squames en tuiles, port robuste) — au moindre doute, laisser TOUS les tricholomes gris sur place."}',false),
('tricholoma_portentosum','tricholoma_terreum','it','Il tricholoma portentosum ha un cappello umido-viscido (gelatinoso) con fibrille radiali nere incluse e tutt''al più una debole tonalità giallo-verde; il tricholoma terreum è asciutto, finemente feltroso-squamoso e di un grigio topo puro. Il cappello viscido con l''umidità è il carattere distintivo più evidente.','portentosum ha odore farinoso mite; terreum è quasi inodore. Un forte odore farinoso in un tricholoma grigio NON è un via libera — è compatibile anche con il tricholoma tigrato, mortale.','Entrambi crescono sotto le conifere (soprattutto pino, anche abete rosso), su terreni piuttosto sabbiosi e poveri di calcare, in autunno; la stazione NON distingue in modo affidabile.','Entrambi hanno sporata bianca — non utilizzabile come carattere distintivo.','I tricholomi grigi sono un tabù per i principianti: in questo gruppo cromatico figurano diverse specie da tossiche a mortali (incluso il tricholoma tigrato T. pardinum). Raccogliere solo se il cappello viscido CON fibrille radiali nere è identificato con certezza e ogni sospetto di grosse squame/portamento robusto è escluso — in caso di dubbio, lasciare sul posto.','{"Tricholoma a fibrille nere/portentosum (commestibile): cappello da grigio a grigio-bianco con FIBRILLE RADIALI nere incluse, nettamente viscido-appiccicoso con l''umidità (cappello gelatinoso), spesso un debole riflesso giallo-verdastro al bordo del cappello/nei punti ammaccati.","Tricholoma terreum (qui classificato come tossico): cappello grigio topo, finemente FELTROSO-SQUAMOSO (non radial-fibrilloso, mai viscido), asciutto e opaco, senza tonalità giallo-verde.","La carne/le lamelle di portentosum possono mostrare una debole tonalità giallo-verdastra (soprattutto alla pressione/al taglio) — da NON usare come unico carattere di sicurezza, poiché variabile; terreum resta puramente grigio.","portentosum ha odore/sapore farinoso-mite; terreum è praticamente inodore e mite.","ATTENZIONE pericolo di morte nel gruppo dei tricholomi grigi: il tricholoma tigrato mortale (T. pardinum) gli assomiglia (odore farinoso, grosse squame embricate, portamento robusto) — al minimo dubbio, lasciare TUTTI i tricholomi grigi sul posto."}',false),
('zigeunerpilz','cortinarius_splendens','en','Bright yellow = warning sign: any webcap (Cortinarius) that is uniformly sulphur/bright yellow is off-limits — the edible gypsy mushroom (Cortinarius caperatus) is dull greyish-ochre-brownish with a frosted cap and a membranous ring.','The gypsy mushroom smells pleasantly mushroomy; Cortinarius splendens is inconspicuous to slightly radish-like — smell does NOT reliably separate them.','The gypsy mushroom grows in acidic coniferous/mixed forests and bilberry stands; the splendid webcap (Cortinarius splendens), a mycorrhizal fungus, grows in calcareous broadleaf forests, typically with beech.','Both have a rust-brown spore print — therefore NO distinguishing criterion. Rely on cap colour (bright yellow!), a true membranous ring and a marginate yellow bulb.','No webcap (Cortinarius) with a rusty spore print for beginners — always leave bright yellow club-footed webcaps standing. The kidney toxin only acts after several days; the poisoning goes unnoticed at first. When in doubt, mushroom inspection (VAPKO).','{"Gypsy mushroom (Cortinarius caperatus): cap greyish-brown/ochreous with a whitish frosted sheen, NOT bright yellow — Cortinarius splendens: strong sulphur to bright yellow throughout.","The gypsy mushroom has a true membranous stem ring; the splendid webcap has only a fleeting yellow cortina (cobweb veil), NO firm membranous ring.","Cortinarius splendens has a marginate yellow bulb and yellow flesh; the gypsy mushroom has a faintly bulbous base without bright yellow.","The splendid webcap contains a nephrotoxic poison (orellanine-syndrome type, not yet definitively identified chemically — NOT necessarily orellanine itself) and can cause fatal kidney failure with a latency of days to weeks.","The gypsy mushroom grows in acidic coniferous/mixed forest and bilberry stands; C. splendens, a mycorrhizal fungus, prefers calcareous broadleaf forests (especially with beech)."}',false),
('zigeunerpilz','cortinarius_splendens','es','Amarillo brillante = señal de alarma: todo cortinario (Cortinarius) uniformemente amarillo azufre/amarillo vivo está prohibido — la seta comestible (Cortinarius caperatus) es mate, gris-ocre-parduzca, con sombrero pruinoso y anillo membranoso.','Cortinarius caperatus huele agradablemente a hongo; Cortinarius splendens es inodoro o ligeramente rafanoide (a rábano) — el olor NO los separa de forma fiable.','Cortinarius caperatus crece en bosques ácidos de coníferas/mixtos y en arandaneras; el cortinario espléndido (Cortinarius splendens), hongo micorrízico, crece en bosques calcáreos de frondosas, típicamente bajo el haya.','Ambos tienen esporada pardo-herrumbre — por lo tanto NINGÚN criterio de separación. Fiarse del color del sombrero (¡amarillo vivo!), del verdadero anillo membranoso y del bulbo amarillo marginado.','Ningún cortinario (Cortinarius) con esporada herrumbre para principiantes — dejar siempre en el sitio los cortinarios de pie bulboso amarillo brillante. El veneno renal actúa solo tras varios días; la intoxicación pasa inadvertida al principio. En caso de duda, control de setas (VAPKO).','{"Cortinarius caperatus: sombrero gris-parduzco/ocráceo con un brillo pruinoso blanquecino, NO amarillo vivo — Cortinarius splendens: amarillo azufre a amarillo vivo intenso en todas sus partes.","Cortinarius caperatus posee un verdadero anillo membranoso en el pie; el cortinario espléndido solo tiene una cortina amarilla fugaz (velo aracnoideo), NINGÚN anillo membranoso firme.","Cortinarius splendens presenta un bulbo amarillo marginado y carne amarilla; Cortinarius caperatus tiene una base débilmente bulbosa sin amarillo brillante.","El cortinario espléndido contiene un veneno nefrotóxico (de tipo síndrome orellánico, aún no identificado químicamente de forma definitiva — NO necesariamente la orellanina misma) y puede provocar una insuficiencia renal mortal con una latencia de días a semanas.","Cortinarius caperatus crece en bosques ácidos de coníferas/mixtos y en arandaneras; C. splendens, hongo micorrízico, prefiere los bosques calcáreos de frondosas (especialmente bajo el haya)."}',false),
('zigeunerpilz','cortinarius_splendens','fr','Jaune éclatant = signal d''alarme : tout cortinaire entièrement jaune soufre/jaune vif est à proscrire — le rozite comestible est terne, gris-ocre-brunâtre, avec un chapeau pruineux et un anneau membraneux.','Le rozite a une odeur agréable, fongique ; Cortinarius splendens est inodore à légèrement raphanoïde (de radis) — l''odeur ne sépare PAS de façon fiable.','Le rozite pousse dans les forêts de conifères/mixtes acides et les peuplements de myrtilles ; le cortinaire splendide (Cortinarius splendens), champignon mycorhizien, pousse dans les forêts feuillues calcaires, typiquement sous le hêtre.','Les deux ont une sporée brun-rouille — donc AUCUN critère de séparation. Se fier à la couleur du chapeau (jaune vif !), au véritable anneau membraneux et au bulbe jaune marginé.','Aucun cortinaire (Cortinarius) à sporée rouille pour les débutants — laisser systématiquement sur place les cortinaires à bulbe jaune vif. Le poison rénal n''agit qu''après plusieurs jours, l''intoxication passe d''abord inaperçue. En cas de doute, contrôle des champignons (VAPKO).','{"Rozite/Pholiote ridée (Cortinarius caperatus) : chapeau gris-brunâtre/ocré avec un reflet pruineux blanchâtre, PAS jaune vif — Cortinarius splendens : jaune soufre à jaune vif intense dans toutes ses parties.","Le rozite possède un véritable anneau membraneux sur le pied ; le cortinaire splendide n''a qu''une cortine jaune fugace (voile arachnéen), AUCUN anneau membraneux ferme.","Cortinarius splendens présente un bulbe jaune marginé et une chair jaune ; le rozite a une base faiblement bulbeuse sans jaune éclatant.","Le cortinaire splendide contient un poison néphrotoxique (de type syndrome orellanien, encore non identifié chimiquement de façon définitive — PAS forcément l''orellanine elle-même) et peut provoquer une insuffisance rénale mortelle avec une latence de plusieurs jours à plusieurs semaines.","Le rozite pousse dans les forêts de conifères/mixtes acides et les peuplements de myrtilles ; C. splendens, champignon mycorhizien, préfère les forêts feuillues calcaires (surtout sous le hêtre)."}',false),
('zigeunerpilz','cortinarius_splendens','it','Giallo brillante = segnale d''allarme: ogni cortinario interamente giallo zolfo/giallo vivo è da evitare — il rozites commestibile è opaco, grigio-ocra-brunastro, con cappello pruinoso e anello membranoso.','Il rozites ha odore aromatico-fungino; Cortinarius splendens è inodore o leggermente rafanoide (di ravanello) — l''odore NON distingue in modo affidabile.','Il rozites cresce nei boschi acidi di conifere/misti e nelle brughiere a mirtillo; il cortinario splendente (Cortinarius splendens), fungo micorrizico, cresce nei boschi di latifoglie calcarei, tipicamente sotto il faggio.','Entrambi hanno sporata bruno-ruggine — quindi NESSUN criterio di distinzione. Affidarsi al colore del cappello (giallo vivo!), al vero anello membranoso e al bulbo giallo marginato.','Nessun cortinario (Cortinarius) con sporata ruggine per i principianti — lasciare sempre sul posto i cortinari con bulbo giallo brillante. Il veleno renale agisce solo dopo giorni, l''avvelenamento inizialmente passa inosservato. In caso di dubbio, controllo dei funghi (VAPKO).','{"Rozites/Pholiota raggrinzita (Cortinarius caperatus): cappello grigio-brunastro/ocraceo con riflesso pruinoso biancastro, NON giallo vivo — Cortinarius splendens: giallo zolfo o giallo vivo intenso in tutte le parti.","Il rozites possiede un vero anello membranoso sul gambo; il cortinario splendente ha solo una cortina gialla fugace (velo ragnateloso), NESSUN anello membranoso solido.","Cortinarius splendens presenta un bulbo giallo marginato e carne gialla; il rozites ha una base debolmente bulbosa senza giallo brillante.","Il cortinario splendente contiene un veleno nefrotossico (di tipo sindrome orellanica, ancora non identificato chimicamente in modo definitivo — NON necessariamente l''orellanina stessa) e può provocare un''insufficienza renale mortale con latenza da giorni a settimane.","Il rozites nei boschi acidi di conifere/misti e nelle brughiere a mirtillo; C. splendens, fungo micorrizico, predilige i boschi di latifoglie calcarei (soprattutto sotto il faggio)."}',false)
